/* ================= language engine (English / Arabic) ================= */
const LANG_KEY='akam-lang';
let LANG=(()=>{try{return localStorage.getItem(LANG_KEY)}catch(e){return null}})()==='ar'?'ar':'en';
const isAR=()=>LANG==='ar';
const LOC=()=>isAR()?'ar-KW-u-nu-latn':'en-GB';
const AR_EXTRA=[
 [/^(Good morning|Good afternoon|Good evening), (.+)$/,m=>AR[m[1]]+'، '+m[2]],
 [/^(-?)(\d+)d (\d+)h$/,m=>m[1]+m[2]+'ي '+m[3]+'س'],[/^(-?)(\d+)h (\d+)m$/,m=>m[1]+m[2]+'س '+m[3]+'د'],[/^(-?)(\d+)m$/,m=>m[1]+m[2]+'د'],[/^(-?)(\d+)h$/,m=>m[1]+m[2]+'س'],
 [/^(.+) \((\d+)\)$/,m=>{const t=trCore(m[1]);return t==null?null:t+' ('+m[2]+')'}],
 [/^(.+)…$/,m=>{const t=trCore(m[1]);return t==null?null:t+'…'}],[/^(.+):$/,m=>{const t=trCore(m[1]);return t==null?null:t+':'}],[/^(.+)\.$/,m=>{const t=trCore(m[1]);return t==null?null:t+'.'}]];
const trCache=new Map();
function trCore(s){
  if(!s)return null;if(trCache.has(s))return trCache.get(s);
  let r=null;
  if(Object.prototype.hasOwnProperty.call(AR,s))r=AR[s];
  else if(/[A-Za-z]/.test(s)){
    if(s.includes(' · ')){const parts=s.split(' · ');const out=parts.map(p=>{const t=trCore(p.trim());return t==null?p:t});if(out.some((x,i)=>x!==parts[i]))r=out.join(' · ')}
    if(r==null)for(const list of [AR_EXTRA,AR_PAT]){for(const [re,fn] of list){if(!fn)continue;const m=s.match(re);if(m){const v=fn(m);if(v!=null&&v!==s){r=v;break}}}if(r!=null)break}
    if(r==null&&/[.!?] +[A-Z]/.test(s)){const parts=s.split(/(?<=[.!?]) +(?=[A-Z])/);const out=parts.map(p=>{const t=trCore(p);return t==null?p:t});if(out.some((x,i)=>x!==parts[i]))r=out.join(' ')}
    if(r==null){for(const sep of [' · ',' — ',' – ',' / ',', ']){if(s.includes(sep)){const parts=s.split(sep);const out=parts.map(p=>{const t=trCore(p.trim());return t==null?p:t});if(out.some((x,i)=>x!==parts[i])){r=out.join(sep==', '?'، ':sep);break}}}}
  }
  if(r!=null)r=curAR(r);
  if(trCache.size>20000)trCache.clear();trCache.set(s,r);return r}
const curAR=x=>x.replace(/\b(KWD|SAR|AED|QAR|BHD|OMR) (-?[\d,]+(?:\.\d+)?)/g,(_,c,n)=>n+' '+CUR_AR[c]);
function trAR(s){const r=trCore(s);return r==null?s:r}
/* t(): use in code for strings built at runtime (toasts, prompts) */
const tx=s=>isAR()?trAR(s):s;
function trText(raw){const m=raw.match(/^([\s·→—–]*)([\s\S]*?)([\s·→—–]*)$/);const core=m[2];if(!core||!/[A-Za-z]/.test(core))return null;let r=trCore(core);if(r==null&&/\b(KWD|SAR|AED|QAR|BHD|OMR) -?\d/.test(core))r=curAR(core);return r==null?null:m[1].replace(/→/g,'←')+r+m[3].replace(/→/g,'←')}
const SKIP_TAGS={SCRIPT:1,STYLE:1,TEXTAREA:1,CODE:1,PRE:1};
function trNode(root){
  if(!isAR()||!root)return;
  if(root.nodeType===3){trTextNode(root);return}
  if(root.nodeType!==1||SKIP_TAGS[root.tagName]||root.closest&&root.closest('[translate="no"]'))return;
  trAttrs(root);root.querySelectorAll&&root.querySelectorAll('[placeholder],[title],[aria-label],[data-l]').forEach(trAttrs);
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT,{acceptNode:n=>{const p=n.parentNode;return p&&(SKIP_TAGS[p.nodeName]||(p.closest&&p.closest('[translate="no"]')))?NodeFilter.FILTER_REJECT:NodeFilter.FILTER_ACCEPT}});
  const list=[];while(w.nextNode())list.push(w.currentNode);list.forEach(trTextNode)}
function trTextNode(n){const v=n.nodeValue;const r=trText(v);if(r==null||r===v)return;const p=n.parentNode;
  if(p&&p.nodeName==='OPTION'&&!p.hasAttribute('value'))p.setAttribute('value',p.textContent);
  n.nodeValue=r}
function trAttrs(el){for(const a of ['placeholder','title','aria-label','data-l']){const v=el.getAttribute&&el.getAttribute(a);if(v){const r=trText(v);if(r!=null&&r!==v)el.setAttribute(a,r)}}}
let trObs=null;
function trRecs(recs){if(!isAR())return;for(const r of recs){try{if(r.type==='childList')r.addedNodes.forEach(trNode);else if(r.type==='characterData')trTextNode(r.target)}catch(e){console.error('i18n',e&&e.stack||e)}}}
function flushTr(){if(trObs&&isAR())trRecs(trObs.takeRecords())}
function startTranslator(){
  if(trObs||typeof MutationObserver==='undefined')return;
  trObs=new MutationObserver(trRecs);
  trObs.observe(document.body,{childList:true,subtree:true,characterData:true})}
function applyLang(){const h=document.documentElement;h.setAttribute('lang',LANG);h.setAttribute('dir',isAR()?'rtl':'ltr');document.title=isAR()?'الكاظمي لإدارة الأصول':'Alkazemi Asset Management';if(isAR())trNode(document.body)}
function setLang(l){LANG=l==='ar'?'ar':'en';try{localStorage.setItem(LANG_KEY,LANG)}catch(e){}trCache.clear();applyLang()}
const themeBtn=()=>`<button class="iconbtn themebtn" data-act="theme" aria-label="${isDark()?'Switch to light mode':'Switch to dark mode'}" title="${isDark()?'Light mode':'Dark mode'}">${ic(isDark()?'sun':'moon')}</button>`;
const langBtn=(cls)=>`<button class="btn ghost sm langbtn ${cls||''}" data-act="lang" translate="no" aria-label="${isAR()?'Switch to English':'التبديل إلى العربية'}"><span class="lf">${isAR()?'English':'عربي'}</span><span class="ls">${isAR()?'EN':'ع'}</span></button>`;

/* ================= utilities ================= */
function mulberry32(a){return function(){a|=0;a=a+0x6D2B79F5|0;let t=Math.imul(a^a>>>15,1|a);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296}}
let R=mulberry32(20261014);
const ri=(a,b)=>a+Math.floor(R()*(b-a+1));
const pick=a=>a[Math.floor(R()*a.length)];
const MIN=6e4,HOUR=36e5,DAY=864e5;
const TODAY=new Date();TODAY.setHours(0,0,0,0);
const pad=n=>String(n).padStart(2,'0');
const iso=d=>{const x=new Date(d);return x.getFullYear()+'-'+pad(x.getMonth()+1)+'-'+pad(x.getDate())};
const ym=d=>{const x=new Date(d);return x.getFullYear()+'-'+pad(x.getMonth()+1)};
const addD=(d,n)=>new Date(new Date(d).getTime()+n*DAY);
const nowISO=()=>new Date().toISOString();
const daysUntil=s=>s?Math.round((new Date(String(s).length<=10?s+'T00:00:00':s)-TODAY)/DAY):null;
const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const uid=p=>p+'-'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const $=s=>document.querySelector(s);
const $$=s=>[...document.querySelectorAll(s)];
function fmtDate(s){if(!s)return '—';const d=new Date(String(s).length<=10?s+'T00:00:00':s);return d.toLocaleDateString(LOC(),{day:'2-digit',month:'short',year:'numeric'})}
function fmtDT(s){if(!s)return '—';const d=new Date(s);return d.toLocaleDateString(LOC(),{day:'2-digit',month:'short'})+', '+d.toLocaleTimeString(LOC(),{hour:'2-digit',minute:'2-digit'})}
function hm(s){return new Date(s).toLocaleTimeString(LOC(),{hour:'2-digit',minute:'2-digit'})}
function ago(s){const m=(Date.now()-new Date(s))/MIN;if(m<1)return 'just now';if(m<60)return Math.round(m)+' min ago';if(m<1440)return Math.round(m/60)+' h ago';return Math.round(m/1440)+' d ago'}
function dur(ms){const neg=ms<0;ms=Math.abs(ms);const h=Math.floor(ms/HOUR),m=Math.floor(ms%HOUR/MIN);const s=h>=48?Math.floor(h/24)+'d '+(h%24)+'h':h?h+'h '+pad(m)+'m':m+'m';return neg?'-'+s:s}
function hhmm(ms){ms=Math.max(0,ms);const h=Math.floor(ms/HOUR),m=Math.floor(ms%HOUR/MIN);return pad(h)+':'+pad(m)}
function monthLabel(m){const [y,mo]=m.split('-');return new Date(+y,+mo-1,1).toLocaleDateString(LOC(),{month:'long',year:'numeric'})}
function monthShort(m){const [y,mo]=m.split('-');return new Date(+y,+mo-1,1).toLocaleDateString(LOC(),{month:'short'})}
function hijri(d){try{return new Intl.DateTimeFormat(isAR()?'ar-u-ca-islamic-umalqura-nu-latn':'en-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric'}).format(d)}catch(e){return ''}}
const initials=n=>String(n||'').split(/\s+/).map(w=>w.replace(/^Al-/,'')[0]).filter(c=>c&&/[A-Za-z]/.test(c)).slice(0,2).join('').toUpperCase();
const avTone=id=>'t'+(1+(String(id).split('').reduce((a,c)=>a+c.charCodeAt(0),0)%6));
const sum=(a,f)=>a.reduce((s,x)=>s+(f?f(x):x),0);
function toCSV(rows){return rows.map(r=>r.map(c=>{const s=String(c==null?'':c);return /[",\n]/.test(s)?'"'+s.replace(/"/g,'""')+'"':s}).join(',')).join('\n')}
function parseCSV(text){const out=[];let row=[],cell='',q=false;for(let i=0;i<text.length;i++){const c=text[i];if(q){if(c==='"'){if(text[i+1]==='"'){cell+='"';i++}else q=false}else cell+=c}else{if(c==='"')q=true;else if(c===','){row.push(cell);cell=''}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);out.push(row);row=[];cell=''}else cell+=c}}if(cell||row.length){row.push(cell);out.push(row)}return out.filter(r=>r.some(c=>c.trim()))}
function downloadText(name,text,type){try{const b=new Blob([text],{type:type||'text/csv'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);toast('Downloaded '+name)}catch(e){toast('Download is not available in this browser')}}

