const DEC={KWD:3,BHD:3,OMR:3,SAR:2,AED:2,QAR:2};
function money(n,cur){cur=cur||'KWD';return cur+' '+Number(n||0).toLocaleString('en-US',{minimumFractionDigits:DEC[cur],maximumFractionDigits:DEC[cur]})}
function moneyK(n,cur){cur=cur||'KWD';n=Number(n||0);return cur+' '+(Math.abs(n)>=10000?(n/1000).toLocaleString('en-US',{maximumFractionDigits:1})+'k':n.toLocaleString('en-US',{maximumFractionDigits:0}))}
const toKWD=(n,cur)=>(n||0)*FX[cur||'KWD'];

