let S=null;
const ui={view:'dashboard',scope:'',f:{},pending:{},tickMode:'board',reportPeriod:30,rentMonth:ym(TODAY),wiz:{},guardTab:'home',menu:false,navOpen:false,drawer:null,helpId:'start'};
const me=()=>S&&S.users.find(u=>u.id===S.session);
const userById=id=>S.users.find(u=>u.id===id);
const nameOf=id=>{if(id==='system')return 'System';const u=userById(id);return u?u.name:'—'};
const propById=id=>S.props.find(p=>p.id===id);
const unitById=id=>S.units.find(u=>u.id===id);
const tenantById=id=>S.tenants.find(t=>t.id===id);
const ticketById=id=>S.tickets.find(t=>t.id===id);
const itemById=id=>S.items.find(t=>t.id===id);
const vehById=id=>S.vehicles.find(t=>t.id===id);
const setting=k=>(S.settings&&S.settings[k]!==undefined)?S.settings[k]:DEFAULT_SETTINGS[k];
const can=(u,k)=>!!u&&(u.role==='admin'||(u.perms||[]).includes(k));
const scopedRole=u=>u.role==='supervisor'||u.role==='guard';
const propsFor=u=>scopedRole(u)?S.props.filter(p=>(u.props||[]).includes(p.id)):S.props;
function propIds(u){let ids=propsFor(u).map(p=>p.id);if(ui.scope&&ids.includes(ui.scope))ids=[ui.scope];return new Set(ids)}
function ticketsFor(u){const ids=propIds(u);let l=S.tickets.filter(t=>ids.has(t.propId));if(u.role==='tech')l=l.filter(t=>t.techId===u.id);if(u.role==='guard')l=l.filter(t=>t.reporterId===u.id||ids.has(t.propId));return l}
const isOpen=t=>t.status!=='closed'&&t.status!=='rejected';
const slaHours=p=>PRI[p]&&PRI[p].k==='urgent'?setting('slaUrgentH'):setting('slaNormalH');
const dueOf=t=>t.dueAt?new Date(t.dueAt).getTime():new Date(t.createdAt).getTime()+slaHours(t.priority)*HOUR;
const isLate=t=>isOpen(t)&&Date.now()>dueOf(t);
const closedAt=t=>{const h=t.history.filter(x=>x.status==='closed');return h.length?h[h.length-1].at:null};

