function readMedia(files){
  const list=[...files];if(!list.length)return Promise.resolve([]);toast('Uploading '+list.length+' file'+(list.length>1?'s':'')+'…');
  const kind=f=>f.type.startsWith('video/')?'video':f.type.startsWith('image/')?'image':'file';
  return Promise.all(list.map(f=>new Promise(res=>{
    if(kind(f)==='image'){const fr=new FileReader();fr.onload=()=>{const img=new Image();img.onload=()=>{const s=Math.min(1,1400/Math.max(img.width,img.height));const c=document.createElement('canvas');c.width=Math.round(img.width*s);c.height=Math.round(img.height*s);c.getContext('2d').drawImage(img,0,0,c.width,c.height);
        c.toBlob(b=>{uploadBlob(b||f,f.name.replace(/\.\w+$/,'')+'.jpg').then(url=>res({name:f.name,type:'image',url})).catch(()=>{let d='';try{d=c.toDataURL('image/jpeg',.6)}catch(e){}res({name:f.name,type:'image',data:d})})},'image/jpeg',.82)};
      img.onerror=()=>res({name:f.name,type:'image'});img.src=fr.result};fr.onerror=()=>res({name:f.name,type:'image'});fr.readAsDataURL(f)}
    else uploadBlob(f,f.name).then(url=>res({name:f.name,type:kind(f),url,size:f.size})).catch(()=>{let l='';try{l=URL.createObjectURL(f)}catch(e){}res({name:f.name,type:kind(f),size:f.size,local:l})});
  })));
}
async function serverLogin(email,pw){
  if(!online){const u=S.users.find(x=>x.email.toLowerCase()===email.trim().toLowerCase()&&x.active!==false);return u&&pw==='demo123'?u.id:null}
  const {data,error}=await sb.rpc('login',{p_email:email,p_password:pw});if(error)throw error;return data;
}
async function alertHealth(){if(!online||!sb)return null;try{const {data,error}=await sb.functions.invoke('aqar-alerts',{body:{health:true}});if(error)return null;return data}catch(e){return null}}

/* ================= notifications ================= */
function logAct(text){S.log.unshift({id:uid('l'),at:nowISO(),by:S.session||'system',text});if(S.log.length>600)S.log.length=600}
function notify(ids,text,link,subject,body,opts){
  opts=opts||{};const at=nowISO();const ch=setting('channels')||{};
  [...new Set((ids||[]).filter(Boolean))].forEach(id=>{const u=userById(id);if(!u||u.active===false)return;
    S.notifs.unshift({id:uid('n'),userId:id,text,at,read:false,link:link||null,kind:opts.kind||'info'});
    if(opts.inAppOnly)return;
    const pref=u.prefs||{email:true,whatsapp:true};const subj=subject||text;const msg=body||text;
    if(ch.email!==false&&pref.email!==false&&u.email)S.outbox.unshift({id:uid('e'),at,channel:'email',to:u.email,toName:u.name,userId:id,subject:subj,body:msg,ref:link&&link.id||null});
    if(ch.whatsapp!==false&&pref.whatsapp!==false&&u.phone&&opts.whatsapp!==false)S.outbox.unshift({id:uid('w'),at,channel:'whatsapp',to:u.phone,toName:u.name,userId:id,subject:subj,body:'*'+subj+'*\n'+msg,ref:link&&link.id||null});
  });
  if(S.notifs.length>900)S.notifs.length=900;if(S.outbox.length>500)S.outbox.length=500;
}
const usersByRole=r=>S.users.filter(u=>u.role===r&&u.active!==false).map(u=>u.id);
function escalationTo(t){const roles=setting('escalateRoles')||[];const ids=[];
  if(roles.includes('supervisor'))ids.push(t.supId||(propById(t.propId)||{}).supId);
  ['manager','owner','admin'].forEach(r=>{if(roles.includes(r))ids.push(...usersByRole(r))});return ids}
function ticketMsg(t,extra){const p=propById(t.propId);return t.id+' · '+t.title+'\nBuilding: '+p.code+' '+p.name+'\nLocation: '+t.location+'\nPriority: '+PRI[t.priority].l+' (fix within '+slaHours(t.priority)+' h, due '+fmtDT(new Date(dueOf(t)).toISOString())+')\nStage: '+STAGE[t.status].l+(extra?'\n'+extra:'')+'\n\nOpen Alkazemi Asset Management to act on it.'}

/* ================= ticket workflow ================= */
function actionFor(t,u){
  if(!u)return null;const a=u.role==='admin';
  switch(t.status){
    case 'reported':return (a||(can(u,'supApprove')&&(t.supId===u.id||(u.props||[]).includes(t.propId))))?'Pre-approve':null;
    case 'mgr_approval':return can(u,'mgrApprove')?'Approve as manager':null;
    case 'owner_approval':return can(u,'ownerApprove')?'Owner approval':null;
    case 'assigned':return (a||t.techId===u.id)?'Start work':null;
    case 'in_progress':return (a||t.techId===u.id)?'Record job done':null;
    case 'job_done':return can(u,'closeJob')?'Close or send to procurement':null;
    case 'procurement':return can(u,'procure')?'Approve purchase':null;
  }return null}
const myQueue=u=>ticketsFor(u).filter(t=>actionFor(t,u));
function waitingOn(t){const s=STAGE[t.status];if(!s||!s.who)return '';
  if(s.who==='supervisor')return nameOf(t.supId);if(s.who==='tech')return nameOf(t.techId);
  if(s.who==='manager')return 'Operations manager';if(s.who==='owner')return 'Owner';if(s.who==='procurement')return 'Procurement';return ''}
function stageAge(t){const h=t.history[t.history.length-1];return Date.now()-new Date(h?h.at:t.createdAt).getTime()}
function moveTicket(t,status,text,to,subject,extraMsg){
  t.status=status;t.history.push({at:nowISO(),by:S.session,status,text});
  notify(to,t.id+' · '+text,{view:'tickets',id:t.id},(subject||'Ticket update')+' · '+t.id+' · '+(propById(t.propId)||{}).code,ticketMsg(t,text+(extraMsg?'\n'+extraMsg:'')),{kind:'ticket'});
  if(status==='closed'||status==='rejected')resolveAlert('tk-'+t.id);
  logAct(t.id+': '+text);save();
}
function newTicket(o){
  const u=me();const p=propById(o.propId);const created=nowISO();const pri=o.priority||'P3';
  const staff=u.role!=='guard';
  const t={id:nextTicketId(),propId:p.id,unitId:o.unitId||null,category:o.category,priority:pri,title:o.title,location:o.location||'Not specified',desc:o.desc||'',reporterId:u.id,
    createdAt:created,dueAt:new Date(Date.now()+slaHours(pri)*HOUR).toISOString(),status:'reported',supId:p.supId,managerId:'u-mgr',techId:null,estCost:o.estCost||0,history:[],media:o.media||[],job:null,proc:null,rejectReason:null,arrivals:[],emergency:!!o.emergency};
  t.history.push({at:created,by:u.id,status:'reported',text:(o.emergency?'EMERGENCY reported':'Reported')+(t.media.length?' with '+t.media.length+' photo/video':'')});
  // supervisors and above pre-approve their own reports automatically
  if(staff&&(u.role==='supervisor'||u.role==='admin'||u.role==='manager'||u.role==='owner')){
    t.status='mgr_approval';t.history.push({at:created,by:u.id,status:'mgr_approval',text:'Pre-approved by '+ROLES[u.role].short.toLowerCase()+' (raised from office)'});
  }
  S.tickets.unshift(t);
  const toRole=t.status==='reported'?[p.supId]:usersByRole('manager');
  if(o.emergency){notify([p.supId,...usersByRole('manager'),...usersByRole('owner'),'u-admin'],'EMERGENCY · '+t.title+' at '+p.code,{view:'tickets',id:t.id},'EMERGENCY at '+p.code+' '+p.name,ticketMsg(t,'Reported by '+u.name+' ('+u.phone+')'),{kind:'emergency'})}
  else notify(toRole,(t.status==='reported'?'New report to pre-approve · ':'Ticket to approve · ')+t.id+' · '+p.code,{view:'tickets',id:t.id},(t.status==='reported'?'Pre-approval needed':'Approval needed')+' · '+t.id,ticketMsg(t,'Reported by '+u.name),{kind:'approval'});
  logAct('Created '+t.id+' at '+p.code);save();return t;
}
function supApprove(t,o){const p=propById(t.propId);t.category=o.category||t.category;t.estCost=+o.estCost||0;
  if(o.priority&&o.priority!==t.priority){t.priority=o.priority;t.dueAt=new Date(new Date(t.createdAt).getTime()+slaHours(o.priority)*HOUR).toISOString()}
  moveTicket(t,'mgr_approval','Pre-approved by supervisor · estimate '+money(t.estCost,p.currency)+(o.note?' · '+o.note:''),usersByRole('manager'),'Manager approval needed')}
function mgrApprove(t,o){const p=propById(t.propId);t.techId=o.techId;t.managerId=S.session;
  if(o.priority&&o.priority!==t.priority){t.priority=o.priority;t.dueAt=new Date(new Date(t.createdAt).getTime()+slaHours(o.priority)*HOUR).toISOString()}
  const lim=+setting('ownerThreshold')||0;const kwd=toKWD(t.estCost,p.currency);
  if(lim>0&&kwd<lim){t.history.push({at:nowISO(),by:S.session,status:'owner_approval',text:'Manager approved · technician: '+nameOf(t.techId)});
    moveTicket(t,'assigned','Below owner approval limit (KWD '+lim+') · sent to '+nameOf(t.techId),[t.techId,t.supId],'Job assigned')}
  else moveTicket(t,'owner_approval','Manager approved · technician: '+nameOf(t.techId)+(o.note?' · '+o.note:''),usersByRole('owner'),'Owner approval needed')}
function ownerApprove(t,o){moveTicket(t,'assigned','Owner approved · sent to '+nameOf(t.techId)+(o&&o.note?' · '+o.note:''),[t.techId,t.supId,(propById(t.propId)||{}).guardId],'Job assigned')}
function rejectTicket(t,reason){t.rejectReason=reason;moveTicket(t,'rejected','Rejected · '+reason,[t.reporterId,t.supId],'Ticket rejected')}

/* ================= escalation engine =================
   Online: the database runs akam.run_escalations() every 5 minutes (pg_cron) and the akam-alerts edge function sends email/WhatsApp.
   Demo mode on a device: the same rules run here every minute. */
function alertFor(ref){return S.alerts.find(a=>a.ref===ref&&!a.resolved)}
function resolveAlert(id){const a=S.alerts.find(x=>x.id===id);if(a&&!a.resolved){a.resolved=true;a.resolved_at=nowISO();if(online&&sb)sb.from('alerts').update({resolved:true,resolved_at:a.resolved_at}).eq('id',id).then(()=>{})}}
function runLocalEscalations(){
  if(online||!S)return;const now=Date.now();const rep=(+setting('repeatH')||4)*HOUR;let n=0;
  S.tickets.filter(isLate).forEach(t=>{const id='tk-'+t.id;let a=S.alerts.find(x=>x.id===id);
    if(a&&!a.resolved&&now-new Date(a.last_at).getTime()<rep)return;
    if(!a){a={id,kind:'ticket_sla',ref:t.id,count:0,first_at:nowISO(),last_at:nowISO(),resolved:false};S.alerts.unshift(a)}
    a.count++;a.last_at=nowISO();a.resolved=false;n++;
    const late=dur(now-dueOf(t));const p=propById(t.propId);
    notify(escalationTo(t),'LATE '+late+' · '+t.id+' · '+t.title+' at '+p.code+' (alert #'+a.count+')',{view:'tickets',id:t.id},'LATE JOB · alert #'+a.count+' · '+t.id+' · '+p.code,ticketMsg(t,'This job is '+late+' past its '+slaHours(t.priority)+'-hour deadline. Waiting on: '+waitingOn(t)+'.'),{kind:'late'})});
  S.vjobs.filter(j=>j.status==='in_progress'&&j.startedAt&&now>new Date(j.startedAt).getTime()+j.expectedH*HOUR).forEach(j=>{const id='vj-'+j.id;let a=S.alerts.find(x=>x.id===id);
    if(a&&!a.resolved&&now-new Date(a.last_at).getTime()<(+setting('vehicleRepeatH')||2)*HOUR)return;
    if(!a){a={id,kind:'vehicle_overtime',ref:j.id,count:0,first_at:nowISO(),last_at:nowISO(),resolved:false};S.alerts.unshift(a)}
    a.count++;a.last_at=nowISO();j.alerts=a.count;n++;const v=vehById(j.vehicleId);const over=dur(now-new Date(j.startedAt).getTime()-j.expectedH*HOUR);
    notify([j.workerId,...usersByRole('manager')],'Repair overtime '+over+' · '+v.plate+' '+v.make+' '+v.model+' · '+j.issue,{view:'fleet',id:j.id},'Vehicle repair over time · '+v.plate,'Repair job '+j.id+' on '+v.plate+' ('+v.make+' '+v.model+') was expected to take '+j.expectedH+' h and is now '+over+' over.\nIssue: '+j.issue+'\nGarage: '+j.garage,{kind:'late'})});
  if(n){save();queueRender()}
}

/* ================= reminders ================= */
function computeReminders(){
  const out=[];const mg=[...usersByRole('admin'),...usersByRole('owner')];
  S.units.forEach(u=>{if(!u.end||!u.tenantId)return;const d=daysUntil(u.end);if(d<=60){const p=propById(u.propId);const t=tenantById(u.tenantId);
    out.push({type:'Lease expiry',tone:d<0?'bad':'warn',days:d,propId:p.id,subject:(d<0?'Lease expired · ':'Lease expiring · ')+u.code,detail:(t?t.name:'')+' · '+u.tenancy+' ends '+fmtDate(u.end),to:[p.supId,...mg]})}});
  S.props.forEach(p=>{p.docs.forEach(d=>{if(!d.expiry)return;const n=daysUntil(d.expiry);if(n<=45)out.push({type:'Document expiry',tone:n<0?'bad':'warn',days:n,propId:p.id,subject:d.title+' · '+p.code,detail:'Expiry '+fmtDate(d.expiry)+' · ref '+d.ref,to:[p.supId,...mg]})});
    p.ppm.forEach(m=>{const n=daysUntil(m.next);if(n<=7){const techs=S.users.filter(u=>u.role==='tech'&&(u.skills||[]).includes(m.cat)).map(u=>u.id);out.push({type:'Planned maintenance',tone:n<0?'bad':'info',days:n,propId:p.id,subject:m.label+' · '+p.code,detail:m.cat+' · due '+fmtDate(m.next),to:[...techs,p.supId,p.guardId,...usersByRole('manager')]})}})});
  S.rent.forEach(r=>{if(r.paidOn)return;const d=daysUntil(r.due);if(d<-5){const u=unitById(r.unitId);if(!u)return;const p=propById(u.propId);const t=tenantById(u.tenantId);out.push({type:'Rent overdue',tone:'bad',days:d,propId:p.id,subject:'Rent overdue · '+u.code+' · '+monthLabel(r.month),detail:(t?t.name+' · ':'')+money(r.amount,r.cur),to:[p.supId,'u-admin']})}});
  S.vehicles.forEach(v=>{[['regExp','Vehicle registration (Daftar)'],['insExp','Vehicle insurance']].forEach(([k,l])=>{const n=daysUntil(v[k]);if(n<=30)out.push({type:'Fleet document',tone:n<0?'bad':'warn',days:n,propId:null,subject:l+' · '+v.plate,detail:v.make+' '+v.model+' · expires '+fmtDate(v[k]),to:[...usersByRole('manager'),'u-admin']})});
    const n=daysUntil(v.nextService);if(n<=7)out.push({type:'Vehicle service',tone:n<0?'bad':'info',days:n,propId:null,subject:'Service due · '+v.plate,detail:v.make+' '+v.model+' · '+fmtDate(v.nextService)+' or '+v.nextServiceKm.toLocaleString()+' km',to:[v.driverId,'u-t7',...usersByRole('manager')]})});
  S.items.forEach(i=>{if(i.qty<=i.min)out.push({type:'Low stock',tone:i.qty===0?'bad':'warn',days:0,propId:null,subject:i.name+' · '+i.qty+' '+i.unit+' left',detail:i.store+' · reorder level '+i.min,to:usersByRole('procurement')})});
  return out.sort((a,b)=>a.days-b.days);
}
function sendReminders(silent){const list=computeReminders();const per={};
  list.forEach(r=>[...new Set(r.to.filter(Boolean))].forEach(id=>(per[id]=per[id]||[]).push(r)));
  Object.entries(per).forEach(([id,items])=>{const bad=items.filter(r=>r.tone==='bad').length;
    const lines=items.slice(0,40).map(r=>'• '+r.type+': '+r.subject+' — '+r.detail).join('\n')+(items.length>40?'\n…and '+(items.length-40)+' more in the platform.':'');
    notify([id],items.length+' reminders today'+(bad?' · '+bad+' overdue':''),{view:'alerts'},'Daily reminders · '+items.length+' items'+(bad?' ('+bad+' overdue)':''),'Daily reminder digest from '+setting('orgName')+'.\n\n'+lines,{kind:'reminder',whatsapp:false})});
  S.lastReminderRun=iso(TODAY);logAct('Sent daily reminder digest ('+list.length+' items to '+Object.keys(per).length+' people)');save();if(!silent)toast('Reminder digest sent to '+Object.keys(per).length+' people');return list.length}
function afterLogin(fresh){if(!S||!S.session)return;if(!online)setTimeout(runLocalEscalations,300);if(S.lastReminderRun!==iso(TODAY)&&me()&&['admin','manager','supervisor'].includes(me().role))sendReminders(true)}

/* ================= components ================= */
const st=(t,tone)=>`<span class="st ${tone||''}">${esc(t)}</span>`;
const stage=s=>st(STAGE[s].l,STAGE[s].c);
const priPill=p=>st(PRI[p].l+' · '+(PRI[p].k==='urgent'?setting('slaUrgentH'):setting('slaNormalH'))+'h',PRI[p].c);
function slaPill(t){
  if(!isOpen(t)){const c=closedAt(t);if(!c)return st('Rejected','');return new Date(c).getTime()>dueOf(t)?st('Closed late','warn'):st('On time','ok')}
  const left=dueOf(t)-Date.now();if(left<0)return st('Late '+dur(-left),'bad');return st(dur(left)+' left',left<6*HOUR?'warn':'')}
function expPill(s,warn){warn=warn||60;if(!s)return st('No expiry','');const d=daysUntil(s);if(d<0)return st('Expired '+(-d)+'d ago','bad');if(d<=warn)return st(d+' days left','warn');return `<span class="small dim">${fmtDate(s)}</span>`}
const av=(id,sm)=>{const u=userById(id);return `<span class="av ${sm?'sm':''} ${avTone(id)}" title="${esc(u?u.name:'')}">${esc(initials(u?u.name:'?'))}</span>`};
const avName=(id,sub)=>{const u=userById(id);return `<span class="who">${av(id,true)}<span class="stack tight" style="gap:0"><b>${esc(u?u.name:'—')}</b>${sub!==false&&u?`<span class="tiny muted">${esc(sub||u.title)}</span>`:''}</span></span>`};
const unitStatusPill=s=>st(s,s==='Occupied'?'ok':s==='Vacant'?'gold':s==='Reserved'?'info':'bad');
function empty(msg,icon){return `<div class="empty">${ic(icon||'check')}<span>${msg}</span></div>`}
function table(cols,rows,opts){opts=opts||{};
  if(!rows.length)return `<div class="tbl">${empty(opts.empty||'Nothing to show.',opts.emptyIcon)}</div>`;
  return `<div class="tbl"><table><thead><tr>${cols.map(c=>`<th class="${c.r?'r':''}">${esc(c.h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr class="${r.act?'click':''} ${r.sel?'sel':''}" ${r.act?`data-act="${r.act}" data-id="${esc(r.id)}"`:''}>${r.cells.map((c,i)=>`<td class="${cols[i].r?'r':''}" data-l="${esc(cols[i].h)}">${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function media(list,cap){
  if(!list||!list.length)return '<p class="muted small">No photos or videos.</p>';
  return `<div class="media">${list.map(m=>{let inner;
    if(m.type==='image'&&(m.url||m.data))inner=`<img src="${esc(m.url||m.data)}" alt="${esc(m.name)}" loading="lazy">`;
    else if(m.type==='video'&&(m.url||m.local))inner=`<video src="${esc(m.url||m.local)}" controls muted playsinline preload="metadata"></video>`;
    else inner=`<span class="ph">${ic(m.type==='video'?'video':m.type==='image'?'img':'doc')}</span>`;
    const href=m.url&&m.type!=='video'?` href="${esc(m.url)}" target="_blank" rel="noopener"`:'';
    return `<${href?'a':'div'} class="mt ${m.sample?'sample':''}"${href}>${inner}<span class="cap">${esc(m.name)}${m.sample?' · sample':''}</span></${href?'a':'div'}>`}).join('')}</div>`}
function hbars(items,fmt){fmt=fmt||(v=>v);const max=Math.max(1,...items.map(i=>i.value));
  return `<div class="hbars">${items.map(i=>`<div class="hb"><span class="l" title="${esc(i.label)}">${esc(i.label)}</span><span class="t"><i class="${i.tone||''}" style="width:${(i.value/max*100).toFixed(1)}%"></i></span><span class="v">${fmt(i.value)}</span></div>`).join('')}</div>`}
function lolli(days,vals,hlIdx,tipFmt){const max=Math.max(1,...vals);
  return `<div class="lolli" role="img" aria-label="${days.map((d,i)=>d+': '+vals[i]).join(', ')}">${days.map((d,i)=>{const h=vals[i]?Math.max(8,vals[i]/max*120):0;const hl=i===hlIdx;
    return `<div class="c ${hl?'hl':''}">${hl?`<span class="tip">${tipFmt?tipFmt(vals[i]):vals[i]}</span>`:''}${vals[i]?`<span class="stem ${hl?'hl':''}" style="height:${h}px"></span>`:`<span class="stem zero"></span>`}<span class="dot"></span><span class="lab">${d}</span></div>`}).join('')}</div>`}
function dial(frac,center,sub,subCls){frac=Math.max(0,Math.min(1,frac));const N=48;let ticks='';
  for(let i=0;i<N;i++){const a=(i/N)*Math.PI*2-Math.PI/2;const r1=88,r2=i%4===0?80:83;ticks+=`<line x1="${100+r1*Math.cos(a)}" y1="${100+r1*Math.sin(a)}" x2="${100+r2*Math.cos(a)}" y2="${100+r2*Math.sin(a)}" stroke="var(--line-2)" stroke-width="${i%4===0?1.6:1}"/>`}
  const R0=68,C=2*Math.PI*R0;const a=frac*Math.PI*2-Math.PI/2;const kx=100+R0*Math.cos(a),ky=100+R0*Math.sin(a);
  return `<div class="dial"><svg viewBox="0 0 200 200" aria-hidden="true">${ticks}<circle cx="100" cy="100" r="${R0}" fill="none" stroke="var(--surface-3)" stroke-width="12"/><circle class="arc" cx="100" cy="100" r="${R0}" fill="none" stroke="var(--gold)" stroke-width="12" stroke-linecap="round" stroke-dasharray="${(C*frac).toFixed(1)} ${C.toFixed(1)}" transform="rotate(-90 100 100)"/>${frac>0.01?`<circle class="knob" cx="${kx}" cy="${ky}" r="5" fill="var(--ink)"/>`:''}</svg><div class="mid"><b>${center}</b><span class="${subCls||''}">${sub||''}</span></div></div>`}
/* building illustration generated from type and code */
function bldArt(p){const seedN=p.code.split('').reduce((a,c)=>a+c.charCodeAt(0),0);const r=mulberry32(seedN);const t=p.type;let s='';
  const sky=t==='Industrial & Logistics'?'var(--surface-3)':'var(--gold-soft)';
  s+=`<rect width="400" height="120" fill="${sky}"/><circle cx="${330+r()*40}" cy="${28+r()*10}" r="14" fill="var(--gold)" opacity=".7"/>`;
  if(t==='Industrial & Logistics'){for(let i=0;i<3;i++){const x=20+i*128,w=118,h=48+r()*20;s+=`<path d="M${x} 120V${120-h}l${w/2} -16 ${w/2} 16V120z" fill="var(--surface)" stroke="var(--line-2)"/><rect x="${x+w/2-18}" y="${120-30}" width="36" height="30" fill="var(--surface-3)" stroke="var(--line-2)"/>`}}
  else{const n=t==='Retail'?5:t==='Residential'?4:3;for(let i=0;i<n;i++){const w=t==='Retail'?70:56+r()*30,x=14+i*(380/n),h=t==='Retail'?38+r()*16:50+r()*60;const dark=i===Math.floor(n/2)&&t!=='Retail';
    s+=`<rect x="${x}" y="${120-h}" width="${w}" height="${h}" rx="4" fill="${dark?'var(--night)':'var(--surface)'}" stroke="${dark?'var(--night)':'var(--line-2)'}"/>`;
    for(let yy=120-h+8;yy<112;yy+=12)for(let xx=x+7;xx<x+w-8;xx+=12)s+=`<rect x="${xx}" y="${yy}" width="6" height="6" rx="1" fill="${dark?(r()<.35?'var(--gold)':'var(--night-3)'):(r()<.2?'var(--gold)':'var(--surface-3)')}"/>`}}
  s+=`<rect y="116" width="400" height="4" fill="var(--line-2)"/>`;return `<svg viewBox="0 0 400 120" preserveAspectRatio="xMidYMid slice" aria-hidden="true">${s}</svg>`}
/* apartment picker / stacking plan */
function stackPlan(propId,selId,opts){opts=opts||{};const units=S.units.filter(u=>u.propId===propId);if(!units.length)return '<p class="muted">No units yet. Add units from the building page.</p>';
  const floors=[...new Set(units.map(u=>u.floor))].sort((a,b)=>b-a);
  return `<div class="stackplan">${floors.map(f=>`<div class="floor"><span class="fl">${f===0?'G':'F'+f}</span>${units.filter(u=>u.floor===f).map(u=>{const cls=u.status==='Vacant'?'vac':u.status==='Occupied'?'occ':u.status==='Reserved'?'occ':'mnt';const dis=opts.onlyVacant&&u.status!=='Vacant';
    return `<button type="button" class="apt ${cls} ${u.id===selId?'on':''}" ${dis?'disabled style="opacity:.35;cursor:not-allowed"':''} data-act="${opts.act||'pickApt'}" data-id="${u.id}" title="${esc(u.code+' · '+u.kind+' · '+u.status)}"><b>${esc(u.no)}</b><span>${esc(u.kind.replace('Apartment ',''))}</span></button>`}).join('')}</div>`).join('')}</div>
  <div class="legend"><span><i style="background:var(--surface)"></i>Occupied</span><span><i style="background:var(--gold-soft)"></i>Vacant</span><span><i style="background:var(--bad-soft)"></i>Under maintenance</span>${selId?'<span><i style="background:var(--night)"></i>Selected</span>':''}</div>`}
/* drawers & dialogs */
function drawer(html,wide){const L=$('#layer');L.className='layer';L.innerHTML=`<div class="drawer ${wide?'wide':''}" role="dialog" aria-modal="true">${html}</div>`;L.hidden=false;cardify(L);const dh=L.querySelector('h2,h3');const tb=L.querySelector('.tabs .on,[aria-selected=true]');motion(L,(dh?dh.textContent:'')+'|'+(tb?tb.textContent:''),'drawer');}
function dialog(html){const L=$('#layer');L.className='layer center';L.innerHTML=`<div class="dialog" role="dialog" aria-modal="true">${html}</div>`;L.hidden=false;setTimeout(()=>{const f=L.querySelector('input:not([type=hidden]),textarea,select');if(f)try{f.focus()}catch(e){}},40)}
function closeLayer(){const L=$('#layer');L.hidden=true;L.innerHTML='';ui.drawer=null}
function dHead(title,sub,extra){return `<div class="dh-bar"><div class="grow">${sub?`<span class="eyebrow">${sub}</span>`:''}<h2>${title}</h2>${extra||''}</div><button class="circ" data-act="close" aria-label="Close">${ic('x')}</button></div>`}
function reopenDrawer(){const d=ui.drawer;if(!d)return;const L=$('#layer');const sc=L.querySelector('.d-body');const top=sc?sc.scrollTop:0;const fn=DRAWERS[d.k];if(fn){fn(d.id,true);const n=$('#layer .d-body');if(n)n.scrollTop=top}}
let toastT=null;
function toast(msg){const t=$('#toast');t.textContent=msg;t.hidden=false;clearTimeout(toastT);toastT=setTimeout(()=>{t.hidden=true},3400)}
function cardify(root){(root||document).querySelectorAll('.tbl table').forEach(tb=>{const hs=[...tb.querySelectorAll('thead th')].map(h=>h.textContent.trim());tb.querySelectorAll('tbody tr').forEach(tr=>[...tr.children].forEach((td,i)=>{if(!td.hasAttribute('data-l'))td.setAttribute('data-l',hs[i]||'')}))})}
function copyText(text,msg){try{navigator.clipboard.writeText(text).then(()=>toast(msg||'Copied'),()=>toast('Copy blocked by the browser'))}catch(e){toast('Copy blocked by the browser')}}
function scopeName(){return ui.scope?propById(ui.scope).name:'All buildings'}

/* ================= motion: count-up numbers & growing charts ================= */
const MO_SEL='.big:not(#tv-clock),.dial .mid b,.pbar .track,.lolli .tip,.hb .v,.cnt-up';
const MO_DUR=1400;
const moLast=new Map();let moKeys={};
const moReduced=()=>{try{return window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches}catch(e){return false}};
const moEase=t=>1-Math.pow(1-t,3);
function moNumNode(el){const w=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let n;while(n=w.nextNode()){if(/\d/.test(n.nodeValue))return n}return null}
function moParse(s){const m=s.match(/-?\d[\d,]*(?:\.\d+)?/);if(!m)return null;const raw=m[0];const dec=(raw.split('.')[1]||'').length;
  return {pre:s.slice(0,m.index),post:s.slice(m.index+raw.length),val:parseFloat(raw.replace(/,/g,'')),dec,comma:raw.includes(',')||Math.abs(parseFloat(raw.replace(/,/g,'')))>=10000}}
function moFmt(v,p){const s=v.toFixed(p.dec);if(!p.comma)return s;const [a,b]=s.split('.');return a.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(b?'.'+b:'')}
function moCount(node,p,from){const t0=performance.now();const to=p.val;
  const step=now=>{const k=Math.min(1,(now-t0)/MO_DUR);const v=from+(to-from)*moEase(k);if(!node.isConnected)return;node.nodeValue=p.pre+moFmt(k<1?v:to,p)+p.post;if(k<1)requestAnimationFrame(step)};
  node.nodeValue=p.pre+moFmt(from,p)+p.post;requestAnimationFrame(step)}
/* scope: where to look; key: what the screen is. Charts replay only when the key changes; numbers count from their previous value when data changes live. */
function motion(scope,key,slot){
  if(!scope)return;try{flushTr()}catch(e){}
  slot=slot||'main';const fresh=moKeys[slot]!==key;moKeys[slot]=key;
  const els=[...scope.querySelectorAll(MO_SEL)];const reduce=moReduced();
  els.forEach((el,i)=>{const node=moNumNode(el);if(!node)return;const p=moParse(node.nodeValue);if(!p||!isFinite(p.val))return;
    const id=slot+'|'+key+'|'+i;const prev=moLast.get(id);moLast.set(id,p.val);
    if(reduce)return;
    if(fresh){if(p.val!==0)moCount(node,p,0)}else if(prev!=null&&prev!==p.val)moCount(node,p,prev)});
  if(fresh&&!reduce){scope.classList.remove('mo');void scope.offsetWidth;scope.classList.add('mo');
    scope.querySelectorAll('.lolli').forEach(l=>[...l.children].forEach((c,i)=>c.style.setProperty('--mo-d',(i*55)+'ms')));
    scope.querySelectorAll('.hbars').forEach(l=>[...l.children].forEach((c,i)=>c.style.setProperty('--mo-d',(i*45)+'ms')));
    scope.querySelectorAll('.stepbar,.figs,.tv-heat').forEach(l=>[...l.children].forEach((c,i)=>c.style.setProperty('--mo-d',(i*60)+'ms')));
    scope.querySelectorAll('.strip').forEach(l=>[...l.children].forEach((c,i)=>c.style.setProperty('--mo-d',(i*80)+'ms')));
    clearTimeout(scope._moT);scope._moT=setTimeout(()=>scope.classList.remove('mo'),MO_DUR+900)}}

