function applyTheme(){const t=lsGet(THEME_KEY);const sys=window.matchMedia&&window.matchMedia('(prefers-color-scheme: dark)').matches;document.documentElement.setAttribute('data-theme',t||(sys?'dark':'light'))}
const isDark=()=>document.documentElement.getAttribute('data-theme')==='dark';
const logoSrc=()=>isDark()?LOGO_WHITE:LOGO_INK;

function render(){
  const root=$('#root');if(!S){return}
  const ae=document.activeElement;const keep=ae&&ae.id?{id:ae.id,s:ae.selectionStart,e:ae.selectionEnd}:null;
  const u=me();
  if(!u){root.innerHTML=viewLogin();motion(root,'login');return}
  if(u.role==='guard'){root.innerHTML=viewGuardApp(u);cardify(root);restoreFocus(keep);motion(root,u.id+'|guard|'+ui.guardTab);maybeTour();return}
  if(!can(u,ui.view)||ui.view==='tv')ui.view=can(u,'dashboard')?'dashboard':(NAV.find(n=>n[0]!=='sec'&&can(u,n[0]))||['help'])[0];
  if(ui.scope&&!propsFor(u).some(p=>p.id===ui.scope))ui.scope='';
  const unread=S.notifs.filter(n=>n.userId===u.id&&!n.read).length;const q=myQueue(u).length;
  const late=ticketsFor(u).filter(isLate).length;
  const nav=NAV.filter(n=>n[0]==='sec'||can(u,n[0])).filter((n,i,a)=>!(n[0]==='sec'&&(!a[i+1]||a[i+1][0]==='sec'))).map(n=>{
    if(n[0]==='sec')return `<div class="nav-sec">${n[1]}</div>`;
    let cnt='';if(n[0]==='tickets'&&q)cnt=`<span class="cnt">${q}</span>`;if(n[0]==='escalations'&&late)cnt=`<span class="cnt bad">${late}</span>`;
    return `<button class="nav ${ui.view===n[0]?'on':''}" data-act="${n[0]==='tv'?'tvOpen':'nav'}" data-v="${n[0]}" data-tour="nav-${n[0]}">${ic(n[2])}<span>${n[1]}</span>${cnt}</button>`}).join('');
  const views={dashboard:viewDashboard,escalations:viewEscalations,buildings:viewBuildings,units:viewUnits,tenants:viewTenants,inspections:viewInspections,tickets:viewTickets,report:viewReport,guard:u2=>`<div class="card" style="max-width:680px">${guardBody(u2,true)}</div>`,warehouse:viewWarehouse,fleet:viewFleet,rent:viewRent,alerts:viewAlerts,reports:viewReports,users:viewUsers,settings:viewSettings,help:viewHelp};
  const props=propsFor(u);
  const greet=ui.view==='dashboard';
  root.innerHTML=`<div class="shell ${ui.navOpen?'navopen':''}">
   <div class="side-scrim" data-act="navToggle"></div>
   <aside class="side" aria-label="Main navigation" data-tour="nav">
     <div class="brand"><img src="${EMBLEM}" alt=""><div><b>Alkazemi</b><span>Asset Management</span></div></div>
     ${nav}
     <div class="side-foot"><div class="side-card"><b style="font-weight:500">Need a hand?</b><p>Step-by-step guides for every screen, or replay the tour.</p><div class="row"><button class="btn gold sm" data-act="nav" data-v="help">${ic('book')}Guide</button><button class="btn sm" style="background:var(--night-2);border-color:var(--night-3);color:var(--night-ink)" data-act="tourStart">${ic('play')}Tour</button></div></div></div>
   </aside>
   <div class="main">
     ${online?'':`<div class="offline-bar"><b>Demo mode.</b> The shared database is not connected, so changes stay on this device. <button class="btn sm" data-act="reload">Reconnect</button></div>`}
     <header class="top">
       <button class="iconbtn menu-btn" data-act="navToggle" aria-label="Open menu">${ic('menu')}</button>
       <div class="title">${greet?`<b>${greeting()}, ${esc(u.name.split(' ')[0])}</b><span>${new Date().toLocaleDateString(LOC(),{weekday:'long',day:'numeric',month:'long'})} · ${hijri(new Date())}</span>`:`<b>${TITLE[ui.view]||''}</b><span>${SUB[ui.view]||''}</span>`}</div>
       ${props.length>1&&!['users','settings','help','fleet','warehouse'].includes(ui.view)?`<label class="scope" data-tour="scope" title="Building">${ic('bld')}<select id="scope" data-change="scope" aria-label="Building"><option value="">All buildings</option>${props.map(p=>`<option value="${p.id}" ${ui.scope===p.id?'selected':''}>${esc(p.code)} · ${esc(p.name)}</option>`).join('')}</select></label>`:''}
       <form class="search" data-form="gsearch" role="search" data-tour="search">${ic('search')}<input id="gq" name="q" placeholder="Search tickets, units, plates…" autocomplete="off"></form>
       <span id="sync" class="st plain ${syncState==='live'?'ok':syncState==='saving'?'info':'warn'}" style="display:${online?'':'none'}">${SYNC_L[syncState]||''}</span>
       ${langBtn()}${themeBtn()}<button class="iconbtn" data-act="nav" data-v="help" aria-label="Help" data-tour="help">${ic('help')}</button>
       <button class="iconbtn" data-act="bell" aria-label="Notifications" data-tour="bell">${ic('bell')}${unread?`<span class="badge">${unread>99?'99+':unread}</span>`:''}</button>
       <div class="rel"><button class="me" data-act="menu" aria-haspopup="true" data-tour="me"><span class="av ${avTone(u.id)}">${esc(initials(u.name))}</span><span class="who"><b>${esc(u.name)}</b><span>${esc(ROLES[u.role].l)}</span></span>${ic('down')}</button>
         ${ui.menu?`<div class="menu-pop"><button data-act="profile">${ic('user')}My profile & alerts</button><button data-act="tourStart">${ic('play')}Take the tour</button><button data-act="nav" data-v="help">${ic('book')}Help & guide</button><button data-act="theme">${ic(isDark()?'sun':'moon')}${isDark()?'Light':'Dark'} theme</button><hr><button data-act="logout">${ic('logout')}Sign out</button></div>`:''}</div>
     </header>
     <main class="content" id="content">${views[ui.view](u)}</main>
   </div>
   <nav class="bnav" aria-label="Quick navigation">${bottomNav(u,q,late)}</nav>
  </div>`;
  cardify(root);restoreFocus(keep);motion($('#content'),[u.id,ui.view,ui.scope,ui.f.wtab,ui.f.ftab,ui.f.atab,ui.reportPeriod,ui.tickMode].join('|'));maybeTour();
}
function bottomNav(u,q,late){const items=[['dashboard','Home','grid'],['tickets','Jobs','wrench'],['report','Report','cam'],['escalations','Late','alarm'],['buildings','Buildings','bld'],['warehouse','Stores','box'],['fleet','Fleet','truck']].filter(n=>can(u,n[0]));
  const pick4=[];['dashboard','tickets','report'].forEach(k=>{const n=items.find(x=>x[0]===k);if(n)pick4.push(n)});items.forEach(n=>{if(pick4.length<4&&!pick4.includes(n))pick4.push(n)});
  return pick4.map(n=>`<button class="bn ${ui.view===n[0]?'on':''} ${n[0]==='report'?'cta':''}" data-act="nav" data-v="${n[0]}">${ic(n[2])}<span>${n[1]}</span>${n[0]==='tickets'&&q?`<b>${q}</b>`:n[0]==='escalations'&&late?`<b>${late}</b>`:''}</button>`).join('')+`<button class="bn" data-act="navToggle">${ic('more')}<span>More</span></button>`}
function restoreFocus(k){if(!k)return;const el=document.getElementById(k.id);if(el){try{el.focus({preventScroll:true});if(k.s!=null&&el.setSelectionRange)el.setSelectionRange(k.s,k.e)}catch(e){}}}
function greeting(){const h=new Date().getHours();return h<12?'Good morning':h<17?'Good afternoon':'Good evening'}

