/* ================= dashboard ================= */
function portfolio(u){
  const ids=propIds(u);const units=S.units.filter(x=>ids.has(x.propId));const occ=units.filter(x=>x.status==='Occupied').length;
  const tks=ticketsFor(u);const open=tks.filter(isOpen);const m=ym(TODAY);
  const rent=S.rent.filter(r=>r.month===m&&(()=>{const x=unitById(r.unitId);return x&&ids.has(x.propId)})());
  const exp=sum(rent,r=>toKWD(r.amount,r.cur)),col=sum(rent.filter(r=>r.paidOn),r=>toKWD(r.amount,r.cur));
  const since=Date.now()-30*DAY;const closed=tks.filter(t=>t.status==='closed'&&new Date(closedAt(t)).getTime()>=since);const onTime=closed.filter(t=>new Date(closedAt(t)).getTime()<=dueOf(t)).length;
  const fix=closed.map(t=>new Date(closedAt(t))-new Date(t.createdAt));
  return {ids,units,occ,tks,open,late:open.filter(isLate),approvals:open.filter(t=>['reported','mgr_approval','owner_approval'].includes(t.status)),exp,col,closed,onTime,avgFix:fix.length?sum(fix)/fix.length:0};
}
function weekPlanner(u){const ids=propIds(u);const start=addD(TODAY,-((TODAY.getDay()+6)%7));const days=[...Array(7)].map((_,i)=>addD(start,i));
  const ev={};days.forEach(d=>ev[iso(d)]=[]);
  S.props.filter(p=>ids.has(p.id)).forEach(p=>p.ppm.forEach(m=>{if(ev[m.next])ev[m.next].push({c:'night',t:m.label,s:p.code,act:'openProp',id:p.id})}));
  S.units.filter(x=>ids.has(x.propId)&&x.tenantId&&ev[x.end]).forEach(x=>ev[x.end].push({c:'',t:'Lease ends',s:x.code,act:'editUnit',id:x.id}));
  S.insp.filter(i=>ids.has(i.propId)&&ev[iso(i.at)]).forEach(i=>ev[iso(i.at)].push({c:'gold',t:'Vacant inspection',s:unitById(i.unitId)?unitById(i.unitId).code:'',act:'openInsp',id:i.id}));
  if(can(u,'fleet'))S.vehicles.forEach(v=>{if(ev[v.nextService])ev[v.nextService].push({c:'',t:'Vehicle service',s:v.plate,act:'openVehicle',id:v.id})});
  return `<div class="week">${days.map(d=>{const k=iso(d);const l=ev[k];const today=k===iso(TODAY);
    return `<div class="day ${today?'today':''}"><div class="dh"><span>${d.toLocaleDateString(LOC(),{weekday:'short'})}</span><b>${d.getDate()}</b></div>${l.slice(0,4).map(e=>`<div class="ev ${e.c}" data-act="${e.act}" data-id="${e.id}"><b>${esc(e.t)}</b><span>${esc(e.s)}</span></div>`).join('')}${l.length>4?`<span class="tiny muted" style="text-align:center">+${l.length-4} more</span>`:''}</div>`}).join('')}</div>`}
function taskPanel(u,list,title){const n=list.length;
  return `<section class="card night" data-tour="queue"><div class="card-h"><h3 style="font-weight:500">${title}</h3><span class="big md" style="color:var(--night-ink)">${n}</span></div>
   <div class="tasks">${list.slice(0,7).map(t=>{const p=propById(t.propId);const late=isLate(t);return `<div class="task" data-act="openTicket" data-id="${t.id}"><span class="ic">${ic(CAT_ICON[t.category]||'wrench')}</span><span class="grow"><div class="t clip">${esc(t.title)}</div><div class="s clip">${t.id} · ${esc(p.code)} · ${esc(actionFor(t,u)||STAGE[t.status].l)}</div></span><span class="ck ${late?'late':''}" title="${late?'Late':'Within deadline'}">${late?'':''}</span></div>`}).join('')||`<p class="muted" style="padding:10px 4px">Nothing is waiting on you. Good work.</p>`}
   ${n>7?`<button class="btn sm" style="align-self:flex-start;background:var(--night-2);border-color:var(--night-3);color:var(--night-ink)" data-act="queueAll">View all ${n}</button>`:''}</div></section>`}
function viewDashboard(u){
  const P=portfolio(u);const q=myQueue(u).sort((a,b)=>dueOf(a)-dueOf(b));
  if(u.role==='tech')return dashTech(u,q);
  if(u.role==='procurement')return dashProc(u,q);
  const occPct=Math.round(P.occ/Math.max(1,P.units.length)*100),onPct=P.closed.length?Math.round(P.onTime/P.closed.length*100):100,rentPct=P.exp?Math.round(P.col/P.exp*100):0;
  const strip=[['Waiting for approval',P.approvals.length+' jobs','night',Math.max(14,Math.min(30,P.approvals.length*2))],['Fixed on time · 30 days',onPct+'%','gold',Math.max(14,onPct/3)],['Occupancy',occPct+'%','hatch',Math.max(18,occPct/2.2)],['Rent collected · '+new Date().toLocaleDateString(LOC(),{month:'short'}),rentPct+'%','out',Math.max(14,rentPct/3.5)]];
  const days=[...Array(7)].map((_,i)=>addD(TODAY,i-6));const raised=days.map(d=>P.tks.filter(t=>iso(t.createdAt)===iso(d)).length);
  const lateList=P.late.sort((a,b)=>dueOf(a)-dueOf(b));
  const byStage=STAGES.filter(s=>s.k!=='closed'&&s.k!=='rejected').map(s=>({s,n:P.open.filter(t=>t.status===s.k).length}));
  const att=S.props.filter(p=>P.ids.has(p.id)).map(p=>{const o=P.open.filter(t=>t.propId===p.id);return {p,o:o.length,l:o.filter(isLate).length}}).filter(x=>x.o).sort((a,b)=>b.l-a.l||b.o-a.o).slice(0,6);
  const low=S.items.filter(i=>i.qty<=i.min);const inRep=S.vjobs.filter(j=>j.status!=='done');
  return `<section class="stack loose">
    <div class="spread" style="align-items:flex-end;gap:24px" data-tour="strip">
      <div class="grow strip" style="display:grid;grid-template-columns:${strip.map(s=>s[3]+'fr').join(' ')};gap:10px;min-width:min(100%,520px)">${strip.map(s=>`<div class="pbar"><span class="lbl clip">${s[0]}</span><span class="track ${s[2]}">${s[1]}</span></div>`).join('')}</div>
      <div class="figs"><div class="fig"><span class="big">${P.ids.size}</span><small>${ic('bld')}Buildings</small></div><div class="fig"><span class="big">${P.open.length}</span><small>${ic('wrench')}Open jobs</small></div><div class="fig ${P.late.length?'alert':''}"><span class="big">${P.late.length}</span><small>${ic('alarm')}Late now</small></div></div>
    </div>
    <div class="grid g-dash">
      ${taskPanel(u,q,'Waiting on you')}
      <section class="card"><div class="card-h"><h3>Jobs raised</h3>${can(u,'reports')?`<button class="circ" data-act="nav" data-v="reports" aria-label="Open reports">${ic('arrow')}</button>`:''}</div>
        <div class="row" style="align-items:baseline;gap:8px"><span class="big md">${(sum(raised)/7).toFixed(1)}</span><span class="small muted">per day<br>last 7 days</span></div>
        ${lolli(days.map(d=>d.toLocaleDateString(LOC(),{weekday:'narrow'})),raised,6,v=>v+' today')}</section>
      <section class="card"><div class="card-h"><h3>Fixed within deadline</h3><button class="circ" data-act="nav" data-v="escalations" aria-label="Late jobs">${ic('arrow')}</button></div>
        ${dial(P.closed.length?P.onTime/P.closed.length:1,onPct+'%',P.closed.length+' closed · 30 days')}
        <div class="spread small"><span class="muted">Average time to fix</span><b class="num">${dur(P.avgFix)}</b></div></section>
      <section class="card" data-tour="late"><div class="card-h"><h3>Late jobs</h3><span class="st ${lateList.length?'bad':'ok'}">${lateList.length?lateList.length+' late':'None late'}</span></div>
        <div class="list">${lateList.slice(0,5).map(t=>{const a=alertFor(t.id)||S.alerts.find(x=>x.id==='tk-'+t.id);const p=propById(t.propId);return `<div class="li click" data-act="openTicket" data-id="${t.id}"><span class="ibox bad">${ic('alarm')}</span><div class="grow"><div class="ttl clip">${esc(t.title)}</div><div class="tiny muted clip">${esc(p.code)} · waiting on ${esc(waitingOn(t))} · ${a?'alert #'+a.count+' sent '+ago(a.last_at):'first alert pending'}</div></div><span class="st bad">${dur(Date.now()-dueOf(t))}</span></div>`}).join('')||empty('Every open job is within its deadline.')}</div>
        ${lateList.length>5?`<button class="btn sm" data-act="nav" data-v="escalations">View all ${lateList.length}</button>`:''}</section>
    </div>
    <div class="grid" style="grid-template-columns:minmax(0,2fr) minmax(0,1fr)" >
      <section class="card" style="min-width:0"><div class="card-h"><h3>This week</h3><span class="small muted">Planned maintenance, inspections, lease ends${can(u,'fleet')?', vehicle services':''}</span></div>${weekPlanner(u)}</section>
      <section class="card"><div class="card-h"><h3>Open jobs by stage</h3><button class="circ" data-act="nav" data-v="tickets" aria-label="Maintenance board">${ic('arrow')}</button></div>
        ${hbars(byStage.map(x=>({label:x.s.short,value:x.n,tone:x.s.k.includes('approval')||x.s.k==='reported'?'gold':''})))}
        <div class="note small">Every job runs: guard report → supervisor → manager → owner → technician → review.</div></section>
    </div>
    <div class="grid g2">
      <section class="card"><div class="card-h"><h3>Buildings needing attention</h3><button class="circ" data-act="nav" data-v="buildings" aria-label="Buildings">${ic('arrow')}</button></div>
        <div class="list">${att.map(x=>`<div class="li click" data-act="openProp" data-id="${x.p.id}"><span class="ibox">${ic('bld')}</span><div class="grow"><div class="ttl clip">${esc(x.p.name)}</div><div class="tiny muted">${x.p.code} · supervisor ${esc(nameOf(x.p.supId))}</div></div>${x.l?st(x.l+' late','bad'):''}${st(x.o+' open','')}</div>`).join('')||empty('No open jobs.')}</div></section>
      ${can(u,'warehouse')||can(u,'fleet')?`<section class="card"><div class="card-h"><h3>Stores & fleet</h3></div>
        <div class="grid" style="grid-template-columns:1fr 1fr;gap:12px"><div class="card inset" style="padding:14px;cursor:pointer" data-act="nav" data-v="warehouse"><span class="small muted">Low stock items</span><span class="big md ${low.length?'':''}">${low.length}</span><span class="tiny muted">of ${S.items.length} in ${STORES.length} stores</span></div>
        <div class="card inset" style="padding:14px;cursor:pointer" data-act="nav" data-v="fleet"><span class="small muted">Vehicles in repair</span><span class="big md">${inRep.length}</span><span class="tiny muted">${inRep.filter(j=>j.status==='in_progress'&&Date.now()>new Date(j.startedAt).getTime()+j.expectedH*HOUR).length} over expected time</span></div></div>
        <div class="list">${low.slice(0,3).map(i=>`<div class="li click" data-act="openItem" data-id="${i.id}"><span class="ibox gold">${ic('box')}</span><div class="grow"><div class="ttl clip">${esc(i.name)}</div><div class="tiny muted">${esc(i.store)} · bin ${esc(i.bin)}</div></div>${st(i.qty+' / '+i.min+' '+i.unit,i.qty?'warn':'bad')}</div>`).join('')}</div></section>`:`<section class="card"><div class="card-h"><h3>Vacant units</h3><button class="circ" data-act="nav" data-v="inspections" aria-label="Inspections">${ic('arrow')}</button></div><div class="list">${P.units.filter(x=>x.status==='Vacant').slice(0,5).map(x=>`<div class="li click" data-act="editUnit" data-id="${x.id}"><span class="ibox gold">${ic('door')}</span><div class="grow"><div class="ttl mono">${esc(x.code)}</div><div class="tiny muted">${esc(x.kind)}</div></div>${st('Vacant','gold')}</div>`).join('')||empty('No vacant units.')}</div></section>`}
    </div></section>`;
}
function dashTech(u,q){const mine=S.tickets.filter(t=>t.techId===u.id);const active=mine.filter(t=>t.status==='in_progress')[0];const vj=S.vjobs.filter(j=>j.workerId===u.id&&j.status!=='done');
  const done=mine.filter(t=>t.job&&Date.now()-new Date(t.job.completedAt)<30*DAY);
  let timer='';if(active){const el=Date.now()-new Date(active.createdAt).getTime();const tot=dueOf(active)-new Date(active.createdAt).getTime();timer=`<section class="card"><div class="card-h"><h3>Current job deadline</h3><button class="circ" data-act="openTicket" data-id="${active.id}" aria-label="Open job">${ic('arrow')}</button></div>${dial(el/tot,hhmm(el),isLate(active)?'Late by '+dur(Date.now()-dueOf(active)):dur(dueOf(active)-Date.now())+' left',isLate(active)?'late':'ontrack')}<p class="small clip">${esc(active.title)} · ${esc(propById(active.propId).code)}</p></section>`}
  else if(vj[0]){const j=vj[0];timer=vehicleTimerCard(j)}
  return `<section class="stack loose"><div class="spread" style="align-items:flex-end"><div class="figs"><div class="fig"><span class="big">${mine.filter(t=>t.status==='assigned').length}</span><small>${ic('clip')}To start</small></div><div class="fig"><span class="big">${mine.filter(t=>t.status==='in_progress').length}</span><small>${ic('wrench')}On site</small></div><div class="fig ${mine.filter(isLate).length?'alert':''}"><span class="big">${mine.filter(isLate).length}</span><small>${ic('alarm')}Late</small></div><div class="fig"><span class="big">${done.length}</span><small>${ic('check')}Done · 30 days</small></div></div></div>
   <div class="grid g3">${taskPanel(u,q,'My jobs')}${timer||`<section class="card"><h3>Current job</h3>${empty('No job in progress.')}</section>`}
   ${vj.length?`<section class="card"><div class="card-h"><h3>Vehicle repairs</h3><button class="circ" data-act="nav" data-v="fleet">${ic('arrow')}</button></div><div class="list">${vj.map(j=>{const v=vehById(j.vehicleId);return `<div class="li click" data-act="openVJob" data-id="${j.id}"><span class="ibox">${ic('truck')}</span><div class="grow"><div class="ttl">${esc(v.plate)} · ${esc(j.issue)}</div><div class="tiny muted">${esc(j.garage)} · expected ${j.expectedH} h</div></div>${vjPill(j)}</div>`}).join('')}</div></section>`:''}</div>
   <section class="card"><div class="card-h"><h3>Recent jobs</h3></div>${table([{h:'Ticket'},{h:'Issue'},{h:'Building'},{h:'Stage'},{h:'Deadline'}],mine.slice(0,10).map(t=>({act:'openTicket',id:t.id,cells:[`<span class="mono">${t.id}</span>`,esc(t.title),esc(propById(t.propId).code),stage(t.status),slaPill(t)]})))}</section></section>`}
function dashProc(u,q){const low=S.items.filter(i=>i.qty<=i.min);const val=sum(S.items,i=>i.qty*i.cost);const mo=S.moves.filter(m=>m.at.slice(0,7)===ym(TODAY));
  return `<section class="stack loose"><div class="figs"><div class="fig"><span class="big">${q.length}</span><small>${ic('cash')}Purchases to approve</small></div><div class="fig ${low.length?'alert':''}"><span class="big">${low.length}</span><small>${ic('box')}Low stock</small></div><div class="fig"><span class="big">${moneyK(val)}</span><small>${ic('layers')}Stock value</small></div><div class="fig"><span class="big">${mo.length}</span><small>${ic('swap')}Movements this month</small></div></div>
  <div class="grid g3">${taskPanel(u,q,'Purchases waiting')}<section class="card"><div class="card-h"><h3>Reorder now</h3><button class="circ" data-act="nav" data-v="warehouse">${ic('arrow')}</button></div><div class="list">${low.slice(0,8).map(i=>`<div class="li click" data-act="openItem" data-id="${i.id}"><span class="ibox gold">${ic('box')}</span><div class="grow"><div class="ttl clip">${esc(i.name)}</div><div class="tiny muted">${esc(i.supplier)}</div></div>${st(i.qty+' / '+i.min,i.qty?'warn':'bad')}</div>`).join('')||empty('Nothing below reorder level.')}</div></section>
  <section class="card"><div class="card-h"><h3>Latest movements</h3></div><div class="list">${S.moves.slice(0,7).map(m=>{const i=itemById(m.itemId);return `<div class="li"><span class="ibox ${m.type==='in'?'ok':''}">${ic(m.type==='in'?'download':m.type==='out'?'upload':'swap')}</span><div class="grow"><div class="ttl clip">${esc(i?i.name:'')}</div><div class="tiny muted">${ago(m.at)} · ${esc(m.ref||'')}</div></div><b class="num">${m.type==='out'?'−':m.qty<0?'':'+'}${Math.abs(m.qty)}</b></div>`}).join('')}</div></section></div></section>`}

/* ================= escalations ================= */
function viewEscalations(u){
  const tks=ticketsFor(u).filter(isLate).sort((a,b)=>dueOf(a)-dueOf(b));const rep=setting('repeatH');
  const vj=S.vjobs.filter(j=>j.status==='in_progress'&&j.startedAt&&Date.now()>new Date(j.startedAt).getTime()+j.expectedH*HOUR);
  const roles=(setting('escalateRoles')||[]).map(r=>ROLES[r]?ROLES[r].short.toLowerCase()+(r==='admin'?'':'s'):r).join(', ');
  return `<div class="callout night"><div class="row nowrap" style="align-items:flex-start"><span class="ibox" style="background:var(--gold);color:#1A1A1A;border:0">${ic('alarm')}</span><div class="stack tight"><b style="font-weight:500">Every job must be fixed within ${setting('slaUrgentH')} hours (Emergency, Urgent) or ${setting('slaNormalH')} hours (Normal, Planned).</b>
    <span style="color:var(--night-dim)">Once a job is late, an alert goes to the ${esc(roles)} by email, WhatsApp and in the platform, and repeats every ${rep} hours until the job is closed. The clock starts when the issue is reported, so slow approvals count too.</span></div></div></div>
   <div class="figs"><div class="fig alert"><span class="big">${tks.length}</span><small>${ic('alarm')}Late jobs</small></div><div class="fig"><span class="big">${sum(tks,t=>(alertFor(t.id)||{count:0}).count)}</span><small>${ic('bell')}Alerts sent</small></div><div class="fig"><span class="big">${tks.length?dur(Date.now()-dueOf(tks[0])):'0m'}</span><small>${ic('clock')}Longest overdue</small></div><div class="fig ${vj.length?'alert':''}"><span class="big">${vj.length}</span><small>${ic('truck')}Vehicle repairs over time</small></div></div>
   ${table([{h:'Ticket'},{h:'Issue'},{h:'Building'},{h:'Stuck at'},{h:'Due'},{h:'Late by'},{h:'Alerts'},{h:'Next alert'}],tks.map(t=>{const a=alertFor(t.id);const p=propById(t.propId);const next=a?new Date(new Date(a.last_at).getTime()+rep*HOUR):null;
     return {act:'openTicket',id:t.id,cells:[`<span class="mono">${t.id}</span>`,`<div class="ttl">${esc(t.title)}</div><span class="tiny muted">${priPill(t.priority)}</span>`,`${esc(p.code)}<div class="tiny muted">${esc(p.name)}</div>`,`${stage(t.status)}<div class="tiny muted">${esc(waitingOn(t))} · ${dur(stageAge(t))}</div>`,`<span class="small">${fmtDT(new Date(dueOf(t)).toISOString())}</span>`,st(dur(Date.now()-dueOf(t)),'bad'),a?`<b>#${a.count}</b> <span class="tiny muted">${ago(a.last_at)}</span>`:'<span class="tiny muted">Queued</span>',next?`<span class="small">${next<new Date()?'Due now':hm(next)}</span>`:'—']}}),{empty:'No late jobs. Every open job is within its deadline.',emptyIcon:'check'})}
   ${vj.length?`<section class="stack"><h2>Vehicle repairs over expected time</h2>${table([{h:'Job'},{h:'Vehicle'},{h:'Issue'},{h:'Worker'},{h:'Expected'},{h:'Elapsed'},{h:'Alerts'}],vj.map(j=>{const v=vehById(j.vehicleId);const el=Date.now()-new Date(j.startedAt).getTime();return {act:'openVJob',id:j.id,cells:[`<span class="mono">${j.id}</span>`,`${esc(v.plate)}<div class="tiny muted">${esc(v.make+' '+v.model)}</div>`,esc(j.issue),esc(nameOf(j.workerId)),j.expectedH+' h',st(dur(el),'bad'),'#'+(j.alerts||(alertFor(j.id)||{count:0}).count)]}}))}</section>`:''}
   ${can(u,'sendReminders')||u.role==='admin'?`<div class="row"><button class="btn dark" data-act="escalateNow">${ic('bell')}Send late-job alerts now</button><span class="small muted">${online?'Runs automatically every 5 minutes on the server.':'Demo mode: runs every minute in this browser.'}</span></div>`:''}`;
}

/* ================= buildings ================= */
function propStats(p){const units=S.units.filter(u=>u.propId===p.id);const occ=units.filter(u=>u.status==='Occupied').length;const open=S.tickets.filter(t=>t.propId===p.id&&isOpen(t));
  return {units:units.length,occ,vac:units.filter(u=>u.status==='Vacant').length,open:open.length,late:open.filter(isLate).length,docs:p.docs.filter(d=>d.expiry&&daysUntil(d.expiry)<=45).length}}
const DOC_KINDS=['Licence','Permit','Certificate','Contract','Insurance','Title deed','Drawing','Other'];
function bCover(p){const ph=p.photos||[];const c=ph.find(x=>x.id===p.coverId)||ph[0];return c&&(c.url||c.data)?`<img class="bphoto" src="${esc(c.url||c.data)}" alt="" loading="lazy">`:bldArt(p)}
function coverId(p){const ph=p.photos||[];return (ph.find(x=>x.id===p.coverId)||ph[0]||{}).id}
function photoGallery(p,edit){const ph=p.photos||[];const cv=coverId(p);
  return `<div class="stack"><div class="spread"><div><h3>Building photos</h3><span class="small muted">The cover photo is shown on the Buildings page.</span></div>${edit?`<label class="btn sm dark">${ic('cam')}Add photos<input type="file" accept="image/*" multiple hidden data-change="propPhotos" data-p="${p.id}"></label>`:''}</div>
  ${ph.length?`<div class="pgal">${ph.map(x=>`<figure class="pg ${x.id===cv?'cover':''}"><a href="${esc(x.url||x.data||'#')}" target="_blank" rel="noopener"><img src="${esc(x.url||x.data||'')}" alt="" loading="lazy"></a>${x.id===cv?`<span class="pg-badge">${ic('star')}<span>Cover</span></span>`:''}${edit?`<div class="pg-acts">${x.id!==cv?`<button class="btn xs" data-act="propCover" data-p="${p.id}" data-id="${x.id}">Set as cover</button>`:''}<button class="btn xs" data-act="propPhotoDel" data-p="${p.id}" data-id="${x.id}" aria-label="Remove photo" title="Remove photo">${ic('trash')}</button></div>`:''}</figure>`).join('')}</div>`:`<p class="small muted">${edit?'No photos yet. Add photos of the building, entrance and facilities.':'No photos yet.'}</p>`}</div>`}
const xfRow=x=>`<div class="xf"><input name="xk" placeholder="Field name" value="${esc(x.k||'')}" aria-label="Field name"><input name="xv" placeholder="Value" value="${esc(x.v||'')}" aria-label="Value"><button type="button" class="iconbtn" data-act="xfDel" aria-label="Remove field" title="Remove field">${ic('trash')}</button></div>`;
function editPropForm(id){const p=propById(id);const u=me();if(!p||!can(u,'editProperty'))return;ui.drawer={k:'propEdit',id};const ex=p.extra||[];
  drawer(dHead('Edit building',p.code+' · '+esc(p.name))+`<form data-form="editProperty" class="stack" style="flex:1;min-height:0"><input type="hidden" name="propId" value="${p.id}"><div class="d-body">
   <div class="fgrid">
    <label class="f">Building name<input name="name" required value="${esc(p.name)}"></label>
    <label class="f">Category<select name="type">${TYPES.map(t=>`<option ${t===p.type?'selected':''}>${t}</option>`).join('')}</select></label>
    <label class="f">Country<select name="country">${Object.entries(COUNTRY).map(([k,c])=>`<option value="${k}" ${k===p.country?'selected':''}>${c.name}</option>`).join('')}</select></label>
    <label class="f">Area / district<input name="area" required value="${esc(p.area||'')}"></label>
    <label class="f">City / governorate<input name="city" required value="${esc(p.city||'')}"></label>
    <label class="f">Address<input name="address" value="${esc(p.address||'')}"></label>
    <label class="f">PACI number<input name="paci" inputmode="numeric" value="${esc(p.paci||'')}"></label>
    <label class="f">Plot<input name="plot" value="${esc(p.plot&&p.plot!=='—'?p.plot:'')}"></label>
    <label class="f">Floors<input name="floors" type="number" min="1" value="${p.floors||1}"></label>
    <label class="f">Built-up area (m²)<input name="bua" type="number" min="0" value="${p.bua||0}"></label>
    <label class="f">Year built<input name="year" type="number" min="1900" max="2100" value="${p.yearBuilt||''}"></label>
    <label class="f">Owner<input name="owner" value="${esc(p.owner||'')}"></label>
   </div>
   <div class="stack"><div><h3>Additional details</h3><span class="small muted">Name each field yourself, e.g. "Electricity meter no.", "Parking spaces" or "Insurance company".</span></div>
    <div class="stack tight" id="xf">${(ex.length?ex:[{k:'',v:''}]).map(xfRow).join('')}</div>
    <div class="row"><button type="button" class="btn sm" data-act="xfAdd">${ic('plus')}Add field</button></div></div>
   <p class="note">Photos, licences and documents are managed in the building's Photos and Documents tabs. All amounts are in Kuwaiti dinar (KWD).</p>
   </div>
   <div class="d-foot"><button type="button" class="btn" data-act="openProp" data-id="${p.id}">Cancel</button><button class="btn dark" type="submit">${ic('check')}Save building</button></div></form>`,true)}
function docForm(pid,did){const p=propById(pid);const d=did?p.docs.find(x=>x.id===did):null;
  dialog(dHead(d?'Edit document':'Add a document',p.code)+`<form data-form="saveDoc" class="stack"><input type="hidden" name="propId" value="${p.id}"><input type="hidden" name="docId" value="${d?d.id:''}">
   <div class="fgrid"><label class="f">Document name<span class="hint">Name it the way you file it, e.g. "Fire licence 2026"</span><input name="title" required value="${esc(d?d.title:'')}" placeholder="e.g. Elevator maintenance contract"></label>
   <label class="f">Type<select name="kind">${DOC_KINDS.map(k=>`<option ${(d&&d.kind)===k?'selected':''}>${k}</option>`).join('')}</select></label>
   <label class="f">Reference / licence no.<input name="ref" value="${esc(d&&d.ref&&d.ref!=='—'?d.ref:'')}"></label>
   <label class="f">Issue date<input name="issued" type="date" value="${d&&d.issued||''}"></label>
   <label class="f">Expiry date<input name="expiry" type="date" value="${d&&d.expiry||''}"></label>
   <label class="f">${d&&d.url?'Replace file':'File'}${d&&d.url?`<span class="hint">Current: ${esc(d.file)}</span>`:''}<input name="file" type="file" accept="image/*,application/pdf,.doc,.docx,.xls,.xlsx"></label></div>
   <label class="f">Notes<textarea name="notes" rows="2">${esc(d&&d.notes||'')}</textarea></label>
   <div class="row spread">${d?`<button type="button" class="btn" data-act="docDelAsk" data-p="${p.id}" data-id="${d.id}">${ic('trash')}Delete</button>`:'<span></span>'}<div class="row"><button type="button" class="btn" data-act="closeDlg" data-p="${p.id}">Cancel</button><button class="btn dark" type="submit">${d?'Save document':'Add document'}</button></div></div></form>`)}
function viewBuildings(u){
  const f=ui.f;const all=propsFor(u);const list=all.filter(p=>(!f.btype||p.type===f.btype)&&(!f.bc||p.country===f.bc)&&(!f.bq||(p.name+' '+p.code+' '+p.area+' '+p.city).toLowerCase().includes(f.bq.toLowerCase())));
  return `<div class="spread"><div class="chips">${['',...TYPES].map(t=>`<button class="chip ${(f.btype||'')===t?'on':''}" data-act="setF" data-k="btype" data-val="${t}">${t||'All'} <span class="n">${t?all.filter(p=>p.type===t).length:all.length}</span></button>`).join('')}</div>
     ${can(u,'editProperty')?`<button class="btn dark" data-act="addProperty">${ic('plus')}Add building</button>`:''}</div>
   <div class="filters"><label class="search">${ic('search')}<input id="bq" data-input="f" data-k="bq" placeholder="Search name, code, area" value="${esc(f.bq||'')}"></label>
    <select id="bc" data-change="setF" data-k="bc"><option value="">All countries</option>${Object.entries(COUNTRY).map(([k,c])=>`<option value="${k}" ${f.bc===k?'selected':''}>${c.name}</option>`).join('')}</select><span class="small muted">${list.length} of ${all.length} buildings</span></div>
   <div class="bgrid">${list.map(p=>{const s=propStats(p);return `<button class="bcard" data-act="openProp" data-id="${p.id}"><div class="bimg">${bCover(p)}<span class="tp">${st(p.type,'night')}</span><span class="cd">${p.code}</span>${can(u,'editProperty')?`<span class="bedit" role="button" tabindex="0" data-act="editProp" data-id="${p.id}" aria-label="Edit building" title="Edit building">${ic('pencil')}</span>`:''}</div>
     <div class="bbody"><div><h3>${esc(p.name)}</h3><span class="small muted">${esc(p.area)}, ${esc(p.city)} · ${COUNTRY[p.country].name}</span></div>
     <div class="stack tight"><div class="spread small"><span class="dim">${s.occ} of ${s.units} units let</span><b class="num">${Math.round(s.occ/Math.max(1,s.units)*100)}%</b></div><div class="meter"><i class="gold" style="width:${s.occ/Math.max(1,s.units)*100}%"></i></div></div>
     <div class="spread small"><span class="row nowrap" style="gap:6px">${av(p.supId,true)}<span class="clip">${esc(nameOf(p.supId))}</span></span><span class="row nowrap" style="gap:6px" title="Security guard">${ic('shield')}<span class="clip dim">${esc(nameOf(p.guardId).split(' ')[0])}</span></span></div>
     <div class="row">${s.late?st(s.late+' late','bad'):''}${s.open?st(s.open+' open',''):st('No open jobs','ok')}${s.vac?st(s.vac+' vacant','gold'):''}${s.docs?st(s.docs+' docs expiring','warn'):''}</div></div></button>`}).join('')||empty('No buildings match these filters.','bld')}</div>`;
}
function propertyDrawer(id,re){
  const u=me();const p=propById(id);if(!p)return;ui.drawer={k:'prop',id};const tab=ui.f.ptab||'overview';const s=propStats(p);const edit=can(u,'editProperty');
  const tabs=[['overview','Overview'],['photos','Photos ('+(p.photos||[]).length+')'],['floors','Floors & units'],['docs','Documents ('+p.docs.length+')'],['jobs','Maintenance ('+s.open+')'],['team','Team']];
  let body='';
  if(tab==='overview')body=`<div class="bimg" style="border-radius:18px;height:170px">${bCover(p)}</div>
    <dl class="kv"><div><dt>Code</dt><dd class="mono">${p.code}</dd></div><div><dt>Category</dt><dd>${p.type}</dd></div><div><dt>Country</dt><dd>${COUNTRY[p.country].name}</dd></div><div><dt>Currency</dt><dd>KWD · Kuwaiti dinar</dd></div><div><dt>Address</dt><dd>${esc(p.address)}, ${esc(p.area)}</dd></div>${p.paci?`<div><dt>PACI number</dt><dd class="mono">${p.paci}</dd></div>`:''}<div><dt>Plot</dt><dd>${esc(p.plot)}</dd></div><div><dt>Floors</dt><dd>${p.floors}</dd></div><div><dt>Built-up area</dt><dd class="num">${p.bua.toLocaleString()} m²</dd></div><div><dt>Year built</dt><dd>${p.yearBuilt}</dd></div><div><dt>Owner</dt><dd>${esc(p.owner)}</dd></div><div><dt>Occupancy</dt><dd>${s.occ}/${s.units} units</dd></div><div><dt>Open jobs</dt><dd>${s.open}${s.late?' · <span style="color:var(--bad)">'+s.late+' late</span>':''}</dd></div>${(p.extra||[]).map(x=>`<div><dt>${esc(x.k)}</dt><dd>${esc(x.v)||'—'}</dd></div>`).join('')}</dl>
    <div class="stack"><div class="spread"><h3>Planned preventive maintenance</h3><span class="small muted">Reminders go to the matching technician, supervisor and guard</span></div>
    ${table([{h:'Service'},{h:'Team'},{h:'Every'},{h:'Next due'},{h:''}],p.ppm.map(m=>({cells:[esc(m.label),esc(m.cat),m.every+' days',expPill(m.next,7),edit||can(u,'mgrApprove')?`<button class="btn sm" data-act="ppmDone" data-p="${p.id}" data-id="${m.id}">Mark done</button>`:'']})))}</div>`;
  if(tab==='floors')body=`<div class="card flat"><div class="card-h"><h3>Stacking plan</h3><span class="small muted">Tap an apartment to open it</span></div>${stackPlan(p.id,null,{act:'editUnit'})}</div>
    ${edit?`<form class="card inset" data-form="addUnits"><input type="hidden" name="propId" value="${p.id}"><div class="spread"><h3>Building module · add floors and units</h3><span class="small muted">Creates units floor by floor</span></div>
      <div class="fgrid"><label class="f">From floor<input name="from" type="number" min="0" value="1" required></label><label class="f">To floor<input name="to" type="number" min="0" value="${p.floors}" required></label><label class="f">Units per floor<input name="per" type="number" min="1" max="30" value="4" required></label>
      <label class="f">Unit type<select name="kind">${['Apartment 1BR','Apartment 2BR','Apartment 3BR','Studio','Penthouse','Office suite','Shop','Showroom','Kiosk','Warehouse','Workshop','Parking bay'].map(k=>`<option>${k}</option>`).join('')}</select></label>
      <label class="f">Rental or lease<select name="tenancy"><option>Rental</option><option>Lease</option></select></label><label class="f">Area (m²)<input name="area" type="number" min="1" value="110"></label><label class="f">Rent / month (${p.currency})<input name="rent" type="number" min="0" step="any" value="${p.currency==='KWD'?350:3500}"></label></div>
      <div class="row"><button class="btn dark" type="submit">${ic('plus')}Generate units</button><span class="small muted">Floor 0 is the ground floor. Existing unit numbers are skipped.</span></div></form>`:''}`;
  if(tab==='docs')body=`<div class="spread"><p class="small muted">Licences, permits and documents for this building. Documents within 45 days of expiry trigger reminders.</p>${edit?`<button class="btn dark sm" data-act="docAdd" data-p="${p.id}">${ic('plus')}Add document</button>`:''}</div>
    ${table([{h:'Document'},{h:'File'},{h:'Reference'},{h:'Status'},{h:''}],p.docs.map(d=>({cells:[`<b style="font-weight:500">${esc(d.title)}</b><div class="tiny muted">${d.kind?esc(d.kind)+' · ':''}Uploaded ${fmtDate(d.uploaded)}${d.issued?' · Issued '+fmtDate(d.issued):''}</div>${d.notes?`<div class="tiny muted">${esc(d.notes)}</div>`:''}`,d.url?`<a href="${esc(d.url)}" target="_blank" rel="noopener" class="small">${esc(d.file)}</a>`:`<span class="small muted">${esc(d.file)}</span>`,`<span class="mono small">${esc(d.ref)}</span>`,expPill(d.expiry,45),edit?`<span class="row nowrap"><button class="btn sm" data-act="docEdit" data-p="${p.id}" data-id="${d.id}">${ic('pencil')}Edit</button><label class="btn sm" for="up-${d.id}">${ic('upload')}${d.url?'Replace':'Upload'}<input id="up-${d.id}" type="file" hidden data-change="docFile" data-p="${p.id}" data-d="${d.id}"></label></span>`:'']})))}`;
  if(tab==='photos')body=photoGallery(p,edit);
  if(tab==='jobs')body=ticketTable(S.tickets.filter(t=>t.propId===p.id),u);
  if(tab==='team'){const sups=S.users.filter(x=>x.role==='supervisor'),gs=S.users.filter(x=>x.role==='guard');
    body=`${edit?`<form class="card inset" data-form="propTeam"><input type="hidden" name="propId" value="${p.id}"><div class="fgrid"><label class="f">Building supervisor<span class="hint">Pre-approves reports, manages tenants</span><select name="supId">${sups.map(x=>`<option value="${x.id}" ${x.id===p.supId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label>
      <label class="f">Security guard<span class="hint">Reports issues, patrols, logs visitors</span><select name="guardId">${gs.map(x=>`<option value="${x.id}" ${x.id===p.guardId?'selected':''}>${esc(x.name)} · ${esc(x.title)}</option>`).join('')}</select></label></div><div class="row"><button class="btn dark" type="submit">Save assignment</button></div></form>`:''}
     ${table([{h:'Name'},{h:'Role'},{h:'Phone'},{h:'Email'}],[p.supId,p.guardId,...usersByRole('manager'),...usersByRole('owner')].map(id=>{const x=userById(id);return {cells:[avName(id,false),esc(x.title),`<span class="mono small">${esc(x.phone)}</span>`,`<span class="small">${esc(x.email)}</span>`]}}))}`}
  drawer(dHead(esc(p.name),p.code+' · '+p.type,`<span class="small muted">${esc(p.area)}, ${esc(p.city)} · ${COUNTRY[p.country].name}</span>${edit?`<div class="row" style="margin-top:8px"><button class="btn sm dark" data-act="editProp" data-id="${p.id}">${ic('pencil')}Edit building</button><button class="btn sm" data-act="docAdd" data-p="${p.id}">${ic('doc')}Add document</button></div>`:''}`)+`<div class="d-body"><div class="tabs">${tabs.map(t=>`<button class="${tab===t[0]?'on':''}" data-act="ptab" data-t="${t[0]}">${t[1]}</button>`).join('')}</div>${body}</div>`,true);
}
function addPropertyForm(){const sups=S.users.filter(x=>x.role==='supervisor');
  drawer(dHead('Add building','New property')+`<form data-form="addProperty" class="stack" style="flex:1;min-height:0"><div class="d-body"><div class="fgrid">
   <label class="f">Building name<input name="name" required placeholder="e.g. Salwa Residence"></label><label class="f">Category<select name="type">${TYPES.map(t=>`<option>${t}</option>`).join('')}</select></label>
   <label class="f">Country<select name="country">${Object.entries(COUNTRY).map(([k,c])=>`<option value="${k}">${c.name}</option>`).join('')}</select></label><label class="f">Area / district<input name="area" required placeholder="Salwa"></label><label class="f">City / governorate<input name="city" required placeholder="Hawalli"></label>
   <label class="f">Address<input name="address" placeholder="Block 5, Street 12, Building 30"></label><label class="f">PACI number (Kuwait)<input name="paci" inputmode="numeric"></label><label class="f">Floors<input name="floors" type="number" min="1" value="6"></label>
   <label class="f">Built-up area (m²)<input name="bua" type="number" min="1" value="4000"></label><label class="f">Year built<input name="year" type="number" min="1950" max="2035" value="2015"></label><label class="f">Owner<input name="owner" value="Al-Kazemi Real Estate Co."></label>
   <label class="f">Building supervisor<select name="supId">${sups.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join('')}</select></label><label class="f">New guard's name<input name="guard" required placeholder="Full name"></label><label class="f">Guard's mobile<input name="guardPhone" placeholder="+965 5xxx xxxx"></label></div>
   <p class="note">The country's document checklist and the planned maintenance schedule are created automatically. Add floors and units next from the building's Floors tab.</p></div>
   <div class="d-foot"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn dark" type="submit">Create building</button></div></form>`)}

/* ================= units ================= */
function viewUnits(u){
  const f=ui.f;const ids=propIds(u);const all=S.units.filter(x=>ids.has(x.propId));let list=all;
  if(f.uten)list=list.filter(x=>x.tenancy===f.uten);if(f.ustat)list=list.filter(x=>x.status===f.ustat);if(f.uexp)list=list.filter(x=>x.end&&x.tenantId&&daysUntil(x.end)<=60);
  if(f.uq)list=list.filter(x=>(x.code+' '+x.kind+' '+((tenantById(x.tenantId)||{}).name||'')).toLowerCase().includes(f.uq.toLowerCase()));
  const k=[['Occupied',all.filter(x=>x.status==='Occupied').length],['Vacant',all.filter(x=>x.status==='Vacant').length],['Under maintenance',all.filter(x=>x.status==='Under maintenance').length],['Leases ending ≤ 60 days',all.filter(x=>x.end&&x.tenantId&&daysUntil(x.end)<=60&&daysUntil(x.end)>=0).length],['Expired / holding over',all.filter(x=>x.end&&x.tenantId&&daysUntil(x.end)<0).length]];
  return `<div class="figs">${k.map((x,i)=>`<div class="fig ${i===4&&x[1]?'alert':''}"><span class="big md">${x[1]}</span><small>${x[0]}</small></div>`).join('')}</div>
   ${ui.scope?`<section class="card"><div class="card-h"><h3>${esc(propById(ui.scope).name)} · stacking plan</h3><span class="small muted">Tap an apartment to open it</span></div>${stackPlan(ui.scope,null,{act:'editUnit'})}</section>`:`<p class="note small">Pick a building at the top to see its floor-by-floor stacking plan.</p>`}
   <div class="filters"><label class="search">${ic('search')}<input id="uq" data-input="f" data-k="uq" placeholder="Unit or tenant" value="${esc(f.uq||'')}"></label>
    <select id="uten" data-change="setF" data-k="uten"><option value="">Rental and lease</option><option ${f.uten==='Rental'?'selected':''}>Rental</option><option ${f.uten==='Lease'?'selected':''}>Lease</option></select>
    <select id="ustat" data-change="setF" data-k="ustat"><option value="">Any status</option>${['Occupied','Vacant','Under maintenance','Reserved'].map(s=>`<option ${f.ustat===s?'selected':''}>${s}</option>`).join('')}</select>
    <label class="check"><input type="checkbox" id="uexp" data-change="setFc" data-k="uexp" ${f.uexp?'checked':''}>Ending in 60 days</label></div>
   ${table([{h:'Unit'},{h:'Building'},{h:'Type'},{h:'m²',r:1},{h:'Tenancy'},{h:'Status'},{h:'Tenant'},{h:'Rent / month',r:1},{h:'Lease ends'}],list.slice(0,300).map(x=>{const p=propById(x.propId);const t=tenantById(x.tenantId);
     return {act:'editUnit',id:x.id,cells:[`<span class="mono">${esc(x.code)}</span>`,`<span class="small">${esc(p.name)}</span>`,esc(x.kind),`<span class="num">${x.area}</span>`,st(x.tenancy,x.tenancy==='Lease'?'info':''),unitStatusPill(x.status),esc(t?t.name:'—'),`<span class="num">${money(x.rent,p.currency)}</span>`,x.end&&x.tenantId?expPill(x.end):'—']}}),{empty:'No units match.'})}
   ${list.length>300?`<p class="small muted">Showing 300 of ${list.length}. Narrow with the filters or pick a building.</p>`:''}`;
}
function unitDrawer(id){const u=me();const x=unitById(id);const p=propById(x.propId);const t=tenantById(x.tenantId);ui.drawer={k:'unit',id};const edit=can(u,'editProperty')||can(u,'editTenant');
  const free=S.tenants.filter(tt=>!tt.unitId);const insp=S.insp.filter(i=>i.unitId===x.id);const jobs=S.tickets.filter(tk=>tk.unitId===x.id);
  drawer(dHead(esc(x.code),esc(p.name),`<div class="row">${st(x.tenancy,x.tenancy==='Lease'?'info':'')}${unitStatusPill(x.status)}</div>`)+`<form data-form="saveUnit" style="display:contents"><input type="hidden" name="id" value="${x.id}"><div class="d-body">
   <fieldset ${edit?'':'disabled'} style="border:0;padding:0;margin:0"><div class="fgrid">
   <label class="f">Unit number<input name="no" value="${esc(x.no)}"></label><label class="f">Floor<input name="floor" type="number" value="${x.floor}"></label><label class="f">Type<input name="kind" value="${esc(x.kind)}"></label><label class="f">Area (m²)<input name="area" type="number" value="${x.area}"></label>
   <label class="f">Rental or lease<select name="tenancy"><option ${x.tenancy==='Rental'?'selected':''}>Rental</option><option ${x.tenancy==='Lease'?'selected':''}>Lease</option></select></label>
   <label class="f">Status<select name="status">${['Occupied','Vacant','Under maintenance','Reserved'].map(s=>`<option ${x.status===s?'selected':''}>${s}</option>`).join('')}</select></label>
   <label class="f">Rent / month (${p.currency})<input name="rent" type="number" step="any" value="${x.rent}"></label><label class="f">Lease start<input name="start" type="date" value="${x.start||''}"></label><label class="f">Lease expiry<input name="end" type="date" value="${x.end||''}"></label><label class="f">Next maintenance<input name="nextMaint" type="date" value="${x.nextMaint||''}"></label>
   <label class="f">Tenant<select name="tenantId"><option value="">— Vacant —</option>${t?`<option value="${t.id}" selected>${esc(t.name)}</option>`:''}${free.map(v=>`<option value="${v.id}">${esc(v.name)} (unassigned)</option>`).join('')}</select></label></div></fieldset>
   ${t?`<div class="card inset"><div class="spread"><b style="font-weight:500">${esc(t.name)}</b><button type="button" class="btn sm" data-act="editTenant" data-id="${t.id}">Open tenant</button></div><span class="small dim">${esc(t.kind)} · ${esc(t.idNo)} · ${esc(t.phone)} · ${esc(t.email)} · deposit ${money(t.deposit,p.currency)} · pays ${t.payFreq.toLowerCase()}</span></div>`:''}
   ${x.status==='Vacant'?`<div class="callout"><div class="spread"><div class="stack tight"><b style="font-weight:500">Vacant unit</b><span class="small dim">${insp.length?'Last inspected '+fmtDate(insp[0].at):'Not inspected yet'}</span></div>${can(u,'inspect')?`<button type="button" class="btn dark" data-act="newInsp" data-unit="${x.id}">${ic('cam')}Start inspection</button>`:''}</div></div>`:''}
   ${insp.length?`<div class="stack"><h3>Inspections</h3>${table([{h:'Report'},{h:'Date'},{h:'Inspector'},{h:'Repairs'},{h:'Status'}],insp.map(i=>({act:'openInsp',id:i.id,cells:[`<span class="mono">${i.id}</span>`,fmtDate(i.at),esc(nameOf(i.inspectorId)),money(i.totalCost,i.currency),inspPill(i.status)]})))}</div>`:''}
   ${jobs.length?`<div class="stack"><h3>Maintenance history</h3>${ticketTable(jobs,u)}</div>`:''}</div>
   <div class="d-foot"><button type="button" class="btn" data-act="close">Close</button>${can(u,'editTenant')?`<button type="button" class="btn" data-act="newTenant" data-unit="${x.id}">${ic('plus')}New tenant</button>`:''}${edit?'<button class="btn dark" type="submit">Save unit</button>':''}</div></form>`)}

/* ================= tenants ================= */
function viewTenants(u){const ids=propIds(u);const q=(ui.f.tq||'').toLowerCase();
  const list=S.tenants.filter(t=>{const x=t.unitId&&unitById(t.unitId);return (!x||ids.has(x.propId))&&(!q||(t.name+' '+(x?x.code:'')+' '+t.phone+' '+t.email).toLowerCase().includes(q))});
  return `<div class="spread"><div class="filters"><label class="search">${ic('search')}<input id="tq" data-input="f" data-k="tq" placeholder="Name, unit, phone or email" value="${esc(ui.f.tq||'')}"></label><span class="small muted">${list.length} tenants</span></div>${can(u,'editTenant')?`<button class="btn dark" data-act="newTenant">${ic('plus')}Add tenant</button>`:''}</div>
   ${table([{h:'Tenant'},{h:'ID / CR'},{h:'Unit'},{h:'Lease'},{h:'Rent',r:1},{h:'Pays'},{h:'Mobile'}],list.slice(0,300).map(t=>{const x=t.unitId&&unitById(t.unitId);const p=x&&propById(x.propId);
     return {act:'editTenant',id:t.id,cells:[`<span class="who"><span class="av sm ${avTone(t.id)}">${esc(initials(t.name))}</span><span class="stack tight" style="gap:0"><b>${esc(t.name)}</b><span class="tiny muted">${esc(t.kind)}${t.nationality?' · '+esc(t.nationality):''}</span></span></span>`,`<span class="mono small">${esc(t.idNo)}</span>`,x?`<span class="mono small">${esc(x.code)}</span>`:'<span class="muted small">Not assigned</span>',x&&x.end?expPill(x.end):'—',x?`<span class="num">${money(x.rent,p.currency)}</span>`:'—',esc(t.payFreq),`<span class="mono small">${esc(t.phone)}</span>`]}}))}`}
function tenantDrawer(id,unitId){const u=me();const t=id?tenantById(id):{name:'',kind:'Individual',idNo:'',nationality:'',phone:'',email:'',unitId:unitId||'',deposit:0,payFreq:'Monthly',regNo:''};ui.drawer=id?{k:'tenant',id}:null;
  const x=t.unitId&&unitById(t.unitId);const ids=propIds(u);const free=S.units.filter(v=>ids.has(v.propId)&&(!v.tenantId||v.tenantId===t.id||v.id===unitId));
  const rent=id?S.rent.filter(r=>r.unitId===t.unitId).sort((a,b)=>b.month.localeCompare(a.month)):[];
  drawer(dHead(id?esc(t.name):'Add tenant','Tenant record')+`<form data-form="saveTenant" style="display:contents"><input type="hidden" name="id" value="${id||''}"><div class="d-body"><fieldset ${can(u,'editTenant')?'':'disabled'} style="border:0;padding:0;margin:0"><div class="fgrid">
   <label class="f">Full name or company<input name="name" required value="${esc(t.name)}"></label><label class="f">Tenant type<select name="kind"><option ${t.kind==='Individual'?'selected':''}>Individual</option><option ${t.kind==='Company'?'selected':''}>Company</option></select></label>
   <label class="f">Civil ID / CR number<input name="idNo" value="${esc(t.idNo)}"></label><label class="f">Nationality<input name="nationality" value="${esc(t.nationality||'')}"></label><label class="f">Mobile<input name="phone" value="${esc(t.phone)}"></label><label class="f">Email<input name="email" type="email" value="${esc(t.email)}"></label>
   <label class="f">Unit<select name="unitId"><option value="">— None —</option>${free.map(v=>`<option value="${v.id}" ${v.id===(t.unitId||unitId)?'selected':''}>${esc(v.code)} · ${esc(v.kind)}${!v.tenantId?' (vacant)':''}</option>`).join('')}</select></label>
   <label class="f">Lease start<input name="start" type="date" value="${x&&x.start||iso(TODAY)}"></label><label class="f">Lease expiry<input name="end" type="date" value="${x&&x.end||iso(addD(TODAY,365))}"></label><label class="f">Security deposit<input name="deposit" type="number" step="any" value="${t.deposit}"></label>
   <label class="f">Payment frequency<select name="payFreq">${['Monthly','Quarterly','Semi-annual','Annual'].map(o=>`<option ${t.payFreq===o?'selected':''}>${o}</option>`).join('')}</select></label><label class="f">Lease registration<input name="regNo" value="${esc(t.regNo||'')}"></label></div></fieldset>
   ${rent.length?`<div class="stack"><h3>Rent history</h3>${table([{h:'Month'},{h:'Amount',r:1},{h:'Status'},{h:'Paid on'},{h:'Receipt'}],rent.map(r=>({cells:[monthLabel(r.month),`<span class="num">${money(r.amount,r.cur)}</span>`,rentPill(r),r.paidOn?fmtDate(r.paidOn):'—',`<span class="mono small">${r.receipt||'—'}</span>`]})))}</div>`:''}</div>
   <div class="d-foot"><button type="button" class="btn" data-act="close">Close</button>${can(u,'editTenant')?'<button class="btn dark" type="submit">Save tenant</button>':''}</div></form>`)}

/* ================= vacant inspections ================= */
const inspPill=s=>st(s==='draft'?'Draft':s==='submitted'?'Awaiting review':'Reviewed',s==='draft'?'':s==='submitted'?'warn':'ok');
function viewInspections(u){const ids=propIds(u);const f=ui.f;let list=S.insp.filter(i=>ids.has(i.propId));const all=list;if(f.istat)list=list.filter(i=>i.status===f.istat);
  const vac=S.units.filter(x=>ids.has(x.propId)&&x.status==='Vacant');const recent=new Set(S.insp.filter(i=>Date.now()-new Date(i.at)<90*DAY).map(i=>i.unitId));const todo=vac.filter(x=>!recent.has(x.id));
  return `<div class="spread"><div class="figs"><div class="fig"><span class="big md">${vac.length}</span><small>${ic('door')}Vacant units</small></div><div class="fig ${todo.length?'alert':''}"><span class="big md">${todo.length}</span><small>${ic('clip')}Not inspected · 90 days</small></div><div class="fig"><span class="big md">${all.filter(i=>i.status==='submitted').length}</span><small>${ic('eye')}Awaiting review</small></div><div class="fig"><span class="big md">${moneyK(sum(all.filter(i=>i.status!=='reviewed'),i=>toKWD(i.totalCost,i.currency)))}</span><small>${ic('wrench')}Repairs to approve</small></div></div>
    ${can(u,'inspect')?`<button class="btn dark" data-act="newInsp" data-tour="new-insp">${ic('cam')}New inspection</button>`:''}</div>
   <div class="chips">${[['','All'],['draft','Draft'],['submitted','Awaiting review'],['reviewed','Reviewed']].map(([k,l])=>`<button class="chip ${(f.istat||'')===k?'on':''}" data-act="setF" data-k="istat" data-val="${k}">${l} <span class="n">${k?all.filter(i=>i.status===k).length:all.length}</span></button>`).join('')}</div>
   ${table([{h:'Report'},{h:'Unit'},{h:'Building'},{h:'Inspector'},{h:'Date'},{h:'Rooms'},{h:'Repairs',r:1},{h:'Status'}],list.map(i=>{const x=unitById(i.unitId);const p=propById(i.propId);const dmg=i.rooms.filter(r=>r.cond==='Damaged').length;
     return {act:'openInsp',id:i.id,cells:[`<span class="mono">${i.id}</span>`,`<span class="mono small">${esc(x?x.code:'')}</span><div class="tiny muted">${esc(x?x.kind:'')}</div>`,`<span class="small">${esc(p.name)}</span>`,avName(i.inspectorId),`<span class="small">${fmtDate(i.at)}</span>`,dmg?st(dmg+' damaged','bad'):st('All good','ok'),`<span class="num">${money(i.totalCost,i.currency)}</span>`,inspPill(i.status)]}}),{empty:'No inspections yet.',emptyIcon:'clip'})}
   ${todo.length?`<section class="card"><div class="card-h"><h3>Vacant units waiting for an inspection</h3><span class="small muted">${todo.length} units</span></div><div class="list">${todo.slice(0,8).map(x=>`<div class="li"><span class="ibox gold">${ic('door')}</span><div class="grow"><div class="ttl mono">${esc(x.code)}</div><div class="tiny muted">${esc(x.kind)} · ${esc(propById(x.propId).name)}</div></div>${can(u,'inspect')?`<button class="btn sm" data-act="newInsp" data-unit="${x.id}">Inspect</button>`:''}</div>`).join('')}</div></section>`:''}`}
function newInspection(unitId){const u=me();const x=unitId&&unitById(unitId);
  const withVac=propsFor(u).filter(p=>S.units.some(v=>v.propId===p.id&&v.status==='Vacant'));ui.wiz.insp={step:x?2:1,propId:x?x.propId:(ui.scope&&withVac.some(p=>p.id===ui.scope)?ui.scope:((withVac[0]||propsFor(u)[0]||{}).id)),unitId:x?x.id:null,rooms:[],meters:{elec:'',water:''},keys:2,summary:''};if(x)ui.wiz.insp.rooms=defaultRooms(x);inspWizard()}
function defaultRooms(x){const k=x.kind;const names=k==='Studio'?['Entrance & hall','Living room','Kitchen','Bathroom 1','AC units','Electrical & DB']:k==='Apartment 3BR'||k==='Penthouse'?ROOMS:/Apartment/.test(k)?['Entrance & hall','Living room','Kitchen','Bedroom 1','Master bedroom','Bathroom 1','Bathroom 2','Balcony','AC units','Electrical & DB']:['Main area','Washroom','Storage','AC units','Electrical & DB','Shutters & doors'];
  return names.map(n=>({name:n,cond:'Good',notes:'',photos:[],damages:[]}))}
function inspWizard(){const w=ui.wiz.insp;const u=me();ui.drawer={k:'inspWiz'};const props=propsFor(u);const x=w.unitId&&unitById(w.unitId);let body='';
  if(w.step===1)body=`<label class="f">Building<select id="iw-prop" data-change="iwProp">${props.map(p=>`<option value="${p.id}" ${w.propId===p.id?'selected':''}>${p.code} · ${esc(p.name)}</option>`).join('')}</select></label>
    <div class="stack"><b style="font-weight:500">Choose the vacant apartment</b><span class="small muted">Only vacant units can be picked.</span>${stackPlan(w.propId,w.unitId,{act:'iwUnit',onlyVacant:true})}</div>`;
  if(w.step===2)body=`<div class="note small">Go room by room. Set the condition, add photos of every room, and list each damage with an estimated repair cost.</div>${w.rooms.map((r,i)=>`<section class="card flat" style="gap:10px"><div class="spread"><b style="font-weight:500">${esc(r.name)}</b><div class="okbad">${['Good','Fair','Damaged'].map(c=>`<button type="button" class="${r.cond===c?'on '+(c==='Good'?'ok':c==='Fair'?'na':'bad'):''}" data-act="iwCond" data-i="${i}" data-c="${c}">${c}</button>`).join('')}</div></div>
     ${r.photos.length?media(r.photos):''}
     <div class="row"><label class="btn sm" for="iw-ph-${i}">${ic('cam')}Add photos<input id="iw-ph-${i}" type="file" accept="image/*" capture="environment" multiple hidden data-change="iwPhoto" data-i="${i}"></label>${r.cond!=='Good'?`<button type="button" class="btn sm" data-act="iwDmg" data-i="${i}">${ic('plus')}Add damage</button>`:''}</div>
     ${r.cond!=='Good'?`<input data-input="iw" data-path="rooms.${i}.notes" id="iw-n-${i}" placeholder="Notes for this room" value="${esc(r.notes)}">`:''}
     ${r.damages.map((d,j)=>`<div class="matrow" style="grid-template-columns:minmax(0,1fr) 110px 36px"><input id="iw-d-${i}-${j}" data-input="iw" data-path="rooms.${i}.damages.${j}.item" placeholder="What is damaged" value="${esc(d.item)}"><input id="iw-c-${i}-${j}" type="number" min="0" step="any" data-input="iw" data-path="rooms.${i}.damages.${j}.cost" placeholder="Cost" value="${d.cost||''}"><button type="button" class="circ" data-act="iwDmgRm" data-i="${i}" data-j="${j}" aria-label="Remove">${ic('x')}</button></div>`).join('')}</section>`).join('')}
     <button type="button" class="btn sm" data-act="iwRoom">${ic('plus')}Add another room</button>`;
  if(w.step===3){const total=sum(w.rooms,r=>sum(r.damages,d=>+d.cost||0));const p=propById(w.propId);
    body=`<div class="fgrid"><label class="f">Electricity meter reading<input id="iw-me" data-input="iw" data-path="meters.elec" value="${esc(w.meters.elec)}" inputmode="numeric"></label><label class="f">Water meter reading<input id="iw-mw" data-input="iw" data-path="meters.water" value="${esc(w.meters.water)}" inputmode="numeric"></label><label class="f">Keys handed over<input id="iw-k" type="number" min="0" data-input="iw" data-path="keys" value="${w.keys}"></label></div>
    <label class="f">Summary<textarea id="iw-s" data-input="iw" data-path="summary" rows="3" placeholder="Overall condition and what must be done before re-letting">${esc(w.summary)}</textarea></label>
    <div class="card inset"><div class="spread"><span>${w.rooms.filter(r=>r.cond==='Damaged').length} damaged · ${w.rooms.filter(r=>r.cond==='Fair').length} fair · ${w.rooms.filter(r=>r.cond==='Good').length} good</span><b class="num">${money(total,p.currency)}</b></div><span class="small muted">Estimated repairs. A supervisor or manager reviews the report and can turn each damage into a repair ticket.</span></div>`}
  const steps=['Apartment','Rooms & photos','Readings & summary'];
  drawer(dHead(x?'Inspect '+esc(x.code):'New vacant inspection','Step '+w.step+' of 3 · '+steps[w.step-1],`<div class="wiz-steps">${steps.map((s,i)=>`<i class="${i+1<w.step?'done':i+1===w.step?'on':''}"></i>`).join('')}</div>`)+`<div class="d-body">${body}</div>
   <div class="d-foot">${w.step>1?`<button class="btn" data-act="iwBack">${ic('left')}Back</button>`:`<button class="btn" data-act="close">Cancel</button>`}${w.step===2?`<button class="btn" data-act="iwSave">Save draft</button>`:''}${w.step<3?`<button class="btn dark" data-act="iwNext" ${w.step===1&&!w.unitId?'disabled':''}>Next${ic('right')}</button>`:`<button class="btn gold" data-act="iwSubmit">${ic('check')}Submit report</button>`}</div>`,true)}
function damageCat(s){s=String(s).toLowerCase();if(/ac|cool/.test(s))return 'AC / HVAC';if(/tap|leak|wc|toilet|shower|drain|pipe/.test(s))return 'Washroom & Plumbing';if(/light|socket|switch|power|db/.test(s))return 'Electrical';if(/door|window|handle|lock|glass|wardrobe/.test(s))return 'Doors, Locks & Glass';if(/pest|cockroach/.test(s))return 'Pest Control';return 'Civil & Painting'}
function inspectionDrawer(id){const u=me();const i=S.insp.find(x=>x.id===id);if(!i)return;ui.drawer={k:'insp',id};const p=propById(i.propId);const x=unitById(i.unitId);
  const acts=[];if(i.status==='draft'&&(i.inspectorId===u.id||u.role==='admin'))acts.push(`<button class="btn dark" data-act="inspEdit" data-id="${i.id}">Continue inspection</button>`);
  if(i.status==='submitted'&&can(u,'reviewInspection'))acts.push(`<button class="btn dark" data-act="inspReview" data-id="${i.id}">${ic('check')}Mark reviewed</button>`);
  if(i.status!=='draft'&&i.totalCost>0&&(can(u,'mgrApprove')||can(u,'supApprove'))&&!i.ticketIds.length)acts.push(`<button class="btn gold" data-act="inspTickets" data-id="${i.id}">${ic('wrench')}Create repair tickets</button>`);
  drawer(dHead('Inspection report '+i.id,esc(p.name)+' · '+esc(x?x.code:''),`<div class="row">${inspPill(i.status)}${i.ticketIds.length?st(i.ticketIds.length+' repair tickets','info'):''}</div>`)+`<div class="d-body">${inspReportHTML(i)}
   ${i.ticketIds.length?`<div class="stack"><h3>Repair tickets</h3>${ticketTable(i.ticketIds.map(ticketById).filter(Boolean),u)}</div>`:''}</div>
   <div class="d-foot"><button class="btn" data-act="close">Close</button><button class="btn" data-act="printInsp" data-id="${i.id}">${ic('print')}Print or save PDF</button>${acts.join('')}</div>`,true)}
function inspReportHTML(i){const p=propById(i.propId);const x=unitById(i.unitId);const photos=i.rooms.flatMap(r=>r.photos.map(ph=>Object.assign({room:r.name},ph)));
  return `<div class="report"><div class="rh"><img src="${LOGO_INK}" alt="Al-Kazemi Group"><div style="text-align:right"><b style="font-size:18px;font-weight:500">Vacant unit inspection report</b><div class="small">${i.id} · ${fmtDT(i.at)}</div></div></div>
   <table><tr><th>Building</th><td>${esc(p.code)} · ${esc(p.name)}</td><th>Unit</th><td>${esc(x?x.code:'')} · ${esc(x?x.kind:'')}</td></tr><tr><th>Inspector</th><td>${esc(nameOf(i.inspectorId))}</td><th>Status</th><td>${i.status==='reviewed'?'Reviewed by '+esc(nameOf(i.reviewedBy))+' on '+fmtDate(i.reviewedAt):i.status==='submitted'?'Awaiting review':'Draft'}</td></tr><tr><th>Electricity meter</th><td>${esc(i.meters.elec||'—')}</td><th>Water meter</th><td>${esc(i.meters.water||'—')}</td></tr><tr><th>Keys handed over</th><td>${i.keys}</td><th>Estimated repairs</th><td><b>${money(i.totalCost,i.currency)}</b></td></tr></table>
   <table><thead><tr><th>Room</th><th>Condition</th><th>Notes</th><th>Damage</th><th style="text-align:right">Est. cost</th></tr></thead><tbody>${i.rooms.map(r=>`<tr><td>${esc(r.name)}</td><td>${r.cond}</td><td>${esc(r.notes||'')}</td><td>${r.damages.map(d=>esc(d.item)).join('<br>')||'—'}</td><td style="text-align:right">${r.damages.length?r.damages.map(d=>money(d.cost,i.currency)).join('<br>'):'—'}</td></tr>`).join('')}</tbody></table>
   ${i.summary?`<div><b style="font-weight:500">Summary</b><p>${esc(i.summary)}</p></div>`:''}
   <div><b style="font-weight:500">Photos (${photos.length})</b><div class="ph" style="margin-top:8px">${photos.slice(0,24).map(ph=>`<div>${ph.url||ph.data?`<img src="${esc(ph.url||ph.data)}" alt="">`:''}<span style="position:absolute;left:4px;bottom:3px;background:#fff;padding:0 4px;border-radius:4px">${esc(ph.room)}${ph.sample?' · sample':''}</span></div>`).join('')}</div></div>
   <div class="sig"><div>Inspected by</div><div>Building supervisor</div><div>Operations manager</div></div></div>`}

function rentPill(r){if(r.paidOn)return st('Paid','ok');const d=daysUntil(r.due);if(d<-5)return st('Overdue '+(-d)+'d','bad');return st('Due','warn')}

/* ================= maintenance ================= */
function ticketTable(list,u){return table([{h:'Ticket'},{h:'Issue'},{h:'Building'},{h:'Stage'},{h:'Priority'},{h:'Deadline'},{h:u?'Your action':''}],list.map(t=>{const p=propById(t.propId);
  return {act:'openTicket',id:t.id,cells:[`<span class="mono">${t.id}</span>${t.emergency?'<div>'+st('Emergency','bad')+'</div>':''}`,`<div class="ttl">${esc(t.title)}</div><span class="tiny muted">${esc(t.category)} · ${esc(t.location)}</span>`,`${esc(p.code)}<div class="tiny muted">${esc(p.name)}</div>`,stage(t.status),priPill(t.priority),slaPill(t),u?`<span class="small">${esc(actionFor(t,u)||'—')}</span>`:'']}}),{empty:'No tickets here.',emptyIcon:'wrench'})}
function filteredTickets(u){const f=ui.f;let l=ticketsFor(u);
  if(f.tcat)l=l.filter(t=>t.category===f.tcat);if(f.tpri)l=l.filter(t=>t.priority===f.tpri);if(f.tmine)l=l.filter(t=>actionFor(t,u));if(f.tlate)l=l.filter(isLate);
  if(f.tk){const q=f.tk.toLowerCase();l=l.filter(t=>(t.id+' '+t.title+' '+propById(t.propId).name+' '+t.location).toLowerCase().includes(q))}return l}
function viewTickets(u){const f=ui.f;const l=filteredTickets(u);
  const cols=STAGES.filter(s=>!(u.role==='tech'&&['reported','mgr_approval','owner_approval'].includes(s.k)));
  const board=`<div style="display:grid;grid-auto-flow:column;grid-auto-columns:minmax(270px,1fr);gap:12px;overflow-x:auto;padding-bottom:8px" data-tour="board">${cols.map(s=>{const items=l.filter(t=>t.status===s.k).sort((a,b)=>dueOf(a)-dueOf(b));const show=s.k==='closed'||s.k==='rejected'?items.slice(0,12):items;
    return `<div class="card inset" style="padding:12px;gap:8px;border-radius:20px;min-height:160px"><div class="spread"><b style="font-weight:500">${s.l}</b><span class="st plain">${items.length}</span></div><span class="tiny muted" style="margin-top:-4px">${s.hint}</span>
    ${show.map(t=>{const p=propById(t.propId);const a=actionFor(t,u);return `<button class="card" style="padding:12px;gap:7px;text-align:left;cursor:pointer;border-radius:16px" data-act="openTicket" data-id="${t.id}"><div class="spread"><span class="mono tiny muted">${t.id}</span>${slaPill(t)}</div><b style="font-weight:500;line-height:1.3">${esc(t.title)}</b><span class="tiny muted">${esc(p.code)} · ${esc(t.category)}</span><div class="row" style="gap:6px">${priPill(t.priority)}${t.emergency?st('Emergency','bad'):''}</div>${a?`<span class="small" style="font-weight:500;color:var(--gold-ink)">→ ${esc(a)}</span>`:''}</button>`}).join('')}
    ${items.length>show.length?`<span class="tiny muted">+${items.length-show.length} more in list view</span>`:''}</div>`}).join('')}</div>`;
  return `<div class="spread"><div class="seg">${[['board','Board'],['list','List']].map(([k,l2])=>`<button class="${ui.tickMode===k?'on':''}" data-act="tickMode" data-m="${k}">${l2}</button>`).join('')}</div>
     ${can(u,'createTicket')?`<button class="btn dark" data-act="nav" data-v="report">${ic('plus')}New ticket</button>`:''}</div>
   <div class="filters"><label class="search">${ic('search')}<input id="tk" data-input="f" data-k="tk" placeholder="Ticket, issue or building" value="${esc(f.tk||'')}"></label>
    <select id="tcat" data-change="setF" data-k="tcat"><option value="">All categories</option>${CATS.map(c=>`<option ${f.tcat===c?'selected':''}>${c}</option>`).join('')}</select>
    <select id="tpri" data-change="setF" data-k="tpri"><option value="">Any priority</option>${Object.keys(PRI).map(k=>`<option value="${k}" ${f.tpri===k?'selected':''}>${PRI[k].l}</option>`).join('')}</select>
    <label class="check"><input type="checkbox" id="tmine" data-change="setFc" data-k="tmine" ${f.tmine?'checked':''}>Waiting on me</label><label class="check"><input type="checkbox" id="tlate" data-change="setFc" data-k="tlate" ${f.tlate?'checked':''}>Late only</label></div>
   ${ui.tickMode==='board'?board:ticketTable(l,u)}`}
function chainBar(t){const steps=[['reported','Reported'],['sup','Supervisor'],['mgr','Manager'],['own','Owner'],['tech','Technician'],['rev','Review'],['closed','Closed']];
  const reached=new Set(t.history.map(h=>h.status));const map={reported:'reported',sup:'mgr_approval',mgr:'owner_approval',own:'assigned',tech:'job_done',rev:'closed',closed:'closed'};
  const cur={reported:'sup',mgr_approval:'mgr',owner_approval:'own',assigned:'tech',in_progress:'tech',job_done:'rev',procurement:'rev'}[t.status];
  return `<div class="stepbar" style="--n:${steps.length}">${steps.map(([k,l])=>{let c='';if(k==='reported')c='done';else if(t.status==='rejected'){c=reached.has(map[k])?'done':''}else if(k===cur)c='cur';else if(reached.has(map[k])||t.status==='closed')c='done';
    if(t.status==='rejected'&&!c&&!steps.slice(0,steps.findIndex(s=>s[0]===k)).some(([kk])=>!reached.has(map[kk])&&kk!=='reported'))c='rej';
    return `<div class="${c}"><span>${l}</span><i>${c==='done'?ic('check'):c==='cur'?'Now':c==='rej'?'Rejected':''}</i></div>`}).join('')}</div>`}
function ticketDrawer(id){const u=me();const t=ticketById(id);if(!t)return;ui.drawer={k:'ticket',id};const p=propById(t.propId);const cur=p.currency;const a=actionFor(t,u);let box='';
  const techOpts=sel=>S.users.filter(x=>x.role==='tech'&&!(x.skills||[]).includes('Fleet')).map(x=>`<option value="${x.id}" ${sel===x.id?'selected':''}>${esc(x.name)} · ${esc((x.skills||[]).join(', '))}</option>`).join('');
  if(t.status==='reported'&&a)box=`<form class="callout" data-form="tkSup"><input type="hidden" name="id" value="${t.id}"><b style="font-weight:500">Supervisor pre-approval</b><span class="small dim">Check the photos, confirm the category and urgency, and give a cost estimate. It then goes to the operations manager.</span>
    <div class="fgrid"><label class="f">Category<select name="category">${CATS.map(c=>`<option ${c===t.category?'selected':''}>${c}</option>`).join('')}</select></label><label class="f">Priority<select name="priority">${Object.keys(PRI).map(k=>`<option value="${k}" ${k===t.priority?'selected':''}>${PRI[k].l} (${slaHours(k)} h)</option>`).join('')}</select></label><label class="f">Estimated cost (${cur})<input name="estCost" type="number" min="0" step="any" value="${t.estCost||''}" required></label></div>
    <label class="f">Note to manager<input name="note" placeholder="Optional"></label><div class="row"><button class="btn dark" type="submit">${ic('check')}Pre-approve</button><button class="btn danger" type="button" data-act="tkReject" data-id="${t.id}">Reject</button></div></form>`;
  if(t.status==='mgr_approval'&&a){const sug=S.users.find(x=>x.role==='tech'&&(x.skills||[]).includes(t.category));const lim=+setting('ownerThreshold')||0;
    box=`<form class="callout" data-form="tkMgr"><input type="hidden" name="id" value="${t.id}"><b style="font-weight:500">Manager approval</b><span class="small dim">Supervisor estimate ${money(t.estCost,cur)}. ${lim>0&&toKWD(t.estCost,cur)<lim?'Below the owner approval limit, so it goes straight to the technician.':'After you approve, the owner gives final approval.'}</span>
    <div class="fgrid"><label class="f">Technician<select name="techId">${techOpts(t.techId||(sug&&sug.id))}</select></label><label class="f">Priority<select name="priority">${Object.keys(PRI).map(k=>`<option value="${k}" ${k===t.priority?'selected':''}>${PRI[k].l}</option>`).join('')}</select></label></div>
    <label class="f">Instruction<input name="note" placeholder="Optional"></label><div class="row"><button class="btn dark" type="submit">${ic('check')}Approve</button><button class="btn danger" type="button" data-act="tkReject" data-id="${t.id}">Reject</button></div></form>`}
  if(t.status==='owner_approval'&&a)box=`<form class="callout" data-form="tkOwner"><input type="hidden" name="id" value="${t.id}"><b style="font-weight:500">Owner approval</b><span class="small dim">Supervisor and manager have approved. Estimate ${money(t.estCost,cur)} · technician ${esc(nameOf(t.techId))}.</span>
    <label class="f">Comment<input name="note" placeholder="Optional"></label><div class="row"><button class="btn gold" type="submit">${ic('check')}Give final approval</button><button class="btn danger" type="button" data-act="tkReject" data-id="${t.id}">Reject</button></div></form>`;
  if(t.status==='assigned'&&a)box=`<div class="callout"><b style="font-weight:500">Assigned to ${esc(nameOf(t.techId))}</b><span class="small dim">Start the job when you arrive on site. The guard confirms your arrival.</span><div class="row"><button class="btn dark" data-act="tkStart" data-id="${t.id}">${ic('play')}Start work on site</button></div></div>`;
  if(t.status==='in_progress'&&a)box=`<form class="callout" data-form="tkJob"><input type="hidden" name="id" value="${t.id}"><b style="font-weight:500">Record the job done</b>
    <label class="f">Work carried out<textarea name="summary" required rows="2" placeholder="What was fixed and how"></textarea></label>
    <div class="stack tight"><span class="eyebrow">Materials (${cur}) · pick from the warehouse to deduct stock</span><datalist id="itemlist">${S.items.map(i=>`<option value="${esc(i.name)}">${esc(i.store)} · ${i.qty} ${esc(i.unit)} in stock</option>`).join('')}</datalist><div id="mats" class="stack tight">${matRow()}</div><button class="btn sm" type="button" data-act="addMat" style="align-self:flex-start">${ic('plus')}Add material</button></div>
    <div class="fgrid"><label class="f">Labour cost (${cur})<input name="labour" type="number" min="0" step="any" value="0" required></label><label class="f">After photos or video<input name="after" type="file" accept="image/*,video/*" multiple></label></div>
    <label class="check"><input type="checkbox" name="needsProc">Items must be purchased (send to procurement)</label><div class="row"><button class="btn dark" type="submit">${ic('check')}Submit job done</button></div></form>`;
  if(t.status==='job_done'&&a)box=`<div class="callout"><b style="font-weight:500">Review the completed job</b><span class="small dim">${t.job&&t.job.needsProc?'The technician says items must be purchased.':'No purchase requested.'} Total cost ${t.job?money(t.job.total,cur):'—'}.</span><div class="row"><button class="btn dark" data-act="tkClose" data-id="${t.id}">${ic('check')}Close ticket</button><button class="btn" data-act="tkToProc" data-id="${t.id}">Send to procurement</button></div></div>`;
  if(t.status==='procurement'&&a)box=`<form class="callout" data-form="tkProc"><input type="hidden" name="id" value="${t.id}"><b style="font-weight:500">Approve the purchase</b><div class="fgrid"><label class="f">Supplier<input name="vendor" required placeholder="Supplier name"></label><label class="f">Approved amount (${cur})<input name="amount" type="number" step="any" min="0" value="${t.job?t.job.materialCost:0}" required></label></div><div class="row"><button class="btn dark" type="submit">${ic('check')}Approve and close</button><button class="btn" type="button" data-act="tkReturn" data-id="${t.id}">Return to manager</button></div></form>`;
  const guardHere=u.role==='guard'&&(u.props||[]).includes(t.propId)||u.role==='admin';
  if(guardHere&&['assigned','in_progress'].includes(t.status))box+=`<div class="callout night"><div class="spread"><div class="stack tight"><b style="font-weight:500">Technician at the gate?</b><span class="small" style="color:var(--night-dim)">Confirm when ${esc(nameOf(t.techId))} arrives on site.</span></div><button class="btn gold" data-act="tkArrive" data-id="${t.id}">${ic('check')}Confirm arrival</button></div></div>`;
  const al=alertFor(t.id);
  const lateBox=isLate(t)?`<div class="callout bad"><div class="spread"><div class="stack tight"><b style="font-weight:500;color:var(--bad)">Late by ${dur(Date.now()-dueOf(t))}</b><span class="small dim">Waiting on ${esc(waitingOn(t))} for ${dur(stageAge(t))}. ${al?'Alert #'+al.count+' sent '+ago(al.last_at)+'; next in '+dur(new Date(al.last_at).getTime()+setting('repeatH')*HOUR-Date.now())+'.':'First alert is queued.'}</span></div>${can(u,'mgrApprove')||u.role==='admin'?`<button class="btn sm" data-act="escalateOne" data-id="${t.id}">${ic('bell')}Alert now</button>`:''}</div></div>`:'';
  const job=t.job?`<section class="stack"><h3>Job done record</h3><dl class="kv"><div><dt>Technician</dt><dd>${esc(nameOf(t.job.by))}</dd></div><div><dt>Completed</dt><dd>${fmtDT(t.job.completedAt)}</dd></div><div><dt>Labour</dt><dd class="num">${money(t.job.labour,cur)}</dd></div><div><dt>Materials</dt><dd class="num">${money(t.job.materialCost,cur)}</dd></div><div><dt>Total</dt><dd class="num"><b>${money(t.job.total,cur)}</b></dd></div></dl><p>${esc(t.job.summary)}</p>
    ${t.job.materials.length?table([{h:'Material'},{h:'Qty',r:1},{h:'Unit cost',r:1},{h:'Line',r:1}],t.job.materials.map(m=>({cells:[esc(m.item)+(m.itemId?' <span class="tag">from stock</span>':''),m.qty,money(m.cost,cur),money(m.qty*m.cost,cur)]}))):''}<span class="eyebrow">After</span>${media(t.job.after)}</section>`:'';
  drawer(dHead(esc(t.title),t.id+' · '+esc(t.category),`<div class="row">${stage(t.status)}${priPill(t.priority)}${slaPill(t)}${t.emergency?st('Emergency','bad'):''}</div>`)+`<div class="d-body">${chainBar(t)}${lateBox}${box}
   <dl class="kv"><div><dt>Building</dt><dd>${esc(p.code)} · ${esc(p.name)}</dd></div><div><dt>Location</dt><dd>${esc(t.location)}</dd></div><div><dt>Reported by</dt><dd>${esc(nameOf(t.reporterId))}</dd></div><div><dt>Reported</dt><dd>${fmtDT(t.createdAt)}</dd></div><div><dt>Deadline</dt><dd>${fmtDT(new Date(dueOf(t)).toISOString())}</dd></div><div><dt>Supervisor</dt><dd>${esc(nameOf(t.supId))}</dd></div><div><dt>Technician</dt><dd>${esc(t.techId?nameOf(t.techId):'Not assigned')}</dd></div><div><dt>Estimate</dt><dd class="num">${t.estCost?money(t.estCost,cur):'—'}</dd></div></dl>
   ${t.desc?`<p>${esc(t.desc)}</p>`:''}${t.rejectReason?`<div class="note"><b>Rejected:</b> ${esc(t.rejectReason)}</div>`:''}
   ${t.arrivals&&t.arrivals.length?`<div class="note">${ic('shield')} ${t.arrivals.map(x=>`Technician ${esc(x.name)} arrived ${fmtDT(x.at)} · confirmed by ${esc(nameOf(x.by))}`).join('<br>')}</div>`:''}
   <section class="stack"><h3>Photos and video from site</h3>${media(t.media)}</section>${job}
   ${t.proc?`<div class="note">Purchase order <b class="mono">${t.proc.po}</b> · ${esc(t.proc.vendor)} · ${money(t.proc.amount,cur)} · approved by ${esc(nameOf(t.proc.approvedBy))} on ${fmtDT(t.proc.at)}</div>`:''}
   <section class="stack"><h3>Timeline</h3><div class="timeline">${t.history.map(h=>`<div class="tl ${h.status==='closed'?'gold':h.status==='rejected'?'bad':''}"><i></i><div><div class="w">${fmtDT(h.at)}</div><div><b style="font-weight:500">${esc(nameOf(h.by))}</b> · ${esc(h.text)}</div></div></div>`).join('')}</div></section></div>`,true)}
function matRow(){return `<div class="matrow"><input name="mItem" list="itemlist" placeholder="Material"><input name="mQty" type="number" min="0" step="any" value="1" aria-label="Quantity"><input name="mCost" type="number" min="0" step="any" placeholder="Unit cost" aria-label="Unit cost"><button type="button" class="circ" data-act="rmMat" aria-label="Remove">${ic('x')}</button></div>`}

/* ================= report wizard (staff & guard) ================= */
function repState(u){if(!ui.wiz.rep){const ps=propsFor(u);ui.wiz.rep={step:1,propId:ui.scope||(ps[0]||{}).id,unitId:null,area:'',cat:'',media:[],pri:'P3',note:'',title:''}}return ui.wiz.rep}
function reportWizard(u,embedded){const w=repState(u);const props=propsFor(u);const p=propById(w.propId);const steps=['Building & apartment','What is wrong','Photos','Details'];let body='';
  if(w.step===1)body=`${props.length>1?`<label class="f">Building<select id="rw-prop" data-change="rwProp">${props.map(x=>`<option value="${x.id}" ${w.propId===x.id?'selected':''}>${x.code} · ${esc(x.name)}</option>`).join('')}</select></label>`:`<div class="card inset" style="padding:14px"><b style="font-weight:500">${esc(p.name)}</b><span class="small muted">${p.code}</span></div>`}
    <div class="stack tight"><b style="font-weight:500">Apartment or unit</b><span class="small muted">Tap the apartment, or choose a common area below.</span></div>${stackPlan(w.propId,w.unitId,{act:'rwUnit'})}
    <div class="chips">${LOCS.filter(l=>l!=='Flat / unit').map(l=>`<button type="button" class="chip ${w.area===l&&!w.unitId?'on':''}" data-act="rwArea" data-l="${l}">${l}</button>`).join('')}</div>`;
  if(w.step===2)body=`<div class="cats">${CATS.map(c=>`<button type="button" class="cat ${w.cat===c?'on':''}" data-act="rwCat" data-c="${c}">${ic(CAT_ICON[c])}<span>${c}</span></button>`).join('')}</div>`;
  if(w.step===3)body=`<label class="drop" for="rw-media"><span class="ibox gold">${ic('cam')}</span><span class="stack tight"><b style="font-weight:500">Take a photo or video</b><span class="small muted">${w.media.length?w.media.length+' file(s) attached. Add more if needed.':'Show the problem clearly. You can add several.'}</span></span><input id="rw-media" type="file" accept="image/*,video/*" capture="environment" multiple data-change="rwMedia"></label>${w.media.length?media(w.media):''}`;
  if(w.step===4)body=`<div class="card inset" style="padding:14px;gap:4px"><b style="font-weight:500">${esc(w.cat)}</b><span class="small dim">${esc(p.code)} · ${w.unitId?'Unit '+esc(unitById(w.unitId).no):esc(w.area||'Common area')} · ${w.media.length} photo/video</span></div>
    <label class="f">Short title<input id="rw-title" data-input="rw" data-path="title" value="${esc(w.title)}" placeholder="${esc((TITLES[w.cat]||['Describe the issue'])[0])}"></label>
    <div class="stack tight"><span class="small dim" style="font-weight:500">How urgent?</span><div class="seg">${Object.keys(PRI).map(k=>`<button type="button" class="${w.pri===k?'on':''}" data-act="rwPri" data-p="${k}">${PRI[k].l} · ${slaHours(k)}h</button>`).join('')}</div></div>
    <label class="f">Note<textarea id="rw-note" data-input="rw" data-path="note" rows="3" placeholder="e.g. water leaking from the ceiling near the lift">${esc(w.note)}</textarea></label>
    <p class="small muted">${u.role==='guard'?'Your supervisor is notified straight away.':'Goes straight to the operations manager for approval.'} It must be fixed within ${slaHours(w.pri)} hours.</p>`;
  const ok=w.step===1?(w.unitId||w.area):w.step===2?w.cat:true;
  return `<div class="wiz" data-tour="wizard"><div class="spread"><div class="stack tight"><span class="eyebrow">Step ${w.step} of 4</span><h2>${steps[w.step-1]}</h2></div>${embedded?'':''}</div><div class="wiz-steps">${steps.map((s,i)=>`<i class="${i+1<w.step?'done':i+1===w.step?'on':''}"></i>`).join('')}</div>${body}
   <div class="row" style="justify-content:space-between">${w.step>1?`<button class="btn" data-act="rwBack">${ic('left')}Back</button>`:'<span></span>'}${w.step<4?`<button class="btn dark lg" data-act="rwNext" ${ok?'':'disabled'}>${w.step===3&&!w.media.length?'Skip photos':'Next'}${ic('right')}</button>`:`<button class="btn gold lg" data-act="rwSend">${ic('check')}Send report</button>`}</div></div>`}
function viewReport(u){return `<div class="card" style="max-width:860px">${reportWizard(u)}</div>`}

/* ================= guard app ================= */
function viewGuardApp(u){const unread=S.notifs.filter(n=>n.userId===u.id&&!n.read).length;const p=propsFor(u)[0];
  return `<div class="guard"><div class="gtop"><img src="${EMBLEM}" alt="" style="width:34px"><div class="grow"><b style="font-weight:500">${esc(u.name)}</b><div class="tiny muted clip">${p?esc(p.code+' · '+p.name):''}</div></div>
     ${langBtn()}${themeBtn()}<button class="iconbtn" data-act="bell" aria-label="Notifications" data-tour="bell">${ic('bell')}${unread?`<span class="badge">${unread}</span>`:''}</button><div class="rel"><button class="iconbtn" data-act="menu" aria-label="Menu" data-tour="me">${ic('more')}</button>${ui.menu?`<div class="menu-pop"><button data-act="profile">${ic('user')}My profile</button><button data-act="tourStart">${ic('play')}Take the tour</button><button data-act="gTab" data-t="help">${ic('book')}Help</button><button data-act="theme">${ic(isDark()?'sun':'moon')}${isDark()?'Light':'Dark'} theme</button><hr><button data-act="logout">${ic('logout')}Sign out</button></div>`:''}</div></div>
   ${online?'':`<div class="note small">Demo mode: reports stay on this device.</div>`}
   ${guardBody(u)}</div>
   <nav class="bnav" style="display:flex">${[['home','Home','home'],['report','Report','cam'],['mine','My reports','list'],['help','Help','book']].map(([k,l,i])=>`<button class="bn ${ui.guardTab===k?'on':''} ${k==='report'?'cta':''}" data-act="gTab" data-t="${k}">${ic(i)}<span>${l}</span></button>`).join('')}</nav>`}
function guardBody(u,preview){const p=propsFor(u)[0]||S.props[0];const tab=preview?'home':ui.guardTab;
  if(tab==='report')return `<div class="card">${reportWizard(u)}</div>`;
  if(tab==='mine'){const mine=S.tickets.filter(t=>t.reporterId===u.id).slice(0,30);return `<h2>My reports</h2><div class="card"><div class="list">${mine.map(t=>`<div class="li click" data-act="openTicket" data-id="${t.id}"><span class="ibox">${ic(CAT_ICON[t.category]||'wrench')}</span><div class="grow"><div class="ttl clip">${esc(t.title)}</div><div class="tiny muted">${t.id} · ${ago(t.createdAt)} · ${esc(t.location)}</div></div>${stage(t.status)}</div>`).join('')||empty('You have not reported anything yet.','cam')}</div></div>`}
  if(tab==='help')return helpBody('guard');
  const today=S.patrols.filter(x=>x.propId===p.id&&iso(x.at)===iso(TODAY));const inside=S.visitors.filter(v=>v.propId===p.id&&!v.outAt);const open=S.tickets.filter(t=>t.propId===p.id&&isOpen(t));
  const coming=open.filter(t=>['assigned','in_progress'].includes(t.status));
  return `${preview?`<div class="spread"><h2>Guard tools</h2>${S.props.length>1&&me().role!=='guard'?`<span class="small muted">Preview for ${esc(p.code)} · these options appear only for security guards</span>`:''}</div>`:''}
   <div class="figs"><div class="fig"><span class="big md">${today.length}</span><small>${ic('route')}Patrols today</small></div><div class="fig"><span class="big md">${inside.length}</span><small>${ic('badge')}Visitors inside</small></div><div class="fig"><span class="big md">${open.length}</span><small>${ic('wrench')}Open jobs</small></div></div>
   <div class="gtiles" data-tour="gtiles">
    <button class="gtile main" data-act="gTab" data-t="report"><span class="ibox">${ic('cam')}</span><span class="stack tight"><b>Report an issue</b><span>Photo, apartment, done. Supervisor is alerted.</span></span></button>
    <button class="gtile sos" data-act="sos" data-tour="sos"><span class="ibox">${ic('sos')}</span><span class="stack tight"><b>Emergency</b><span>Fire, flood, lift entrapment</span></span></button>
    <button class="gtile" data-act="patrol" data-tour="patrol"><span class="ibox gold">${ic('route')}</span><span class="stack tight"><b>Patrol round</b><span>${today.length?'Last at '+hm(today[0].at):'Not done today'}</span></span></button>
    <button class="gtile" data-act="visitors"><span class="ibox">${ic('badge')}</span><span class="stack tight"><b>Visitors & contractors</b><span>${inside.length} inside now</span></span></button>
    <button class="gtile" data-act="techArrivals"><span class="ibox">${ic('wrench')}</span><span class="stack tight"><b>Technician arrival</b><span>${coming.length} jobs expected</span></span></button>
    <button class="gtile" data-act="newInsp"><span class="ibox">${ic('clip')}</span><span class="stack tight"><b>Vacant unit check</b><span>Photos of every room</span></span></button>
    ${preview?'':`<button class="gtile" data-act="gTab" data-t="mine"><span class="ibox">${ic('list')}</span><span class="stack tight"><b>My reports</b><span>${S.tickets.filter(t=>t.reporterId===u.id&&isOpen(t)).length} still open</span></span></button>`}
   </div>`}
function patrolDrawer(){const u=me();const p=propsFor(u)[0]||S.props[0];if(!ui.wiz.patrol||ui.wiz.patrol.propId!==p.id)ui.wiz.patrol={propId:p.id,start:Date.now(),checks:PATROL_POINTS.filter(x=>x!=='Lift machine room'||p.floors>2).map(pt=>({point:pt,res:'',note:'',photos:[]}))};const w=ui.wiz.patrol;ui.drawer={k:'patrol'};
  const done=w.checks.filter(c=>c.res).length;
  drawer(dHead('Patrol round',esc(p.code+' · '+p.name),`<div class="row">${st(done+' of '+w.checks.length+' checked',done===w.checks.length?'ok':'')}<span class="small muted">Started ${hm(w.start)}</span></div>`)+`<div class="d-body"><div class="list">${w.checks.map((c,i)=>`<div class="pcheck"><div class="stack tight"><b style="font-weight:500">${esc(c.point)}</b>${c.res==='issue'?`<input id="pc-n-${i}" data-input="patrol" data-i="${i}" placeholder="What is wrong?" value="${esc(c.note)}"><label class="btn sm" for="pc-ph-${i}" style="align-self:flex-start">${ic('cam')}${c.photos.length?c.photos.length+' photo':'Add photo'}<input id="pc-ph-${i}" type="file" accept="image/*" capture="environment" hidden data-change="pcPhoto" data-i="${i}"></label>`:''}</div>
     <div class="okbad">${[['ok','OK'],['issue','Issue'],['na','N/A']].map(([k,l])=>`<button type="button" class="${c.res===k?'on '+(k==='ok'?'ok':k==='issue'?'bad':'na'):''}" data-act="pcSet" data-i="${i}" data-r="${k}">${l}</button>`).join('')}</div></div>`).join('')}</div>
     <p class="small muted">Each "Issue" becomes a report for your supervisor automatically.</p></div>
   <div class="d-foot"><button class="btn" data-act="close">Cancel</button><button class="btn dark" data-act="patrolSubmit" ${done<w.checks.length?'disabled':''}>${ic('check')}Finish patrol</button></div>`)}
function visitorsDrawer(){const u=me();const p=propsFor(u)[0]||S.props[0];ui.drawer={k:'visitors'};const inside=S.visitors.filter(v=>v.propId===p.id&&!v.outAt);const todayL=S.visitors.filter(v=>v.propId===p.id&&iso(v.inAt)===iso(TODAY));
  const jobs=S.tickets.filter(t=>t.propId===p.id&&['assigned','in_progress'].includes(t.status));
  drawer(dHead('Visitors & contractors',esc(p.code+' · '+p.name))+`<div class="d-body"><form class="card inset" data-form="visitorIn"><b style="font-weight:500">Check someone in</b><div class="fgrid">
   <label class="f">Name<input name="name" required></label><label class="f">Company<input name="company" placeholder="Optional"></label>
   <label class="f">Purpose<select name="purpose">${['Visitor','Contractor','Delivery','Technician'].map(x=>`<option>${x}</option>`).join('')}</select></label>
   <label class="f">Apartment / unit<select name="unitNo"><option value="">Common area</option>${S.units.filter(x=>x.propId===p.id).map(x=>`<option>${esc(x.no)}</option>`).join('')}</select></label>
   <label class="f">ID (last 4 digits)<input name="idNo" inputmode="numeric" maxlength="4"></label>
   <label class="f">For job<select name="ticketId"><option value="">None</option>${jobs.map(t=>`<option value="${t.id}">${t.id} · ${esc(t.title)}</option>`).join('')}</select></label></div>
   <div class="row"><button class="btn dark" type="submit">${ic('plus')}Check in</button></div></form>
   <section class="stack"><h3>Inside now (${inside.length})</h3>${inside.length?`<div class="list">${inside.map(v=>`<div class="li"><span class="ibox">${ic('badge')}</span><div class="grow"><div class="ttl">${esc(v.name)}</div><div class="tiny muted">${esc(v.purpose)}${v.company?' · '+esc(v.company):''} · unit ${esc(v.unitNo||'—')} · in ${hm(v.inAt)}</div></div><button class="btn sm" data-act="visitorOut" data-id="${v.id}">Check out</button></div>`).join('')}</div>`:'<p class="muted small">Nobody is checked in.</p>'}</section>
   <section class="stack"><h3>Today</h3>${table([{h:'Name'},{h:'Purpose'},{h:'Unit'},{h:'In'},{h:'Out'}],todayL.map(v=>({cells:[esc(v.name),esc(v.purpose),esc(v.unitNo||'—'),hm(v.inAt),v.outAt?hm(v.outAt):st('Inside','gold')]})),{empty:'No visitors yet today.'})}</section></div>`)}
function arrivalsDrawer(){const u=me();const p=propsFor(u)[0]||S.props[0];ui.drawer={k:'arrivals'};const jobs=S.tickets.filter(t=>t.propId===p.id&&['assigned','in_progress'].includes(t.status));
  drawer(dHead('Technician arrival',esc(p.code+' · '+p.name))+`<div class="d-body"><p class="small muted">When a technician arrives for a job, confirm it here. The supervisor and manager see the arrival time on the ticket.</p>
   <div class="list">${jobs.map(t=>`<div class="li"><span class="ibox">${ic(CAT_ICON[t.category]||'wrench')}</span><div class="grow"><div class="ttl">${esc(t.title)}</div><div class="tiny muted">${t.id} · ${esc(nameOf(t.techId))} · ${esc(t.location)}${t.arrivals.length?' · arrived '+hm(t.arrivals[t.arrivals.length-1].at):''}</div></div>${t.arrivals.length?st('Arrived','ok'):`<button class="btn sm gold" data-act="tkArrive" data-id="${t.id}">Arrived</button>`}</div>`).join('')||empty('No technician is expected at this building.')}</div></div>`)}
function sosDialog(){dialog(`${dHead('Emergency','Alerts everyone immediately')}<form data-form="sos" class="d-body" style="gap:14px"><div class="cats">${['Fire or smoke','Water flood or leak','Power failure','Lift entrapment','Security incident','Gas smell'].map((x,i)=>`<label class="cat" style="position:relative"><input type="radio" name="kind" value="${x}" ${i===0?'checked':''} style="position:absolute;opacity:0">${ic(['fire','water','bolt','lift','shield','sos'][i])}<span>${x}</span></label>`).join('')}</div>
   <label class="f">What is happening?<input name="note" placeholder="Where, and is anyone hurt?"></label><label class="f">Photo (optional)<input name="photo" type="file" accept="image/*" capture="environment"></label>
   <div class="note small">If people are in danger, call <b class="mono">112</b> first.</div><div class="row"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn danger" type="submit" style="background:var(--bad);color:#fff;border-color:var(--bad)">${ic('sos')}Send emergency alert</button></div></form>`);
  setTimeout(()=>$$('.layer .cat input').forEach(r=>{const upd=()=>$$('.layer .cat').forEach(c=>c.classList.toggle('on',c.querySelector('input').checked));r.addEventListener('change',upd);upd()}),0)}

/* ================= warehouse ================= */
const stockPill=i=>i.qty<=0?st('Out of stock','bad'):i.qty<=i.min?st('Reorder','warn'):st('In stock','ok');
function viewWarehouse(u){const f=ui.f;const tab=f.wtab||'stock';const val=sum(S.items,i=>i.qty*i.cost);const low=S.items.filter(i=>i.qty<=i.min);const mo=S.moves.filter(m=>m.at.slice(0,7)===ym(TODAY));
  let body='';
  if(tab==='stock'){let l=S.items;if(f.wcat)l=l.filter(i=>i.cat===f.wcat);if(f.wstore)l=l.filter(i=>i.store===f.wstore);if(f.wlow)l=l.filter(i=>i.qty<=i.min);if(f.wq)l=l.filter(i=>(i.name+' '+i.sku+' '+i.supplier).toLowerCase().includes(f.wq.toLowerCase()));
    body=`<div class="chips">${['',...ITEM_CATS].map(c=>`<button class="chip ${(f.wcat||'')===c?'on':''}" data-act="setF" data-k="wcat" data-val="${c}">${c||'All'} <span class="n">${c?S.items.filter(i=>i.cat===c).length:S.items.length}</span></button>`).join('')}</div>
    <div class="filters"><label class="search">${ic('search')}<input id="wq" data-input="f" data-k="wq" placeholder="Item, SKU or supplier" value="${esc(f.wq||'')}"></label><select id="wstore" data-change="setF" data-k="wstore"><option value="">All stores</option>${STORES.map(s=>`<option ${f.wstore===s?'selected':''}>${s}</option>`).join('')}</select><label class="check"><input type="checkbox" id="wlow" data-change="setFc" data-k="wlow" ${f.wlow?'checked':''}>Reorder only</label></div>
    ${table([{h:'SKU'},{h:'Item'},{h:'Store · bin'},{h:'On hand'},{h:'Reorder at',r:1},{h:'Unit cost',r:1},{h:'Value',r:1},{h:'Status'}],l.map(i=>({act:'openItem',id:i.id,sel:false,cells:[`<span class="mono small">${esc(i.sku)}</span>`,`<div class="ttl">${esc(i.name)}</div><span class="tiny muted">${esc(i.cat)}</span>`,`<span class="small">${esc(i.store)}</span><div class="tiny muted mono">${esc(i.bin)}</div>`,`<div class="stack tight" style="min-width:110px"><b class="num">${i.qty} ${esc(i.unit)}</b><div class="meter"><i class="${i.qty<=i.min?'bad':'gold'}" style="width:${Math.min(100,i.qty/Math.max(1,i.min*3)*100)}%"></i></div></div>`,`<span class="num">${i.min}</span>`,`<span class="num">${money(i.cost)}</span>`,`<span class="num">${money(i.qty*i.cost)}</span>`,stockPill(i)]})),{empty:'No items match.',emptyIcon:'box'})}`}
  if(tab==='moves')body=table([{h:'When'},{h:'Item'},{h:'Movement'},{h:'Qty',r:1},{h:'By'},{h:'Reference'},{h:'Building'}],S.moves.slice(0,200).map(m=>{const i=itemById(m.itemId);const p=m.propId&&propById(m.propId);return {cells:[`<span class="small">${fmtDT(m.at)}</span>`,esc(i?i.name:'—'),st(m.type==='in'?'Received':m.type==='out'?'Issued':'Adjusted',m.type==='in'?'ok':m.type==='out'?'':'warn'),`<b class="num">${m.type==='out'?'−':m.qty>0?'+':''}${m.type==='out'?m.qty:m.qty}</b>`,esc(nameOf(m.by)),`<span class="mono small">${esc(m.ref||'')}</span>`,p?esc(p.code):'—']}}));
  if(tab==='receive')body=can(u,'stockEdit')?`<form class="card" data-form="stockIn" style="max-width:720px"><h3>Receive goods into stock</h3><div class="fgrid"><label class="f">Item<select name="itemId" required>${S.items.map(i=>`<option value="${i.id}">${esc(i.name)} · ${esc(i.store)}</option>`).join('')}</select></label><label class="f">Quantity received<input name="qty" type="number" min="1" step="any" required></label><label class="f">Unit cost (KWD)<input name="cost" type="number" min="0" step="any" placeholder="Leave blank to keep"></label><label class="f">PO / delivery note<input name="ref" placeholder="PO-512"></label></div><div class="row"><button class="btn dark" type="submit">${ic('download')}Receive</button></div></form>
    <form class="card" data-form="addItem" style="max-width:720px"><h3>Add a new stock item</h3><div class="fgrid"><label class="f">Name<input name="name" required></label><label class="f">Category<select name="cat">${ITEM_CATS.map(c=>`<option>${c}</option>`).join('')}</select></label><label class="f">Unit<input name="unit" value="pcs"></label><label class="f">Store<select name="store">${STORES.map(s=>`<option>${s}</option>`).join('')}</select></label><label class="f">Bin<input name="bin" placeholder="A-01"></label><label class="f">Opening quantity<input name="qty" type="number" min="0" value="0"></label><label class="f">Reorder level<input name="min" type="number" min="0" value="5"></label><label class="f">Unit cost (KWD)<input name="cost" type="number" min="0" step="any" value="0"></label><label class="f">Supplier<input name="supplier"></label></div><div class="row"><button class="btn dark" type="submit">${ic('plus')}Add item</button></div></form>`:'<p class="muted">Only procurement and stores staff can receive goods.</p>';
  if(tab==='issue')body=can(u,'stockIssue')?`<form class="card" data-form="stockOut" style="max-width:720px"><h3>Issue stock to a job</h3><div class="fgrid"><label class="f">Item<select name="itemId" required>${S.items.filter(i=>i.qty>0).map(i=>`<option value="${i.id}">${esc(i.name)} · ${i.qty} ${esc(i.unit)} left</option>`).join('')}</select></label><label class="f">Quantity<input name="qty" type="number" min="1" step="any" required></label><label class="f">Maintenance ticket<select name="ref"><option value="">No ticket</option>${S.tickets.filter(t=>['assigned','in_progress'].includes(t.status)).map(t=>`<option value="${t.id}">${t.id} · ${esc(t.title)}</option>`).join('')}</select></label><label class="f">Building<select name="propId"><option value="">—</option>${S.props.map(p=>`<option value="${p.id}">${p.code} · ${esc(p.name)}</option>`).join('')}</select></label></div><div class="row"><button class="btn dark" type="submit">${ic('upload')}Issue</button><span class="small muted">Technicians can also pick stock items when recording a job done.</span></div></form>`:'<p class="muted">You do not have permission to issue stock.</p>';
  return `<div class="figs"><div class="fig"><span class="big md">${S.items.length}</span><small>${ic('box')}Items in ${STORES.length} stores</small></div><div class="fig"><span class="big md">${moneyK(val)}</span><small>${ic('layers')}Stock value</small></div><div class="fig ${low.length?'alert':''}"><span class="big md">${low.length}</span><small>${ic('alarm')}At or below reorder level</small></div><div class="fig"><span class="big md">${mo.filter(m=>m.type==='out').length}</span><small>${ic('upload')}Issues this month</small></div></div>
   <div class="seg" data-tour="wtabs">${[['stock','Stock on hand'],['moves','Movements'],['receive','Receive goods'],['issue','Issue to job']].map(([k,l])=>`<button class="${tab===k?'on':''}" data-act="setF" data-k="wtab" data-val="${k}">${l}</button>`).join('')}</div>${body}`}
function itemDrawer(id){const u=me();const i=itemById(id);if(!i)return;ui.drawer={k:'item',id};const mv=S.moves.filter(m=>m.itemId===i.id).slice(0,30);
  drawer(dHead(esc(i.name),esc(i.sku)+' · '+esc(i.cat),`<div class="row">${stockPill(i)}</div>`)+`<div class="d-body"><div class="figs"><div class="fig"><span class="big md">${i.qty}</span><small>${esc(i.unit)} on hand</small></div><div class="fig"><span class="big md">${i.min}</span><small>Reorder level</small></div><div class="fig"><span class="big md">${money(i.qty*i.cost)}</span><small>Value</small></div></div>
   <dl class="kv"><div><dt>Store</dt><dd>${esc(i.store)}</dd></div><div><dt>Bin</dt><dd class="mono">${esc(i.bin)}</dd></div><div><dt>Unit cost</dt><dd>${money(i.cost)}</dd></div><div><dt>Supplier</dt><dd>${esc(i.supplier||'—')}</dd></div></dl>
   ${can(u,'stockEdit')?`<form class="card inset" data-form="stockAdj"><input type="hidden" name="itemId" value="${i.id}"><b style="font-weight:500">Stock count</b><div class="fgrid"><label class="f">Counted quantity<input name="qty" type="number" min="0" step="any" value="${i.qty}" required></label><label class="f">Reorder level<input name="min" type="number" min="0" value="${i.min}"></label><label class="f">Reason<input name="note" placeholder="Cycle count"></label></div><div class="row"><button class="btn dark" type="submit">Save count</button></div></form>`:''}
   <div class="stack"><h3>Movements</h3>${table([{h:'When'},{h:'Movement'},{h:'Qty',r:1},{h:'By'},{h:'Reference'}],mv.map(m=>({cells:[`<span class="small">${fmtDT(m.at)}</span>`,st(m.type==='in'?'Received':m.type==='out'?'Issued':'Adjusted',m.type==='in'?'ok':m.type==='out'?'':'warn'),`<b class="num">${m.type==='out'?'−':m.qty>0?'+':''}${m.qty}</b>`,esc(nameOf(m.by)),`<span class="mono small">${esc(m.ref||'')}</span>`]})),{empty:'No movements yet.'})}</div></div>`)}
function issueStock(itemId,qty,ref,propId,silent){const i=itemById(itemId);if(!i)return;i.qty=Math.max(0,+(i.qty-qty).toFixed(3));S.moves.unshift({id:uid('mv'),itemId,type:'out',qty,at:nowISO(),by:S.session,ref:ref||'',note:'',propId:propId||null});
  if(i.qty<=i.min)notify(usersByRole('procurement'),'Low stock · '+i.name+' · '+i.qty+' '+i.unit+' left',{view:'warehouse'},'Low stock · '+i.name,i.name+' ('+i.sku+') is at '+i.qty+' '+i.unit+' in '+i.store+'. Reorder level is '+i.min+'.',{kind:'stock',whatsapp:false});
  if(!silent)logAct('Issued '+qty+' '+i.unit+' '+i.name+(ref?' to '+ref:''))}

/* ================= fleet ================= */
function vjElapsed(j){if(!j.startedAt)return 0;return (j.doneAt?new Date(j.doneAt):new Date())-new Date(j.startedAt)}
function vjPill(j){if(j.status==='open')return st('Not started','');const el=vjElapsed(j),ex=j.expectedH*HOUR;if(j.status==='done')return el>ex?st('+'+dur(el-ex)+' over','warn'):st('On time','ok');return el>ex?st('Over by '+dur(el-ex),'bad'):st(dur(ex-el)+' left','')}
function vehicleTimerCard(j){const v=vehById(j.vehicleId);const el=vjElapsed(j),ex=j.expectedH*HOUR;const over=el>ex;
  return `<section class="card" data-act="openVJob" data-id="${j.id}" style="cursor:pointer"><div class="card-h"><h3 class="clip">${esc(v.plate)} · ${esc(j.issue)}</h3><button class="circ" aria-label="Open">${ic('arrow')}</button></div>${dial(j.status==='open'?0:Math.min(1,el/ex),j.status==='open'?'00:00':hhmm(el),j.status==='open'?'Not started · expected '+j.expectedH+' h':over?'Over by '+dur(el-ex):'of '+j.expectedH+' h expected',over?'late':j.status==='open'?'':'ontrack')}
   <div class="spread small"><span class="muted">${esc(j.garage)}</span><span>${esc(nameOf(j.workerId))}</span></div></section>`}
function viewFleet(u){const f=ui.f;const tab=f.ftab||(u.role==='tech'?'jobs':'vehicles');const active=S.vjobs.filter(j=>j.status!=='done');const over=active.filter(j=>j.status==='in_progress'&&vjElapsed(j)>j.expectedH*HOUR);
  const done=S.vjobs.filter(j=>j.status==='done');const overrun=done.filter(j=>vjElapsed(j)>j.expectedH*HOUR);const docs=S.vehicles.filter(v=>daysUntil(v.regExp)<=30||daysUntil(v.insExp)<=30);
  let body='';
  if(tab==='vehicles')body=table([{h:'Plate'},{h:'Vehicle'},{h:'Driver'},{h:'Odometer',r:1},{h:'Next service'},{h:'Registration'},{h:'Insurance'},{h:'Status'}],S.vehicles.map(v=>({act:'openVehicle',id:v.id,cells:[`<span class="mono">${esc(v.plate)}</span>`,`<div class="ttl">${esc(v.make+' '+v.model)}</div><span class="tiny muted">${esc(v.type)} · ${v.year}</span>`,avName(v.driverId,false),`<span class="num">${v.odo.toLocaleString()} km</span>`,`${expPill(v.nextService,7)}<div class="tiny muted">or ${v.nextServiceKm.toLocaleString()} km</div>`,expPill(v.regExp,30),expPill(v.insExp,30),st(v.status,v.status==='Active'?'ok':v.status==='In repair'?'warn':'bad')]})));
  if(tab==='jobs'){const mine=u.role==='tech'?active.filter(j=>j.workerId===u.id):active;
    body=`${mine.length?`<div class="grid g4">${mine.map(vehicleTimerCard).join('')}</div>`:empty('No open repair jobs.','truck')}<h3>Completed repairs</h3>
     ${table([{h:'Job'},{h:'Vehicle'},{h:'Type'},{h:'Issue'},{h:'Garage'},{h:'Expected',r:1},{h:'Actual',r:1},{h:'Result'},{h:'Cost',r:1}],done.slice(0,60).map(j=>{const v=vehById(j.vehicleId);return {act:'openVJob',id:j.id,cells:[`<span class="mono small">${j.id}</span>`,`<span class="mono">${esc(v.plate)}</span>`,esc(j.kind),esc(j.issue),`<span class="small">${esc(j.garage)}</span>`,j.expectedH+' h',dur(vjElapsed(j)),vjPill(j),money(j.cost)]}}))}`}
  if(tab==='times'){const kinds=['Service','Repair','Tyres','Accident'];const avgBy=(arr,key)=>[...new Set(arr.map(key))].map(k=>{const l=arr.filter(x=>key(x)===k);return {k,n:l.length,exp:sum(l,j=>j.expectedH)/l.length,act:sum(l,j=>vjElapsed(j)/HOUR)/l.length,over:l.filter(j=>vjElapsed(j)>j.expectedH*HOUR).length}});
    const bk=avgBy(done,j=>j.kind),bg=avgBy(done,j=>j.garage);
    body=`<div class="grid g2"><section class="card"><div class="card-h"><h3>Average repair time by type</h3><span class="small muted">Hours · actual against expected</span></div>${table([{h:'Type'},{h:'Jobs',r:1},{h:'Expected',r:1},{h:'Actual',r:1},{h:'Over time',r:1}],bk.map(x=>({cells:[esc(x.k),x.n,x.exp.toFixed(1)+' h',`<b class="num" style="color:${x.act>x.exp?'var(--bad)':'var(--ok)'}">${x.act.toFixed(1)} h</b>`,x.over+' of '+x.n]})))}</section>
     <section class="card"><div class="card-h"><h3>Over-time rate by garage</h3></div>${hbars(bg.map(x=>({label:x.k,value:Math.round(x.over/x.n*100),tone:x.over/x.n>.3?'bad':'gold'})),v=>v+'%')}</section></div>`}
  return `<div class="figs"><div class="fig"><span class="big md">${S.vehicles.length}</span><small>${ic('truck')}Vehicles</small></div><div class="fig"><span class="big md">${active.length}</span><small>${ic('wrench')}In the workshop</small></div><div class="fig ${over.length?'alert':''}"><span class="big md">${over.length}</span><small>${ic('alarm')}Over expected time</small></div><div class="fig"><span class="big md">${done.length?Math.round(overrun.length/done.length*100):0}%</span><small>${ic('clock')}Repairs that ran over</small></div><div class="fig ${docs.length?'alert':''}"><span class="big md">${docs.length}</span><small>${ic('doc')}Documents expiring ≤ 30 days</small></div></div>
   <div class="spread"><div class="seg">${[['vehicles','Vehicles'],['jobs','Repair jobs'],['times','Repair times']].map(([k,l])=>`<button class="${tab===k?'on':''}" data-act="setF" data-k="ftab" data-val="${k}">${l}</button>`).join('')}</div>${can(u,'fleetEdit')?`<div class="row"><button class="btn" data-act="addVehicle">${ic('plus')}Add vehicle</button><button class="btn dark" data-act="newVJob" data-tour="new-vjob">${ic('wrench')}Open repair job</button></div>`:''}</div>${body}`}
function vehicleDrawer(id){const u=me();const v=vehById(id);ui.drawer={k:'veh',id};const jobs=S.vjobs.filter(j=>j.vehicleId===v.id);const edit=can(u,'fleetEdit');const drivers=S.users.filter(x=>['tech','supervisor','manager'].includes(x.role));
  drawer(dHead(esc(v.plate)+' · '+esc(v.make+' '+v.model),esc(v.type)+' · '+v.year,`<div class="row">${st(v.status,v.status==='Active'?'ok':'warn')}</div>`)+`<form data-form="saveVehicle" style="display:contents"><input type="hidden" name="id" value="${v.id}"><div class="d-body"><fieldset ${edit?'':'disabled'} style="border:0;padding:0;margin:0"><div class="fgrid">
   <label class="f">Plate<input name="plate" value="${esc(v.plate)}"></label><label class="f">Make<input name="make" value="${esc(v.make)}"></label><label class="f">Model<input name="model" value="${esc(v.model)}"></label><label class="f">Type<select name="type">${VTYPES.map(t=>`<option ${v.type===t?'selected':''}>${t}</option>`).join('')}</select></label>
   <label class="f">Driver<select name="driverId">${drivers.map(x=>`<option value="${x.id}" ${x.id===v.driverId?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><label class="f">Odometer (km)<input name="odo" type="number" value="${v.odo}"></label><label class="f">Next service date<input name="nextService" type="date" value="${v.nextService}"></label><label class="f">Next service at (km)<input name="nextServiceKm" type="number" value="${v.nextServiceKm}"></label>
   <label class="f">Registration (Daftar) expiry<input name="regExp" type="date" value="${v.regExp}"></label><label class="f">Insurance expiry<input name="insExp" type="date" value="${v.insExp}"></label><label class="f">Status<select name="status">${['Active','In repair','Out of service'].map(s=>`<option ${v.status===s?'selected':''}>${s}</option>`).join('')}</select></label></div></fieldset>
   <div class="stack"><div class="spread"><h3>Repair & service history</h3>${edit?`<button type="button" class="btn sm dark" data-act="newVJob" data-v="${v.id}">${ic('wrench')}Open repair job</button>`:''}</div>${table([{h:'Job'},{h:'Opened'},{h:'Issue'},{h:'Expected',r:1},{h:'Actual',r:1},{h:'Result'},{h:'Cost',r:1}],jobs.map(j=>({act:'openVJob',id:j.id,cells:[`<span class="mono small">${j.id}</span>`,`<span class="small">${fmtDate(j.openedAt)}</span>`,esc(j.kind+' · '+j.issue),j.expectedH+' h',j.startedAt?dur(vjElapsed(j)):'—',vjPill(j),money(j.cost)]})),{empty:'No repairs yet.'})}</div></div>
   <div class="d-foot"><button type="button" class="btn" data-act="close">Close</button>${edit?'<button class="btn dark" type="submit">Save vehicle</button>':''}</div></form>`)}
function vjobDrawer(id){const u=me();const j=S.vjobs.find(x=>x.id===id);if(!j)return;ui.drawer={k:'vjob',id};const v=vehById(j.vehicleId);const mine=j.workerId===u.id||u.role==='admin'||can(u,'fleetEdit');const el=vjElapsed(j),ex=j.expectedH*HOUR;
  drawer(dHead(esc(j.issue),j.id+' · '+esc(v.plate)+' · '+esc(v.make+' '+v.model),`<div class="row">${vjPill(j)}${st(j.kind,'')}</div>`)+`<div class="d-body"><div class="grid g2" style="align-items:center">${dial(j.status==='open'?0:Math.min(1,el/ex),j.status==='open'?'00:00':hhmm(el),j.status==='done'?'Finished in '+dur(el):j.status==='open'?'Expected '+j.expectedH+' h':el>ex?'Over by '+dur(el-ex):dur(ex-el)+' left of '+j.expectedH+' h',el>ex&&j.status!=='open'?'late':'ontrack')}
   <dl class="kv" style="grid-template-columns:1fr 1fr"><div><dt>Worker</dt><dd>${esc(nameOf(j.workerId))}</dd></div><div><dt>Garage</dt><dd>${esc(j.garage)}</dd></div><div><dt>Opened</dt><dd>${fmtDT(j.openedAt)}</dd></div><div><dt>Started</dt><dd>${fmtDT(j.startedAt)}</dd></div><div><dt>Finished</dt><dd>${fmtDT(j.doneAt)}</dd></div><div><dt>Alerts sent</dt><dd>${j.alerts||(alertFor(j.id)||{count:0}).count}</dd></div></dl></div>
   ${j.status!=='done'&&mine?`<div class="callout"><b style="font-weight:500">${j.status==='open'?'Start the repair when work begins':'If the repair runs past '+j.expectedH+' hours, you and the operations manager get an alert every '+setting('vehicleRepeatH')+' hours until it is finished.'}</b>
     ${j.status==='open'?`<div class="row"><button class="btn dark" data-act="vjStart" data-id="${j.id}">${ic('play')}Start repair</button></div>`:`<form data-form="vjDone" class="stack"><input type="hidden" name="id" value="${j.id}"><div class="fgrid"><label class="f">Cost (KWD)<input name="cost" type="number" min="0" step="any" required></label><label class="f">Odometer (km)<input name="odo" type="number" value="${v.odo}"></label><label class="f">Expected hours (adjust if agreed)<input name="expectedH" type="number" min="0.5" step="0.5" value="${j.expectedH}"></label></div><label class="f">Work done<input name="notes" placeholder="Parts replaced, findings"></label><div class="row"><button class="btn dark" type="submit">${ic('check')}Mark repair finished</button></div></form>`}</div>`:''}
   ${j.notes?`<p>${esc(j.notes)}</p>`:''}</div>`)}
function newVJobDialog(vid){const workers=S.users.filter(x=>x.role==='tech');dialog(`${dHead('Open repair job','Fleet')}<form data-form="newVJob" class="d-body" style="gap:14px"><div class="fgrid">
  <label class="f">Vehicle<select name="vehicleId">${S.vehicles.map(v=>`<option value="${v.id}" ${v.id===vid?'selected':''}>${esc(v.plate)} · ${esc(v.make+' '+v.model)}</option>`).join('')}</select></label><label class="f">Type<select name="kind">${['Service','Repair','Tyres','Accident'].map(k=>`<option>${k}</option>`).join('')}</select></label>
  <label class="f">Worker<select name="workerId">${workers.map(w=>`<option value="${w.id}" ${(w.skills||[]).includes('Fleet')?'selected':''}>${esc(w.name)}</option>`).join('')}</select></label><label class="f">Garage<select name="garage">${GARAGES.map(g=>`<option>${g}</option>`).join('')}</select></label>
  <label class="f">Expected time (hours)<input name="expectedH" type="number" min="0.5" step="0.5" value="4" required></label></div><label class="f">Issue<input name="issue" required placeholder="e.g. AC compressor not cooling"></label>
  <div class="row"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn dark" type="submit">Open job</button></div></form>`)}

/* ================= rent ================= */
function viewRent(u){const ids=propIds(u);const f=ui.f;const months=[...new Set(S.rent.map(r=>r.month))].sort().reverse();
  let rows=S.rent.filter(r=>{if(r.month!==ui.rentMonth)return false;const x=unitById(r.unitId);return x&&ids.has(x.propId)});const all=rows;
  if(f.rstat)rows=rows.filter(r=>f.rstat==='paid'?r.paidOn:f.rstat==='overdue'?(!r.paidOn&&daysUntil(r.due)<-5):!r.paidOn);
  if(f.rq)rows=rows.filter(r=>{const x=unitById(r.unitId);const t=tenantById(x.tenantId);return (x.code+' '+(t?t.name:'')).toLowerCase().includes(f.rq.toLowerCase())});
  const exp=sum(all,r=>toKWD(r.amount,r.cur)),col=sum(all.filter(r=>r.paidOn),r=>toKWD(r.amount,r.cur));const mp=can(u,'markPaid');
  const trend=months.slice(0,6).reverse().map(m=>{const l=S.rent.filter(r=>r.month===m&&(()=>{const x=unitById(r.unitId);return x&&ids.has(x.propId)})());const e=sum(l,r=>toKWD(r.amount,r.cur));return e?Math.round(sum(l.filter(r=>r.paidOn),r=>toKWD(r.amount,r.cur))/e*100):0});
  return `<div class="grid" style="grid-template-columns:minmax(0,1.6fr) minmax(0,1fr)"><div class="stack"><div class="figs"><div class="fig"><span class="big md">${moneyK(exp)}</span><small>Expected · ${all.length} invoices</small></div><div class="fig"><span class="big md">${moneyK(col)}</span><small>Collected</small></div><div class="fig ${exp-col>0?'alert':''}"><span class="big md">${moneyK(exp-col)}</span><small>Outstanding</small></div><div class="fig"><span class="big md">${exp?Math.round(col/exp*100):0}%</span><small>Collection rate</small></div></div>
     <p class="small muted">Rent is collected outside the platform (K-Net, bank transfer, cheque). Record each payment here, or import the bank statement as CSV. All amounts are in Kuwaiti dinar (KWD).</p></div>
    <section class="card"><div class="card-h"><h3>Collection rate · 6 months</h3></div>${lolli(months.slice(0,6).reverse().map(monthShort),trend,5,v=>v+'%')}</section></div>
   <div class="spread"><div class="filters"><select id="rmonth" data-change="rentMonth">${months.map(m=>`<option value="${m}" ${m===ui.rentMonth?'selected':''}>${monthLabel(m)}</option>`).join('')}</select>
    <select id="rstat" data-change="setF" data-k="rstat"><option value="">Any status</option><option value="unpaid" ${f.rstat==='unpaid'?'selected':''}>Unpaid</option><option value="overdue" ${f.rstat==='overdue'?'selected':''}>Overdue</option><option value="paid" ${f.rstat==='paid'?'selected':''}>Paid</option></select>
    <label class="search">${ic('search')}<input id="rq" data-input="f" data-k="rq" placeholder="Unit or tenant" value="${esc(f.rq||'')}"></label></div>
    <div class="row">${mp?`<button class="btn" data-act="csvOpen">${ic('upload')}Import CSV</button>`:''}<button class="btn" data-act="rentExport">${ic('download')}Export CSV</button></div></div>
   ${table([{h:'Unit'},{h:'Tenant'},{h:'Building'},{h:'Amount',r:1},{h:'Status'},{h:'Paid on'},{h:'Method · ref'},{h:'Receipt'},{h:''}],rows.slice(0,300).map(r=>{const x=unitById(r.unitId);const t=tenantById(x.tenantId);const p=propById(x.propId);
     return {cells:[`<span class="mono small">${esc(x.code)}</span>`,esc(t?t.name:'—'),`<span class="small">${esc(p.name)}</span>`,`<span class="num">${money(r.amount,r.cur)}</span>`,rentPill(r),r.paidOn?`<span class="small">${fmtDate(r.paidOn)}</span>`:'—',r.method?`<span class="small">${esc(r.method)} · <span class="mono">${esc(r.ref||'')}</span></span>`:'—',`<span class="mono small">${r.receipt||'—'}</span>`,mp?(r.paidOn?`<button class="btn sm ghost" data-act="unpay" data-id="${r.id}">Undo</button>`:`<button class="btn sm dark" data-act="markPaid" data-id="${r.id}">Mark paid</button>`):'']}}),{empty:'No rent records match.'})}`}
function csvDialog(){dialog(`${dHead('Import rent payments','CSV')}<div class="d-body"><p class="small">Columns: <span class="mono">unit_code, month (YYYY-MM), amount, paid_on (YYYY-MM-DD), method, reference</span></p>
  <div class="row"><label class="btn" for="csv-file">${ic('upload')}Choose file<input id="csv-file" type="file" accept=".csv,text/csv" hidden data-change="csvFile"></label><button class="btn" data-act="csvSample">Load sample rows</button></div>
  <label class="f">Or paste CSV<textarea id="csv-text" rows="6"></textarea></label><div class="row"><button class="btn" data-act="csvPreview">Preview</button></div><div id="csv-prev"></div></div>
  <div class="d-foot"><button class="btn" data-act="close">Cancel</button><button class="btn dark" data-act="csvApply" id="csv-apply" disabled>Apply payments</button></div>`)}

/* ================= alerts & messages ================= */
const chanIcon=c=>c==='whatsapp'?'wa':'mail';
function obStatus(e){const s=(outboxStatus[e.id]||{}).status||(online?'queued':'demo');if((s==='queued'||s==='waiting_keys'||s==='archived')&&Date.now()-new Date(e.at).getTime()>DAY)return 'expired';return s}
const obPill=s=>st(s==='sent'?'Sent':s==='failed'?'Failed':s==='waiting_keys'?'Waiting for sending keys':s==='demo'?'Demo · not sent':s==='expired'?'Not sent · older than 24 h':'Queued',s==='sent'?'ok':s==='failed'?'bad':s==='waiting_keys'?'warn':'');
function viewAlerts(u){const tab=ui.f.atab||'mine';const mine=S.notifs.filter(n=>n.userId===u.id);let body='';
  if(tab==='mine')body=`<div class="spread"><span class="small muted">${mine.filter(n=>!n.read).length} unread</span><button class="btn sm" data-act="readAll">Mark all read</button></div><div class="card"><div class="list">${mine.slice(0,80).map(n=>`<div class="li click" data-act="openNotif" data-id="${n.id}"><span class="ibox ${n.kind==='late'||n.kind==='emergency'?'bad':n.kind==='approval'?'gold':''}">${ic(n.kind==='late'?'alarm':n.kind==='emergency'?'sos':n.kind==='approval'?'check':n.kind==='stock'?'box':'bell')}</span><div class="grow"><div class="${n.read?'':'ttl'}">${esc(n.text)}</div><div class="tiny muted">${ago(n.at)}</div></div>${n.read?'':st('New','gold')}</div>`).join('')||empty('No notifications yet.','bell')}</div></div>`;
  if(tab==='outbox'){const box=S.outbox.filter(e=>u.role==='admin'||e.userId===u.id).slice(0,150);
    body=`<div class="note small">Every alert is delivered in the platform and, where the person has them switched on, by email and WhatsApp. ${online?'The server sends queued messages every few minutes.':'Demo mode: nothing leaves this browser.'}</div>
    ${table([{h:'Channel'},{h:'To'},{h:'Subject'},{h:'Queued'},{h:'Status'}],box.map(e=>({act:'viewMail',id:e.id,cells:[`<span class="row nowrap" style="gap:6px">${ic(chanIcon(e.channel))}${e.channel==='whatsapp'?'WhatsApp':'Email'}</span>`,`<b style="font-weight:500">${esc(e.toName)}</b><div class="tiny muted mono">${esc(e.to)}</div>`,`<span class="clip" style="display:block;max-width:420px">${esc(e.subject)}</span>`,`<span class="small">${ago(e.at)}</span>`,obPill(obStatus(e))]})),{empty:'Outbox is empty.'})}`}
  if(tab==='rem'){const list=computeReminders().filter(r=>!r.propId||propIds(u).has(r.propId));
    body=`<div class="spread"><span class="small muted">Daily digest ${S.lastReminderRun?'last sent '+fmtDate(S.lastReminderRun):'not sent yet'} · one email per person, not one per item</span>${can(u,'sendReminders')?`<button class="btn dark" data-act="sendRem">${ic('bell')}Send digest now</button>`:''}</div>
    ${table([{h:'Type'},{h:'Subject'},{h:'When'},{h:'Goes to'}],list.slice(0,200).map(r=>({cells:[st(r.type,r.tone),`<div class="ttl">${esc(r.subject)}</div><span class="tiny muted">${esc(r.detail)}</span>`,`<span class="small">${r.days<0?(-r.days)+' d overdue':r.days===0?'Today':'In '+r.days+' d'}</span>`,`<span class="small">${[...new Set(r.to.filter(Boolean))].slice(0,4).map(nameOf).join(', ')}${r.to.length>4?'…':''}</span>`]})),{empty:'Nothing due.'})}`}
  return `<div class="tabs">${[['mine','My notifications'],['outbox','Email & WhatsApp'],['rem','Reminders']].map(([k,l])=>`<button class="${tab===k?'on':''}" data-act="setF" data-k="atab" data-val="${k}">${l}</button>`).join('')}</div>${body}`}
function bellDrawer(){const u=me();const list=S.notifs.filter(n=>n.userId===u.id).slice(0,40);ui.drawer=null;
  drawer(dHead('Notifications',list.filter(n=>!n.read).length+' unread')+`<div class="d-body"><div class="list">${list.map(n=>`<div class="li click" data-act="openNotif" data-id="${n.id}"><span class="ibox ${n.kind==='late'||n.kind==='emergency'?'bad':n.kind==='approval'?'gold':''}">${ic(n.kind==='late'?'alarm':n.kind==='emergency'?'sos':'bell')}</span><div class="grow"><div class="${n.read?'':'ttl'}">${esc(n.text)}</div><div class="tiny muted">${ago(n.at)}</div></div></div>`).join('')||empty('No notifications yet.','bell')}</div></div><div class="d-foot"><button class="btn" data-act="readAll">Mark all read</button>${can(u,'alerts')?'<button class="btn dark" data-act="nav" data-v="alerts">Open alerts</button>':''}</div>`)}

/* ================= reports ================= */
function viewReports(u){const per=ui.reportPeriod;const since=per?Date.now()-per*DAY:0;const inP=s=>s&&new Date(s).getTime()>=since;const ids=propIds(u);const tks=S.tickets.filter(t=>ids.has(t.propId));
  const created=tks.filter(t=>inP(t.createdAt));const closed=tks.filter(t=>t.status==='closed'&&inP(closedAt(t)));const onT=closed.filter(t=>new Date(closedAt(t)).getTime()<=dueOf(t)).length;
  const jobs=tks.filter(t=>t.job&&inP(t.job.completedAt));const cost=sum(jobs,t=>toKWD(t.job.total,propById(t.propId).currency));
  const days=[...Array(14)].map((_,i)=>addD(TODAY,i-13));const ca=days.map(d=>tks.filter(t=>iso(t.createdAt)===iso(d)).length),cb=days.map(d=>tks.filter(t=>t.status==='closed'&&iso(closedAt(t))===iso(d)).length);
  // time spent in each approval stage (bottlenecks)
  const stageT={};tks.filter(t=>inP(t.createdAt)).forEach(t=>{for(let i=0;i<t.history.length;i++){const h=t.history[i];const nx=t.history[i+1];const end=nx?new Date(nx.at):(isOpen(t)?new Date():null);if(!end)continue;(stageT[h.status]=stageT[h.status]||[]).push(end-new Date(h.at))}});
  const stageAvg=['reported','mgr_approval','owner_approval','assigned','in_progress','job_done','procurement'].map(k=>({label:'Waiting · '+STAGE[k].short,value:stageT[k]&&stageT[k].length?sum(stageT[k])/stageT[k].length/HOUR:0,tone:k.includes('approval')||k==='reported'?'gold':''}));
  const byCat=CATS.map(c=>({label:c,value:Math.round(sum(jobs.filter(t=>t.category===c),t=>toKWD(t.job.total,propById(t.propId).currency)))})).filter(x=>x.value).sort((a,b)=>b.value-a.value);
  const techs=S.users.filter(x=>x.role==='tech'&&!(x.skills||[]).includes('Fleet')).map(x=>{const l=tks.filter(t=>t.techId===x.id);const c=l.filter(t=>t.status==='closed'&&inP(closedAt(t)));return {x,open:l.filter(isOpen).length,done:c.length,ontime:c.filter(t=>new Date(closedAt(t)).getTime()<=dueOf(t)).length,late:l.filter(isLate).length}});
  const byProp=S.props.filter(p=>ids.has(p.id)).map(p=>{const l=tks.filter(t=>t.propId===p.id);return {p,open:l.filter(isOpen).length,pend:l.filter(t=>['reported','mgr_approval','owner_approval'].includes(t.status)).length,done:l.filter(t=>t.status==='closed'&&inP(closedAt(t))).length,late:l.filter(isLate).length,cost:sum(l.filter(t=>t.job&&inP(t.job.completedAt)),t=>t.job.total)}}).sort((a,b)=>b.late-a.late||b.open-a.open);
  const today=tks.filter(t=>t.job&&iso(t.job.completedAt)===iso(TODAY));
  return `<div class="spread"><div class="seg">${[[1,'Today'],[7,'7 days'],[30,'30 days'],[90,'90 days'],[0,'All time']].map(([v,l])=>`<button class="${per===v?'on':''}" data-act="period" data-v="${v}">${l}</button>`).join('')}</div><button class="btn" data-act="exportReport">${ic('download')}Export CSV</button></div>
   <div class="figs"><div class="fig"><span class="big md">${created.length}</span><small>Jobs raised</small></div><div class="fig"><span class="big md">${closed.length}</span><small>Closed</small></div><div class="fig"><span class="big md">${tks.filter(isOpen).length}</span><small>Pending now</small></div><div class="fig"><span class="big md">${closed.length?Math.round(onT/closed.length*100):0}%</span><small>Closed within 24/48 h</small></div><div class="fig ${tks.filter(isLate).length?'alert':''}"><span class="big md">${tks.filter(isLate).length}</span><small>Late now</small></div><div class="fig"><span class="big md">${moneyK(cost)}</span><small>Maintenance cost</small></div></div>
   <div class="grid g2"><section class="card"><div class="card-h"><h3>Raised vs closed · 14 days</h3><div class="legend"><span><i style="background:var(--night)"></i>Raised</span><span><i style="background:var(--gold)"></i>Closed</span></div></div>
     <div class="lolli" style="height:190px">${days.map((d,i)=>{const mx=Math.max(1,...ca,...cb);return `<div class="c" style="flex-direction:column"><div class="row nowrap" style="gap:3px;align-items:flex-end;height:140px"><span class="stem" style="height:${ca[i]/mx*130}px;width:6px" title="${ca[i]} raised"></span><span class="stem hl" style="height:${cb[i]/mx*130}px;width:6px" title="${cb[i]} closed"></span></div><span class="lab">${d.getDate()}</span></div>`}).join('')}</div></section>
    <section class="card"><div class="card-h"><h3>Where jobs wait</h3><span class="small muted">Average hours in each stage</span></div>${hbars(stageAvg,v=>v.toFixed(1)+' h')}<p class="small muted">Gold bars are approval steps. Long gold bars mean approvals are eating into the 24/48-hour deadline.</p></section></div>
   <div class="grid g2"><section class="card"><div class="card-h"><h3>Cost by category</h3><span class="small muted">KWD</span></div>${byCat.length?hbars(byCat,v=>v.toLocaleString()):empty('No completed jobs in this period.')}</section>
    <section class="card"><div class="card-h"><h3>Technical team</h3></div>${table([{h:'Technician'},{h:'Open',r:1},{h:'Done',r:1},{h:'On time',r:1},{h:'Late now',r:1}],techs.map(t=>({cells:[avName(t.x.id),t.open,t.done,t.done?Math.round(t.ontime/t.done*100)+'%':'—',t.late?`<b style="color:var(--bad)">${t.late}</b>`:0]})))}</section></div>
   <section class="card"><div class="card-h"><h3>Jobs completed today</h3><span class="small muted">${today.length}</span></div>${ticketTable(today)}</section>
   <section class="stack"><h3>Pending vs done by building</h3>${table([{h:'Building'},{h:'Category'},{h:'Open',r:1},{h:'In approval',r:1},{h:'Done',r:1},{h:'Late',r:1},{h:'Cost',r:1}],byProp.map(r=>({act:'openProp',id:r.p.id,cells:[`<b style="font-weight:500">${r.p.code}</b> ${esc(r.p.name)}`,`<span class="small">${r.p.type}</span>`,r.open,r.pend,r.done,r.late?`<b style="color:var(--bad)">${r.late}</b>`:0,money(r.cost,r.p.currency)]})))}</section>
   <section class="card"><div class="card-h"><h3>Audit trail</h3><span class="small muted">Latest 30 actions</span></div><div class="list">${S.log.slice(0,30).map(l=>`<div class="li"><span class="small muted mono" style="min-width:120px">${fmtDT(l.at)}</span><div class="grow small"><b style="font-weight:500">${esc(nameOf(l.by))}</b> · ${esc(l.text)}</div></div>`).join('')}</div></section>`}

/* ================= users ================= */
function viewUsers(u){const f=ui.f.urole||'';const q=(ui.f.uq2||'').toLowerCase();const list=S.users.filter(x=>(!f||x.role===f)&&(!q||(x.name+' '+x.email+' '+x.title).toLowerCase().includes(q)));
  return `<div class="spread"><div class="chips">${['',...Object.keys(ROLES)].map(k=>`<button class="chip ${f===k?'on':''}" data-act="setF" data-k="urole" data-val="${k}">${k?ROLES[k].short:'All'} <span class="n">${k?S.users.filter(x=>x.role===k).length:S.users.length}</span></button>`).join('')}</div><button class="btn dark" data-act="editUser" data-id="">${ic('plus')}Add user</button></div>
   <div class="filters"><label class="search">${ic('search')}<input id="uq2" data-input="f" data-k="uq2" placeholder="Name, email or title" value="${esc(ui.f.uq2||'')}"></label></div>
   ${table([{h:'Name'},{h:'Role'},{h:'Email'},{h:'Mobile'},{h:'Buildings'},{h:'Alerts'},{h:'Status'}],list.map(x=>({act:'editUser',id:x.id,cells:[avName(x.id),st(ROLES[x.role].short,x.role==='admin'?'night':x.role==='owner'?'gold':''),`<span class="small">${esc(x.email)}</span>`,`<span class="mono small">${esc(x.phone)}</span>`,`<span class="small">${scopedRole(x)?(x.props||[]).map(id=>(propById(id)||{}).code).filter(Boolean).slice(0,4).join(', ')+((x.props||[]).length>4?' +'+((x.props||[]).length-4):'')||'—':'All'}</span>`,`<span class="row nowrap" style="gap:4px">${(x.prefs||{}).email!==false?`<span class="tag">${ic('mail')}</span>`:''}${(x.prefs||{}).whatsapp!==false?`<span class="tag">${ic('wa')}</span>`:''}</span>`,x.active!==false?st('Active','ok'):st('Disabled','bad')]})))}`}
function userDrawer(id){const x=id?userById(id):{name:'',role:'supervisor',title:'',email:'',phone:'',props:[],skills:[],perms:[...ROLES.supervisor.perms],active:true,prefs:{email:true,whatsapp:true}};ui.drawer=null;
  drawer(dHead(id?esc(x.name):'Add user','Account, permissions & alerts')+`<form data-form="saveUser" style="display:contents"><input type="hidden" name="id" value="${id||''}"><div class="d-body">
   <div class="fgrid"><label class="f">Full name<input name="name" required value="${esc(x.name)}"></label><label class="f">Job title<input name="title" value="${esc(x.title)}"></label><label class="f">Email (sign-in)<input name="email" type="email" required value="${esc(x.email)}"></label><label class="f">Mobile (WhatsApp)<input name="phone" value="${esc(x.phone)}" placeholder="+965 9xxx xxxx"></label>
   <label class="f">Role<select name="role" id="us-role" data-change="roleDefaults">${Object.entries(ROLES).map(([k,r])=>`<option value="${k}" ${x.role===k?'selected':''}>${r.l}</option>`).join('')}</select></label><label class="f">${id?'New password':'Password'}<span class="hint">${id?'Leave blank to keep':'Defaults to demo123'}</span><input name="password" type="text" autocomplete="new-password"></label></div>
   <div class="row"><label class="check"><input type="checkbox" name="active" ${x.active!==false?'checked':''}>Account active</label><label class="check"><input type="checkbox" name="pEmail" ${(x.prefs||{}).email!==false?'checked':''}>Email alerts</label><label class="check"><input type="checkbox" name="pWa" ${(x.prefs||{}).whatsapp!==false?'checked':''}>WhatsApp alerts</label></div>
   <div class="grid g2"><div class="card inset" style="gap:8px"><span class="eyebrow">Screens</span>${MODULES.map(([k,l])=>`<label class="check"><input type="checkbox" name="perm" value="${k}" ${(x.perms||[]).includes(k)?'checked':''}>${l}</label>`).join('')}</div>
    <div class="card inset" style="gap:8px"><span class="eyebrow">Actions</span>${ACTIONS.map(([k,l])=>`<label class="check"><input type="checkbox" name="perm" value="${k}" ${(x.perms||[]).includes(k)?'checked':''}>${l}</label>`).join('')}</div></div>
   <div class="stack tight"><span class="eyebrow">Trades (used to suggest technicians)</span><div class="chips">${[...CATS,'Fleet'].map(c=>`<label class="chip"><input type="checkbox" name="skill" value="${c}" ${(x.skills||[]).includes(c)?'checked':''}>${c}</label>`).join('')}</div></div>
   <div class="stack tight"><span class="eyebrow">Buildings (supervisors and guards only see these)</span><div class="card inset" style="max-height:240px;overflow:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:8px">${S.props.map(p=>`<label class="check small"><input type="checkbox" name="prop" value="${p.id}" ${(x.props||[]).includes(p.id)?'checked':''}><span class="mono">${p.code}</span> ${esc(p.name)}</label>`).join('')}</div></div></div>
   <div class="d-foot"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn dark" type="submit">Save user</button></div></form>`,true)}
function profileDrawer(){const u=me();ui.drawer=null;drawer(dHead('My profile & alerts',esc(ROLES[u.role].l))+`<form data-form="saveProfile" style="display:contents"><div class="d-body"><div class="fgrid"><label class="f">Name<input name="name" value="${esc(u.name)}" required></label><label class="f">Mobile (WhatsApp)<input name="phone" value="${esc(u.phone)}"></label><label class="f">Email<input value="${esc(u.email)}" disabled></label></div>
  <div class="card inset"><b style="font-weight:500">How should we reach you?</b><label class="check"><input type="checkbox" name="pEmail" ${(u.prefs||{}).email!==false?'checked':''}>Email alerts</label><label class="check"><input type="checkbox" name="pWa" ${(u.prefs||{}).whatsapp!==false?'checked':''}>WhatsApp alerts</label><span class="small muted">In-app notifications are always on. Late-job and emergency alerts use every channel you allow.</span></div>
  <div class="row"><button type="button" class="btn" data-act="tourStart">${ic('play')}Replay the tour</button></div></div><div class="d-foot"><button type="button" class="btn" data-act="close">Cancel</button><button class="btn dark" type="submit">Save</button></div></form>`)}

/* ================= settings ================= */
function checkHealth(){alertHealth().then(h=>{const el=$('#health');if(!el)return;if(!h){el.innerHTML=online?'Sending service not reachable yet. Messages stay queued.':'Demo mode: messages are not sent.';return}
  el.innerHTML=`<div class="row">${st('Email: '+(h.email?'connected':'add keys'),h.email?'ok':'warn')}${st('WhatsApp: '+(h.whatsapp?'connected':'add keys'),h.whatsapp?'ok':'warn')}</div>${h.queued!=null?`<span class="small muted">${h.queued} queued · ${h.waiting} waiting for keys · ${h.sent} sent in the last 24 h</span>`:''}`})}
function viewSettings(u){const s=S.settings;const roles=s.escalateRoles||[];setTimeout(checkHealth,50);
  return `<form class="grid g2" data-form="saveSettings" style="align-items:start">
   <section class="card"><div class="card-h"><h3>Fix deadlines</h3>${ic('clock')}</div><div class="fgrid"><label class="f">Emergency & urgent jobs (hours)<input name="slaUrgentH" type="number" min="1" max="168" value="${s.slaUrgentH}"></label><label class="f">Normal & planned jobs (hours)<input name="slaNormalH" type="number" min="1" max="336" value="${s.slaNormalH}"></label></div><p class="small muted">The clock starts when the issue is reported and includes approval time. New deadlines apply to jobs reported from now on.</p></section>
   <section class="card"><div class="card-h"><h3>Late-job alerts</h3>${ic('alarm')}</div><label class="f">Repeat the alert every (hours)<input name="repeatH" type="number" min="1" max="24" value="${s.repeatH}"></label>
     <div class="stack tight"><span class="small dim" style="font-weight:500">Who receives late-job alerts</span>${['supervisor','manager','owner','admin'].map(r=>`<label class="check"><input type="checkbox" name="escRole" value="${r}" ${roles.includes(r)?'checked':''}>${ROLES[r].l}${r==='supervisor'?' (of that building)':''}</label>`).join('')}</div>
     <label class="f">Vehicle repair over-time alerts repeat every (hours)<input name="vehicleRepeatH" type="number" min="1" max="24" value="${s.vehicleRepeatH}"></label></section>
   <section class="card"><div class="card-h"><h3>Approval chain</h3>${ic('check')}</div><div class="article" style="gap:8px"><div class="flow"><span>Guard report</span><em>→</em><span class="k">Supervisor</span><em>→</em><span class="k">Manager</span><em>→</em><span class="k">Owner</span><em>→</em><span>Technician</span><em>→</em><span>Review</span></div></div>
     <label class="f">Owner approval needed from (KWD)<span class="hint">0 = the owner approves every job. Above 0, cheaper jobs skip owner approval.</span><input name="ownerThreshold" type="number" min="0" step="any" value="${s.ownerThreshold}"></label></section>
   <section class="card"><div class="card-h"><h3>Alert channels</h3>${ic('bell')}</div><label class="check"><input type="checkbox" name="chEmail" ${s.channels.email!==false?'checked':''}>Email</label><label class="check"><input type="checkbox" name="chWa" ${s.channels.whatsapp!==false?'checked':''}>WhatsApp</label>
     <div id="health" class="note small">${online?'Checking sending accounts…':'Demo mode: messages are not sent.'}</div>
     <details><summary class="small" style="cursor:pointer">How to connect email and WhatsApp</summary><ol class="small" style="padding-left:18px;display:flex;flex-direction:column;gap:6px;margin-top:8px"><li>Email: create a Resend account, verify your sending domain, create an API key.</li><li>WhatsApp: in Twilio, enable a WhatsApp sender (your business number) and note the Account SID and Auth Token.</li><li>In Supabase → Edge Functions → Secrets, add <span class="mono">RESEND_API_KEY</span>, <span class="mono">ALERT_FROM_EMAIL</span>, <span class="mono">TWILIO_ACCOUNT_SID</span>, <span class="mono">TWILIO_AUTH_TOKEN</span>, <span class="mono">TWILIO_WHATSAPP_FROM</span>.</li><li>Queued messages from the last 24 hours go out automatically once the keys are in.</li></ol></details></section>
   <div class="row" style="grid-column:1/-1"><button class="btn dark" type="submit">Save settings</button>${u.role==='admin'&&!online?`<button type="button" class="btn danger" data-act="reset">${ic('reset')}Reset demo data</button>`:''}</div></form>`}

/* ================= TV wall ================= */
let tvTimer=null,clockTimer=null;
function renderTV(){const u=me();if(!u)return;const P=portfolio(u);const now=new Date();const tks=P.tks;
  const feed=[];tks.forEach(t=>t.history.forEach(h=>feed.push({at:h.at,t,h})));feed.sort((a,b)=>b.at.localeCompare(a.at));
  const doneToday=tks.filter(t=>t.job&&iso(t.job.completedAt)===iso(TODAY));const flow=STAGES.filter(s=>s.k!=='closed'&&s.k!=='rejected');
  $('#tv').innerHTML=`<div class="spread"><div class="row"><img src="${LOGO_WHITE}" alt="" style="height:44px"><span class="livedot">Live · updates every 15 s</span></div>
   <div class="row" style="gap:18px"><div style="text-align:right"><div class="big" id="tv-clock" style="font-size:40px">${now.toLocaleTimeString(LOC())}</div><div class="muted small">${now.toLocaleDateString(LOC(),{weekday:'long',day:'numeric',month:'long'})} · ${hijri(now)}</div></div><button class="btn sm" data-act="tvFull">${ic('full')}Full screen</button><button class="btn sm" data-act="tvClose">${ic('x')}Exit</button></div></div>
   <div class="figs"><div class="fig"><span class="big">${P.open.length}</span><small>Open jobs</small></div><div class="fig"><span class="big">${P.approvals.length}</span><small>In approval</small></div><div class="fig"><span class="big">${tks.filter(t=>['assigned','in_progress'].includes(t.status)).length}</span><small>With technicians</small></div><div class="fig alert"><span class="big">${P.late.length}</span><small>Late</small></div><div class="fig"><span class="big" style="color:#FAC951">${doneToday.length}</span><small>Fixed today</small></div><div class="fig"><span class="big">${P.closed.length?Math.round(P.onTime/P.closed.length*100):100}%</span><small>On time · 30 days</small></div></div>
   <div class="grid" style="grid-template-columns:minmax(0,1.5fr) minmax(0,1fr);flex:1">
    <div class="stack"><section class="card"><span class="eyebrow" style="color:#8E8C86">Pipeline</span><div class="figs">${flow.map(s=>`<div class="fig"><span class="big md">${tks.filter(t=>t.status===s.k).length}</span><small>${s.short}</small></div>`).join('')}</div></section>
     <section class="card"><span class="eyebrow" style="color:#8E8C86">Buildings · open jobs</span><div class="tv-heat">${S.props.filter(p=>P.ids.has(p.id)).map(p=>{const n=P.open.filter(t=>t.propId===p.id).length;const l=P.late.filter(t=>t.propId===p.id).length;return `<div class="${l?'h2':n>=2?'h1':''}"><b>${p.code} · ${n}</b><span>${esc(p.name)}</span></div>`}).join('')}</div><div class="row small muted"><span>Gold: 2+ open</span><span>Red: late job</span></div></section></div>
    <div class="stack"><section class="card" style="flex:1"><span class="eyebrow" style="color:#8E8C86">Live activity</span><div class="list">${feed.slice(0,10).map(f=>`<div class="li" style="border-color:#2A2A2C"><span class="mono small muted" style="min-width:48px">${hm(f.at)}</span><div class="grow small"><b style="font-weight:500">${esc(propById(f.t.propId).code)}</b> · ${esc(f.t.title)} <span class="muted">· ${esc(f.h.text)}</span></div></div>`).join('')}</div></section>
     <section class="card"><span class="eyebrow" style="color:#8E8C86">Late now</span><div class="list">${P.late.slice(0,5).map(t=>`<div class="li" style="border-color:#2A2A2C"><div class="grow small"><b style="font-weight:500">${esc(propById(t.propId).code)}</b> · ${esc(t.title)}</div><span class="st bad">${dur(Date.now()-dueOf(t))}</span></div>`).join('')||'<span class="muted small">Nothing late.</span>'}</div></section></div></div>`;motion($('#tv'),'tv','tv')}
function openTV(){$('#tv').hidden=false;moKeys.tv=null;renderTV();clearInterval(tvTimer);clearInterval(clockTimer);tvTimer=setInterval(()=>{if(!$('#tv').hidden)renderTV()},15000);clockTimer=setInterval(()=>{const c=$('#tv-clock');if(c)c.textContent=new Date().toLocaleTimeString(LOC())},1000);try{navigator.wakeLock&&navigator.wakeLock.request('screen').catch(()=>{})}catch(e){}}
function closeTV(){$('#tv').hidden=true;clearInterval(tvTimer);clearInterval(clockTimer);try{document.fullscreenElement&&document.exitFullscreen()}catch(e){}}

/* ================= global search ================= */
function searchDialog(q){const u=me();q=q.trim().toLowerCase();if(!q)return;const ids=propIds(u);const res=[];
  S.tickets.filter(t=>ids.has(t.propId)&&(t.id+' '+t.title).toLowerCase().includes(q)).slice(0,8).forEach(t=>res.push(['openTicket',t.id,'wrench',t.id+' · '+t.title,STAGE[t.status].l]));
  if(can(u,'units'))S.units.filter(x=>ids.has(x.propId)&&x.code.toLowerCase().includes(q)).slice(0,6).forEach(x=>res.push(['editUnit',x.id,'door',x.code,x.kind+' · '+x.status]));
  if(can(u,'tenants'))S.tenants.filter(t=>t.name.toLowerCase().includes(q)).slice(0,6).forEach(t=>res.push(['editTenant',t.id,'user',t.name,t.unitId&&unitById(t.unitId)?unitById(t.unitId).code:'']));
  if(can(u,'buildings'))S.props.filter(p=>ids.has(p.id)&&(p.name+' '+p.code).toLowerCase().includes(q)).slice(0,6).forEach(p=>res.push(['openProp',p.id,'bld',p.name,p.code]));
  if(can(u,'fleet'))S.vehicles.filter(v=>(v.plate+' '+v.make+' '+v.model).toLowerCase().includes(q)).slice(0,5).forEach(v=>res.push(['openVehicle',v.id,'truck',v.plate+' · '+v.make+' '+v.model,v.status]));
  if(can(u,'warehouse'))S.items.filter(i=>(i.name+' '+i.sku).toLowerCase().includes(q)).slice(0,5).forEach(i=>res.push(['openItem',i.id,'box',i.name,i.qty+' '+i.unit+' · '+i.store]));
  dialog(`${dHead('Search results','“'+esc(q)+'”')}<div class="d-body"><div class="list">${res.map(r=>`<div class="li click" data-act="${r[0]}" data-id="${esc(r[1])}"><span class="ibox">${ic(r[2])}</span><div class="grow"><div class="ttl clip">${esc(r[3])}</div><div class="tiny muted">${esc(r[4])}</div></div></div>`).join('')||empty('No matches.','search')}</div></div>`)}

/* ================= guided tour ================= */
const TOURS={
  office:[
    {title:'Welcome to Alkazemi Asset Management',body:'A quick tour of where everything is. Use Next to move on, or Skip to close it. You can replay it any time from your profile menu or the Help page.'},
    {sel:'[data-tour="nav"]',title:'Main menu',body:'Every screen you have access to is listed here, grouped by Overview, Property, Operations, Finance and Administration. What you see depends on your role.'},
    {sel:'[data-tour="scope"]',title:'Pick a building',body:'Choose one building to focus every screen on it, or keep All buildings to see the whole portfolio.'},
    {sel:'[data-tour="search"]',title:'Search anything',body:'Type a ticket number, unit code, tenant, plate number or stock item and press Enter.'},
    {view:'dashboard',sel:'[data-tour="strip"]',title:'Portfolio at a glance',body:'Jobs waiting for approval, the share fixed on time, occupancy and rent collected this month. The big numbers on the right show buildings, open jobs and jobs that are late right now.'},
    {view:'dashboard',sel:'[data-tour="queue"]',title:'Waiting on you',body:'Jobs that need your action, soonest deadline first. Tap one to open it and approve, assign or close it.'},
    {view:'dashboard',sel:'[data-tour="late"]',title:'Late jobs',body:'Anything past its 24 or 48-hour deadline. Alerts repeat by email, WhatsApp and in the platform until the job is closed.'},
    {view:'tickets',sel:'[data-tour="board"]',title:'Maintenance board',body:'Each column is one step of the approval chain: supervisor, manager, owner, technician, review and procurement. Cards show the deadline and what you need to do.'},
    {sel:'[data-tour="nav-escalations"]',title:'Late jobs & escalations',body:'See who a late job is stuck with, how many alerts went out and when the next one is due.'},
    {sel:'[data-tour="bell"]',title:'Notifications',body:'Approvals, late-job alerts and reminders arrive here instantly. The same alerts go to your email and WhatsApp.'},
    {sel:'[data-tour="help"]',title:'Help is always here',body:'Step-by-step guides for every screen and role, including the admin guide.'},
    {sel:'[data-tour="me"]',title:'Your profile',body:'Change how alerts reach you, switch to dark mode, replay this tour or sign out.'}],
  tech:[
    {title:'Welcome',body:'This short tour shows where your jobs are and how to record them. Use Next, or Skip to close.'},
    {view:'dashboard',sel:'[data-tour="queue"]',title:'My jobs',body:'Jobs assigned to you, soonest deadline first. Open one, press Start work when you arrive, and record the job done when finished.'},
    {sel:'[data-tour="nav-tickets"]',title:'Maintenance',body:'All your jobs on a board. Every job must be fixed within 24 or 48 hours of being reported.'},
    {sel:'[data-tour="nav-fleet"]',title:'Vehicle repairs',body:'If you work on vehicles, start and finish repair jobs here. A timer shows time against the expected hours.'},
    {sel:'[data-tour="bell"]',title:'Notifications',body:'New assignments and over-time alerts arrive here and on WhatsApp.'},
    {sel:'[data-tour="help"]',title:'Help',body:'Guides for recording jobs, using stock and vehicle repairs.'}],
  procurement:[
    {title:'Welcome',body:'A quick look at purchases and stores. Use Next, or Skip to close.'},
    {view:'dashboard',sel:'[data-tour="queue"]',title:'Purchases waiting',body:'Jobs the manager has sent to procurement. Open one, enter the supplier and amount, and approve it to close the job.'},
    {view:'warehouse',sel:'[data-tour="wtabs"]',title:'Warehouse',body:'Stock on hand, every movement, receiving goods and issuing stock to jobs. Items at or below their reorder level are flagged.'},
    {sel:'[data-tour="bell"]',title:'Notifications',body:'Low stock and purchase requests arrive here.'},
    {sel:'[data-tour="help"]',title:'Help',body:'Guides for stock, purchases and CSV formats.'}],
  guard:[
    {title:'Welcome',body:'This app is for reporting problems in your building. It takes three taps. Press Next to see how, or Skip to close.'},
    {sel:'[data-tour="gtiles"]',title:'Your tools',body:'Report an issue with a photo, run your patrol round, log visitors and confirm when a technician arrives.'},
    {sel:'[data-tour="sos"]',title:'Emergency',body:'For fire, flooding, lift entrapment or a security incident. It alerts the supervisor, managers and owners at once. If people are in danger, call 112 first.'},
    {sel:'[data-tour="patrol"]',title:'Patrol round',body:'Walk the building and mark each point OK or Issue. Every issue becomes a report automatically.'},
    {sel:'[data-tour="bell"]',title:'Messages',body:'You get a message when your report is approved and when the technician is on the way.'}]};
const tourKey=u=>u.role==='guard'?'guard':u.role==='tech'?'tech':u.role==='procurement'?'procurement':'office';
let tour=null,tourTimer=null;
function maybeTour(){const u=me();if(!u||tour)return;const seen=(u.tour&&u.tour.v2)||lsGet('akam-tour-'+u.id);if(seen||ui.tourSkipped)return;if(tourTimer&&tourTimer.u===u.id)return;if(tourTimer)clearTimeout(tourTimer.h);tourTimer={u:u.id,h:setTimeout(()=>{tourTimer=null;const s2=(u.tour&&u.tour.v2)||lsGet('akam-tour-'+u.id);if(!tour&&!s2&&!ui.tourSkipped&&me()===u)startTour()},700)}}
function startTour(){const u=me();ui.menu=false;closeLayer();tour={steps:(isAR()?TOURS_AR:TOURS)[tourKey(u)],i:0};showStep()}
function endTour(done){const u=me();tour=null;$('#tour').innerHTML='';$('#tour').hidden=true;ui.tourSkipped=true;if(u){u.tour=Object.assign({},u.tour,{v2:true});lsSet('akam-tour-'+u.id,'1');save()}if(done)toast('Tour finished. Find it again under Help.')}
function showStep(){if(!tour)return;const s=tour.steps[tour.i];
  if(s.view&&ui.view!==s.view&&me().role!=='guard'){ui.view=s.view;render()}
  const T=$('#tour');T.hidden=false;let el=s.sel?document.querySelector(s.sel):null;
  if(el&&(el.offsetParent===null||!el.getClientRects().length))el=null;
  if(el){try{el.scrollIntoView({block:'center',behavior:'instant'})}catch(e){el.scrollIntoView()}}
  const n=tour.steps.length;
  T.innerHTML=`<div class="tour-block"></div>${el?'<div class="tour-hole"></div>':'<div class="tour-hole" style="left:50%;top:50%;width:0;height:0"></div>'}<div class="tour-tip" role="dialog" aria-live="polite"><div class="spread"><span class="stepn">Step ${tour.i+1} of ${n}</span><div class="tour-dots">${tour.steps.map((_,i)=>`<i class="${i<=tour.i?'on':''}"></i>`).join('')}</div></div><h3>${esc(s.title)}</h3><p>${esc(s.body)}</p>
   <div class="spread"><button class="btn ghost sm" data-act="tourSkip">Skip tour</button><div class="row">${tour.i?`<button class="btn sm" data-act="tourBack">${ic('left')}Back</button>`:''}<button class="btn dark sm" data-act="tourNext">${tour.i===n-1?'Finish':'Next'}${tour.i===n-1?'':ic('right')}</button></div></div></div>`;
  placeTour(el);setTimeout(()=>{const b=T.querySelector('[data-act="tourNext"]');if(b)try{b.focus({preventScroll:true})}catch(e){}},30)}
function placeTour(el){const T=$('#tour');const hole=T.querySelector('.tour-hole'),tip=T.querySelector('.tour-tip');if(!tip)return;const W=window.innerWidth,H=window.innerHeight;
  if(!el){hole.style.cssText='left:50%;top:40%;width:0;height:0;';tip.style.left=Math.max(16,(W-tip.offsetWidth)/2)+'px';tip.style.top=Math.max(16,(H-tip.offsetHeight)/2)+'px';return}
  const r=el.getBoundingClientRect();const pad=6;hole.style.left=(r.left-pad)+'px';hole.style.top=(r.top-pad)+'px';hole.style.width=(r.width+pad*2)+'px';hole.style.height=(r.height+pad*2)+'px';
  const tw=tip.offsetWidth,th=tip.offsetHeight;let top=r.bottom+14;if(top+th>H-12)top=r.top-th-14;if(top<12)top=Math.min(H-th-12,Math.max(12,r.top+12));
  let left=r.left;if(r.width>W*.5)left=r.left+r.width/2-tw/2;if(left+tw>W-12)left=W-tw-12;if(left<12)left=12;
  if(r.right+tw+20<W&&r.height>H*.5){left=r.right+16;top=Math.max(12,Math.min(H-th-12,r.top+40))}
  tip.style.left=left+'px';tip.style.top=top+'px'}
window.addEventListener('resize',()=>{if(tour)showStep()});

/* ================= help centre ================= */
const flow=(...a)=>`<div class="flow">${a.map((x,i)=>(i?'<em>→</em>':'')+`<span class="${x[0]==='*'?'k':''}">${x.replace(/^\*/,'')}</span>`).join('')}</div>`;
const HELP=[
 {g:'Getting started',id:'start',t:'Welcome',tour:true,h:()=>`<p>Alkazemi Asset Management runs the day-to-day operation of the Al-Kazemi portfolio: buildings, apartments and leases, maintenance from report to repair, vacant unit inspections, warehouse stock and the vehicle fleet.</p>
  <h3>Finding your way</h3><ul><li><b>Menu</b> on the left (on phones, the bottom bar and the <b>More</b> button).</li><li><b>Building switcher</b> at the top: pick one building to focus every screen on it.</li><li><b>Search</b>: type a ticket number, unit code, tenant name, plate number or stock item and press Enter.</li><li><b>Bell</b>: approvals, late-job alerts and reminders. The same alerts go to email and WhatsApp.</li><li><b>Your name</b> (top right): alert preferences, dark mode, the tour, sign out.</li></ul>
  <h3>On a phone or tablet</h3><p>Open the link in Safari or Chrome and choose <b>Add to Home Screen</b>. It then opens full screen like an app. Guards get a simplified app with big buttons.</p>`},
 {g:'Getting started',id:'roles',t:'Roles and responsibilities',h:()=>`<table class="report" style="border:0;padding:0"><thead><tr><th>Role</th><th>Does</th></tr></thead><tbody>
  <tr><td>Security guard</td><td>Reports issues with photos, patrols, logs visitors and contractors, confirms technician arrival, raises emergencies, checks vacant units.</td></tr>
  <tr><td>Building supervisor</td><td>Pre-approves guard reports with a cost estimate, manages tenants for their buildings, runs inspections.</td></tr>
  <tr><td>Operations manager</td><td>Approves jobs, picks the technician, reviews finished work, sends purchases to procurement, manages the fleet.</td></tr>
  <tr><td>Owner / management</td><td>Gives final approval before work starts, sees all reports and the live wall.</td></tr>
  <tr><td>Technician</td><td>Starts the job on site, records the work, materials, cost and after photos. Fleet mechanics run vehicle repairs.</td></tr>
  <tr><td>Procurement & stores</td><td>Approves purchases, receives goods, keeps stock levels.</td></tr>
  <tr><td>Administrator</td><td>Users, permissions, buildings, settings and alert delivery.</td></tr></tbody></table>`},
 {g:'Getting started',id:'workflow',t:'The approval chain',h:()=>`<p>Every maintenance job follows the same path:</p>${flow('Guard reports','*Supervisor pre-approves','*Manager approves','*Owner approves','Technician fixes','Manager reviews','Closed')}
  <ol><li><b>Reported.</b> The guard (or anyone) reports the issue with a photo. The building supervisor is alerted.</li><li><b>Supervisor pre-approval.</b> The supervisor checks the photos, sets the category and urgency and enters a cost estimate.</li><li><b>Manager approval.</b> The operations manager approves and chooses the technician.</li><li><b>Owner approval.</b> The owner gives final approval. An administrator can set a cost limit below which owner approval is skipped (Settings).</li><li><b>Technician.</b> Starts work on site (the guard confirms arrival), then records the job done with materials, cost and after photos.</li><li><b>Review.</b> The manager closes the job, or sends it to procurement if items must be bought. Procurement approves the purchase and the job closes.</li></ol>
  <p>Any approver can <b>reject</b> with a reason; the reporter and supervisor are told. Reports raised by a supervisor or manager skip the supervisor step.</p>`},
 {g:'Getting started',id:'sla',t:'Deadlines and late-job alerts',h:()=>`<p>Every job must be fixed within <b>${setting('slaUrgentH')} hours</b> (Emergency and Urgent) or <b>${setting('slaNormalH')} hours</b> (Normal and Planned). The clock starts when the issue is reported, so approval time counts.</p>
  <h3>When a job is late</h3><ul><li>An alert goes to the building supervisor, operations managers and owners, by email, WhatsApp and in the platform.</li><li>It repeats every <b>${setting('repeatH')} hours</b> until the job is closed or rejected.</li><li>The alert says how late the job is and who it is waiting on.</li><li><b>Late jobs</b> in the menu lists every late job, the alert count and the next alert time. Managers can send an alert immediately.</li></ul>
  <h3>Vehicle repairs</h3><p>Each repair job has an expected time. When it runs over, the worker and the operations manager are alerted every ${setting('vehicleRepeatH')} hours until it is finished.</p>`},
 {g:'Daily work',id:'guard',t:'Security guard guide',roles:['guard'],h:()=>`<ol><li><b>Report an issue:</b> tap Report, choose the apartment (or a common area), choose what is wrong, take a photo, choose how urgent, send. Your supervisor is alerted.</li><li><b>Emergency:</b> fire, flood, power failure, lift entrapment or security incident. Everyone is alerted at once. Call <b>112</b> first if people are in danger.</li><li><b>Patrol round:</b> mark each check point OK, Issue or N/A. Each Issue becomes a report automatically.</li><li><b>Visitors & contractors:</b> check people in with their company, purpose and apartment, and check them out when they leave.</li><li><b>Technician arrival:</b> when the technician arrives for a job, tap Arrived. The supervisor sees the time.</li><li><b>Vacant unit check:</b> photos of every room of an empty apartment, with any damage.</li></ol>`},
 {g:'Daily work',id:'report',t:'Reporting an issue',h:()=>`${flow('Building & apartment','What is wrong','Photos','Details','Send')}<p>Open <b>Report an issue</b>. Pick the building, then tap the apartment on the floor plan, or a common area such as the roof or parking. Choose the category, add photos or a short video, write a title and choose the urgency. Emergency and Urgent jobs must be fixed within ${setting('slaUrgentH')} hours, Normal and Planned within ${setting('slaNormalH')}.</p>`},
 {g:'Daily work',id:'approve',t:'Approving jobs',h:()=>`<p>Open a job from <b>Waiting on you</b> on the dashboard, the bell, or the Maintenance board. The panel at the top shows exactly what you need to do.</p><ul><li><b>Supervisor:</b> confirm category and urgency, enter the estimate, Pre-approve.</li><li><b>Manager:</b> choose the technician (the right trade is suggested), Approve.</li><li><b>Owner:</b> check the estimate and approvals, Give final approval.</li></ul><p>To reject, press Reject and give a reason. The deadline keeps running while a job waits for approval.</p>`},
 {g:'Daily work',id:'tech',t:'Technician guide',roles:['tech'],h:()=>`<ol><li>Open the job from <b>My jobs</b>.</li><li>Press <b>Start work on site</b> when you arrive.</li><li>When finished, fill <b>Record the job done</b>: what you did, materials (pick from the warehouse list to deduct stock), labour cost, after photos. Tick "Items must be purchased" if something needs buying.</li><li>The manager reviews and closes it.</li></ol>`},
 {g:'Daily work',id:'inspections',t:'Vacant unit inspections',h:()=>`<p>Inspect every vacant apartment before it is re-let.</p><ol><li><b>Vacant inspections → New inspection</b>, or the Inspect button on a vacant unit.</li><li>Pick the building and the vacant apartment on the floor plan.</li><li>Go room by room: set Good, Fair or Damaged, add photos, and list each damage with an estimated cost.</li><li>Enter meter readings and keys, write a summary, submit.</li></ol><p>The report can be printed or saved as PDF. A supervisor or manager reviews it and can turn each damage into a repair ticket in one step.</p>`},
 {g:'Daily work',id:'warehouse',t:'Warehouse and stock',h:()=>`<ul><li><b>Stock on hand</b> shows quantity, reorder level and value for each item in each store.</li><li><b>Receive goods</b> adds quantity from a purchase order or delivery note.</li><li><b>Issue to job</b> takes stock out against a maintenance ticket. Technicians can also do this when they record a job.</li><li>Open an item to do a <b>stock count</b> and see every movement.</li><li>When an item reaches its reorder level, procurement gets an alert.</li></ul>`},
 {g:'Daily work',id:'fleet',t:'Fleet and repair timers',h:()=>`<ul><li><b>Vehicles</b>: plate, driver, odometer, next service, registration (Daftar) and insurance expiry. Expiring documents trigger reminders.</li><li><b>Open repair job</b>: choose the vehicle, type, worker, garage and the expected hours.</li><li>The worker presses <b>Start repair</b>; a dial shows time used against the expected time.</li><li>If it runs over, the worker and manager are alerted repeatedly until it is marked finished with the cost.</li><li><b>Repair times</b> compares expected and actual hours by job type and garage.</li></ul>`},
 {g:'Daily work',id:'property',t:'Buildings, units and tenants',h:()=>`<ul><li><b>Buildings</b>: each building's details, floor-by-floor stacking plan, statutory documents with expiry dates, planned maintenance, jobs and team.</li><li><b>Units & leases</b>: every unit with rental or lease, rent, tenant and lease end. Pick a building to see its stacking plan.</li><li><b>Tenants</b>: contact and ID details, deposit, payment frequency, lease registration and rent history.</li></ul>`},
 {g:'Daily work',id:'rent',t:'Rent collection',h:()=>`<p>Rent is collected outside the platform. Record each payment with <b>Mark paid</b> (amount, date, method and reference) and a receipt number is issued. To record many at once, use <b>Import CSV</b> with these columns:</p><p class="mono small">unit_code, month (YYYY-MM), amount, paid_on (YYYY-MM-DD), method, reference</p><p>Unpaid rent more than 5 days past the due date appears in reminders.</p>`},
 {g:'Daily work',id:'reports',t:'Reports and the live wall',h:()=>`<p><b>Reports</b> shows jobs raised and closed, the share fixed within the deadline, where jobs wait longest in the approval chain, cost by category, technician performance and pending versus done for each building. Export to CSV for Excel.</p><p><b>Live wall</b> is a full-screen view for a TV in the operations room. It refreshes every 15 seconds.</p>`},
 {g:'Administration guide',id:'admin-users',t:'Users and permissions',roles:['admin'],h:()=>`<ol><li>Go to <b>Users & permissions → Add user</b>.</li><li>Enter name, email (used to sign in) and mobile (used for WhatsApp alerts).</li><li>Choose a role. The role switches on its usual screens and actions; you can tick or untick any of them for this person.</li><li>For supervisors and guards, tick the buildings they cover. They only see those buildings.</li><li>For technicians, tick their trades so the right person is suggested for each job.</li><li>Set a password (default <span class="mono">demo123</span>) and save. Untick <b>Account active</b> to disable someone.</li></ol>`},
 {g:'Administration guide',id:'admin-buildings',t:'Setting up a building',roles:['admin'],h:()=>`<ol><li><b>Buildings → Add building</b>: name, category (Residential, Commercial, Office, Retail, Industrial & Logistics, Mixed Portfolio), country, address, supervisor and guard.</li><li>The country's document checklist (for Kuwait: title deed, municipality permit, KFSD fire certificate, PACI, MEW, insurance, lift certificate) and the planned maintenance schedule are created automatically.</li><li>Open the building's <b>Floors & units</b> tab and use the building module: from floor, to floor, units per floor, type, rental or lease, area and rent.</li><li>Upload documents with expiry dates on the <b>Documents</b> tab.</li></ol>`},
 {g:'Administration guide',id:'admin-settings',t:'Deadlines, approvals and alerts',roles:['admin'],h:()=>`<ul><li><b>Fix deadlines</b>: hours for Emergency/Urgent and Normal/Planned jobs (default 24 and 48).</li><li><b>Late-job alerts</b>: how often alerts repeat and which roles receive them.</li><li><b>Owner approval limit</b>: 0 means the owner approves every job; set an amount to let cheaper jobs skip owner approval.</li><li><b>Alert channels</b>: switch email or WhatsApp on or off for everyone. Each person can also turn them off in their profile.</li></ul>`},
 {g:'Administration guide',id:'admin-alerts',t:'Connecting email and WhatsApp',roles:['admin'],h:()=>`<p>Alerts are queued in the database and sent by a server function every few minutes. Until sending accounts are connected they show as <b>Waiting for sending keys</b> in Alerts & messages.</p><ol><li><b>Email:</b> create a Resend account, verify the sending domain, create an API key.</li><li><b>WhatsApp:</b> in Twilio, register a WhatsApp sender for the company number and note the Account SID and Auth Token. Meta requires approved message templates for messages sent outside a 24-hour conversation.</li><li>In Supabase → Edge Functions → Secrets add <span class="mono">RESEND_API_KEY</span>, <span class="mono">ALERT_FROM_EMAIL</span>, <span class="mono">TWILIO_ACCOUNT_SID</span>, <span class="mono">TWILIO_AUTH_TOKEN</span>, <span class="mono">TWILIO_WHATSAPP_FROM</span>.</li><li>Settings shows a green check for each channel once the keys are found. Messages queued in the last 24 hours are then sent.</li></ol>`},
 {g:'Administration guide',id:'admin-data',t:'Data, exports and security',roles:['admin'],h:()=>`<ul><li>All data lives in the Supabase project of the Alkazemi organization, in its own section. Photos and documents are stored in Supabase Storage.</li><li>Export rent and report tables to CSV from their screens.</li><li>Every action is recorded in the audit trail (Reports).</li><li>This demo signs people in with a password checked by the database. Before loading real tenant data, switch to Supabase Auth with per-role database rules, and enable two-factor sign-in for administrators.</li></ul>`},
 {g:'Administration guide',id:'faq',t:'Questions',h:()=>`<h3>Why did I get the same alert again?</h3><p>Late-job alerts repeat every ${setting('repeatH')} hours until the job is closed. Close or reject the job to stop them.</p><h3>Can I approve from my phone?</h3><p>Yes. Open the alert link or the platform on your phone and use the same buttons.</p><h3>The page says demo mode.</h3><p>The shared database could not be reached. Changes stay on your device until it reconnects. Press Reconnect.</p><h3>How do I print an inspection report?</h3><p>Open the report and press Print or save PDF.</p>`}];
function helpBody(roleFilter){const u=me();const list=HELP.map(helpL).filter(a=>!a.roles||u.role==='admin'||a.roles.includes(u.role)||(roleFilter&&a.roles.includes(roleFilter)));
  const q=(ui.f.hq||'').toLowerCase();const shown=q?list.filter(a=>(a.t+' '+a.h().replace(/<[^>]+>/g,' ')).toLowerCase().includes(q)):list;
  let cur=shown.find(a=>a.id===ui.helpId)||shown[0];if(roleFilter==='guard'&&!ui.helpPicked)cur=helpL(HELP.find(a=>a.id==='guard'));
  const groups=[...new Set(shown.map(a=>a.g))];
  return `<div class="stack"><div class="spread"><label class="search" style="width:min(380px,100%)">${ic('search')}<input id="hq" data-input="f" data-k="hq" placeholder="Search the guide" value="${esc(ui.f.hq||'')}"></label><button class="btn dark" data-act="tourStart">${ic('play')}Start the guided tour</button></div>
   <div class="help"><nav class="help-nav">${groups.map(g=>`<span class="hs">${g}</span>${shown.filter(a=>a.g===g).map(a=>`<button class="${cur&&a.id===cur.id?'on':''}" data-act="helpOpen" data-id="${a.id}">${esc(a.t)}</button>`).join('')}`).join('')}</nav>
   <article class="card article">${cur?`<span class="eyebrow">${esc(cur.g)}</span><h2>${esc(cur.t)}</h2>${cur.h()}${cur.tour?`<div class="row"><button class="btn gold" data-act="tourStart">${ic('play')}Show me around</button></div>`:''}`:empty('Nothing matches that search.','search')}</article></div></div>`}
function viewHelp(u){return helpBody()}

