  inspReview:d=>{const i=S.insp.find(x=>x.id===d.id);i.status='reviewed';i.reviewedBy=S.session;i.reviewedAt=nowISO();notify([i.inspectorId],'Inspection '+i.id+' reviewed',{view:'inspections'},'Inspection reviewed · '+i.id,'Your inspection of '+(unitById(i.unitId)||{}).code+' was reviewed by '+nameOf(S.session)+'.',{whatsapp:false});logAct('Reviewed inspection '+i.id);save();inspectionDrawer(i.id);render()},
  inspTickets:d=>{const i=S.insp.find(x=>x.id===d.id);const x=unitById(i.unitId);let n=0;i.rooms.forEach(r=>r.damages.forEach(dm=>{if(!dm.item)return;const t=newTicket({propId:i.propId,unitId:i.unitId,category:damageCat(dm.item),priority:'P4',title:dm.item+' · '+r.name,location:'Unit '+x.no+' · '+r.name,desc:'From vacant inspection '+i.id,estCost:+dm.cost||0,media:r.photos.slice(0,2)});i.ticketIds.push(t.id);n++}));
    if(i.status==='submitted'){i.status='reviewed';i.reviewedBy=S.session;i.reviewedAt=nowISO()}save();toast(n+' repair tickets created');inspectionDrawer(i.id);render()},
