  patrolSubmit:()=>{const w=ui.wiz.patrol;const u=me();const p=propById(w.propId);
    const rec={id:uid('PR'),propId:p.id,guardId:u.id,at:nowISO(),checks:w.checks.map(c=>({point:c.point,res:c.res,note:c.note})),durationMin:Math.max(1,Math.round((Date.now()-w.start)/MIN))};
    w.checks.filter(c=>c.res==='issue').forEach(c=>{const t=newTicket({propId:p.id,category:PATROL_CAT[c.point]||'Civil & Painting',priority:'P3',title:(c.note||'Issue found')+' · '+c.point,location:c.point,desc:'Found during patrol round',media:c.photos});rec.checks.find(x=>x.point===c.point).ticketId=t.id});
    S.patrols.unshift(rec);logAct('Patrol round at '+p.code+' ('+rec.checks.filter(c=>c.res==='issue').length+' issues)');ui.wiz.patrol=null;save();closeLayer();render();toast('Patrol saved')},
  visitors:()=>visitorsDrawer(),
  visitorOut:d=>{const v=S.visitors.find(x=>x.id===d.id);v.outAt=nowISO();save();visitorsDrawer();render()},
